75: // Wrap public browser APIs so CLI screenshot, run-code, and locator captures
76: // use the same provenance, including captures that never become OC attachments.
77: function instrument(playwright, env = process.env) {
78:   const patched = Symbol.for('omgithub.wipScreenshot')
79:   function patchScreenshot(prototype, pageFor) {
80:     if (!prototype?.screenshot || prototype.screenshot[patched]) return
81:     const original = prototype.screenshot
82:     const wrapped = async function (...args) {
83:       const page = pageFor(this), page_url = page.url(), captured_at = Date.now()
84:       const bytes = await original.apply(this, args)
85:       if (page.url() === page_url) {
86:         try { queueScreenshot(bytes, { page_url, captured_at, browser_session: env.OMGITHUB_BROWSER_SESSION || '', session_id: env.OPENCODE_SESSION_ID || '' }, env) }
87:         catch (error) { console.error('WIP capture deferred:', error.message) }
88:       }
89:       return bytes
90:     }
91:     wrapped[patched] = true
92:     prototype.screenshot = wrapped
93:   }
94:   function pageReady(page) {
95:     patchScreenshot(Object.getPrototypeOf(page), page => page)
96:     patchScreenshot(Object.getPrototypeOf(page.locator('html')), locator => locator.page())
97:   }
98:   function contextReady(context) {
99:     for (const page of context.pages()) pageReady(page)
100:     context.on('page', pageReady)
101:     return context
102:   }
103:   function browserReady(browser) {
104:     for (const context of browser.contexts()) contextReady(context)
105:     const original = browser.newContext.bind(browser)
106:     browser.newContext = async (...args) => contextReady(await original(...args))
107:     return browser
108:   }
109:   for (const type of [playwright.chromium, playwright.firefox, playwright.webkit].filter(Boolean)) {
110:     for (const name of ['launch', 'connect', 'connectOverCDP', 'launchPersistentContext']) {
111:       if (!type[name] || type[name][patched]) continue
112:       const original = type[name].bind(type)
113:       const wrapped = async (...args) => name === 'launchPersistentContext' ? contextReady(await original(...args)) : browserReady(await original(...args))
114:       wrapped[patched] = true; type[name] = wrapped
115:     }
116:   }
117: }
118: module.exports = { projectOrigins, controllerPorts, skipReason, isProjectPage, imageType, queueScreenshot, instrument, webDirectory }

