// Utilidades matemáticas y de azar determinista.
export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a || 1);
export const smoothstep = (a, b, v) => {
  const t = clamp(invLerp(a, b, v), 0, 1);
  return t * t * (3 - 2 * t);
};
export const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
export const dist2 = (ax, ay, bx, by) => {
  const dx = bx - ax, dy = by - ay;
  return dx * dx + dy * dy;
};
export const angleDiff = (a, b) => {
  let d = (b - a + Math.PI) % TAU;
  if (d < 0) d += TAU;
  return d - Math.PI;
};
export const angleLerp = (a, b, t) => a + angleDiff(a, b) * t;
export const approach = (v, target, delta) => {
  if (v < target) return Math.min(v + delta, target);
  return Math.max(v - delta, target);
};
export const randRange = (rng, a, b) => a + rng() * (b - a);
export const pick = (rng, arr) => arr[Math.floor(rng() * arr.length) % arr.length];
export const shuffle = (rng, arr) => {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hash2(x, y, seed = 0) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

function smooth(t) { return t * t * (3 - 2 * t); }

export function valueNoise(x, y, seed = 0) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const a = hash2(xi, yi, seed), b = hash2(xi + 1, yi, seed);
  const c = hash2(xi, yi + 1, seed), d = hash2(xi + 1, yi + 1, seed);
  const u = smooth(xf), v = smooth(yf);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}

export function fbm(x, y, seed = 0, octaves = 4) {
  let value = 0, amp = 0.5, freq = 1, total = 0;
  for (let i = 0; i < octaves; i++) {
    value += valueNoise(x * freq, y * freq, seed + i * 101) * amp;
    total += amp;
    amp *= 0.5;
    freq *= 2;
  }
  return value / total;
}

export function formatTime(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), r = s % 60;
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}` : `${m}:${String(r).padStart(2, '0')}`;
}

export function deepClone(obj) {
  if (typeof structuredClone === 'function') return structuredClone(obj);
  return JSON.parse(JSON.stringify(obj));
}

export function rectCircle(rect, cx, cy, r) {
  const nx = clamp(cx, rect.x, rect.x + rect.w);
  const ny = clamp(cy, rect.y, rect.y + rect.h);
  return dist2(nx, ny, cx, cy) <= r * r;
}

export function seededColor(seed, hueBase = 0, hueRange = 360, sat = 60, light = 55) {
  const h = (hueBase + hash2(seed, 7, 11) * hueRange) % 360;
  return `hsl(${h.toFixed(0)} ${sat}% ${light}%)`;
}

export class EventBus {
  constructor() { this.map = new Map(); }
  on(type, fn) {
    if (!this.map.has(type)) this.map.set(type, new Set());
    this.map.get(type).add(fn);
    return () => this.map.get(type)?.delete(fn);
  }
  emit(type, data) {
    const set = this.map.get(type);
    if (set) for (const fn of [...set]) { try { fn(data); } catch (e) { console.error(e); } }
    const all = this.map.get('*');
    if (all) for (const fn of [...all]) { try { fn({ type, data }); } catch (e) { console.error(e); } }
  }
}

// Interpolación de color hexadecimal sencilla.
export function hexToRgb(hex) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map(c => c + c).join('') : h, 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}
export function rgba(hex, a = 1) {
  const c = hexToRgb(hex);
  return `rgba(${c.r},${c.g},${c.b},${a})`;
}
export function mixHex(a, b, t) {
  const A = hexToRgb(a), B = hexToRgb(b);
  const c = (x, y) => Math.round(lerp(x, y, t)).toString(16).padStart(2, '0');
  return `#${c(A.r, B.r)}${c(A.g, B.g)}${c(A.b, B.b)}`;
}

export function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = Math.max(1, Math.round(w));
  c.height = Math.max(1, Math.round(h));
  return c;
}

export function roundedRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function roman(n) {
  const map = [[10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']];
  let out = '';
  for (const [v, s] of map) while (n >= v) { out += s; n -= v; }
  return out;
}

// Entrada unificada: teclado, ratón, táctil y mando.
const KEYMAP = {
  ArrowUp: 'up', KeyW: 'up',
  ArrowDown: 'down', KeyS: 'down',
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ShiftLeft: 'run', ShiftRight: 'run',
  KeyJ: 'attack', KeyK: 'heavy', Space: 'dodge',
  KeyL: 'block', KeyE: 'interact', KeyU: 'spell',
  Digit1: 'spell1', Digit2: 'spell2', Digit3: 'spell3',
  KeyC: 'companion', KeyR: 'ultimate', KeyQ: 'potion',
  Tab: 'menu', Escape: 'menu', KeyM: 'map',
  KeyP: 'pause',
};

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.virtual = new Set();
    this.pressed = new Set();
    this.released = new Set();
    this.mouse = { x: 0, y: 0, worldX: 0, worldY: 0, down: false };
    this.joystick = { x: 0, y: 0, active: false };
    this.touchMode = false;
    this.enabled = true;
    this.gamepad = null;
    this._bind();
  }

  _bind() {
    window.addEventListener('keydown', (e) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement || e.target?.isContentEditable) return;
      const action = KEYMAP[e.code];
      if (!action) return;
      if (['Tab', 'Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      if (!this.keys.has(action)) this._press(action);
      this.keys.add(action);
    });
    window.addEventListener('keyup', (e) => {
      const action = KEYMAP[e.code];
      if (!action) return;
      this.keys.delete(action);
      if (!this.virtual.has(action)) this._release(action);
    });
    window.addEventListener('blur', () => this.clear());
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.clear(); });

    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('pointermove', (e) => {
      const r = this.canvas.getBoundingClientRect();
      this.mouse.x = e.clientX - r.left;
      this.mouse.y = e.clientY - r.top;
      this.mouse.worldX = this.mouse.x;
      this.mouse.worldY = this.mouse.y;
    });
    this.canvas.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'touch') return;
      const r = this.canvas.getBoundingClientRect();
      this.mouse.x = e.clientX - r.left;
      this.mouse.y = e.clientY - r.top;
      this.mouse.down = true;
      if (e.button === 0) this._press('attack');
      if (e.button === 2) this._press('dodge');
    });
    window.addEventListener('pointerup', (e) => {
      if (e.pointerType === 'touch') return;
      this.mouse.down = false;
      if (e.button === 0) this._release('attack');
      if (e.button === 2) this._release('dodge');
    });

    window.addEventListener('gamepadconnected', (e) => { this.gamepad = e.gamepad; });
    window.addEventListener('gamepaddisconnected', () => { this.gamepad = null; });
  }

  bindTouch({ joystick, knob, buttons }) {
    this.touchMode = true;
    if (joystick && knob) {
      let pointerId = null;
      const update = (e) => {
        const r = joystick.getBoundingClientRect();
        const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        let dx = (e.clientX - cx) / (r.width * 0.42);
        let dy = (e.clientY - cy) / (r.height * 0.42);
        const len = Math.hypot(dx, dy);
        if (len > 1) { dx /= len; dy /= len; }
        this.joystick.x = dx; this.joystick.y = dy; this.joystick.active = true;
        knob.style.transform = `translate(${dx * 32}px, ${dy * 32}px)`;
        joystick.classList.add('active');
      };
      joystick.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        pointerId = e.pointerId;
        joystick.setPointerCapture(pointerId);
        update(e);
      });
      joystick.addEventListener('pointermove', (e) => {
        if (pointerId !== e.pointerId) return;
        e.preventDefault();
        update(e);
      });
      const end = (e) => {
        if (pointerId !== e.pointerId) return;
        pointerId = null;
        this.joystick.x = 0; this.joystick.y = 0; this.joystick.active = false;
        knob.style.transform = 'translate(0,0)';
        joystick.classList.remove('active');
      };
      joystick.addEventListener('pointerup', end);
      joystick.addEventListener('pointercancel', end);
      joystick.addEventListener('lostpointercapture', end);
    }
    for (const btn of buttons) {
      const action = btn.dataset.action;
      if (!action) continue;
      const down = (e) => {
        e.preventDefault();
        btn.setPointerCapture?.(e.pointerId);
        btn.classList.add('pressed');
        this.virtual.add(action);
        this._press(action);
      };
      const up = (e) => {
        e.preventDefault();
        btn.classList.remove('pressed');
        this.virtual.delete(action);
        this._release(action);
      };
      btn.addEventListener('pointerdown', down);
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('lostpointercapture', up);
      btn.addEventListener('contextmenu', (e) => e.preventDefault());
    }
  }

  _press(action) {
    if (!this.enabled) return;
    this.pressed.add(action);
  }
  _release(action) {
    this.released.add(action);
  }

  down(action) {
    return this.enabled && (this.keys.has(action) || this.virtual.has(action) || this._padDown(action));
  }
  justPressed(action) {
    return this.enabled && this.pressed.has(action);
  }
  justReleased(action) {
    return this.enabled && this.released.has(action);
  }
  consume(action) {
    const had = this.pressed.has(action);
    this.pressed.delete(action);
    return had;
  }

  axis() {
    let x = 0, y = 0;
    if (this.down('left')) x -= 1;
    if (this.down('right')) x += 1;
    if (this.down('up')) y -= 1;
    if (this.down('down')) y += 1;
    if (this.joystick.active) { x += this.joystick.x; y += this.joystick.y; }
    const pad = this._pad();
    if (pad) {
      const ax = pad.axes[0] || 0, ay = pad.axes[1] || 0;
      if (Math.abs(ax) > 0.18) x += ax;
      if (Math.abs(ay) > 0.18) y += ay;
    }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    return { x, y, len: Math.min(1, len) };
  }

  _pad() {
    if (!this.gamepad) {
      const pads = navigator.getGamepads?.() || [];
      this.gamepad = [...pads].find(p => p && p.connected) || null;
    }
    return this.gamepad;
  }
  _padDown(action) {
    const pad = this._pad();
    if (!pad) return false;
    const map = { attack: [0], dodge: [1], interact: [2], spell: [3], block: [4], companion: [5], ultimate: [6], potion: [7], menu: [9] };
    return (map[action] || []).some(i => pad.buttons[i]?.pressed);
  }

  pollGamepad() {
    const pad = this._pad();
    if (!pad) return;
    const map = { attack: [0], dodge: [1], interact: [2], spell: [3], block: [4], companion: [5], ultimate: [6], potion: [7], menu: [9] };
    for (const [action, buttons] of Object.entries(map)) {
      const isDown = buttons.some(i => pad.buttons[i]?.pressed);
      const was = this.virtual.has('pad:' + action);
      if (isDown && !was) { this.virtual.add('pad:' + action); this._press(action); }
      if (!isDown && was) { this.virtual.delete('pad:' + action); this._release(action); }
    }
  }

  clear() {
    this.keys.clear();
    this.virtual.clear();
    this.pressed.clear();
    this.released.clear();
    this.joystick.x = 0; this.joystick.y = 0; this.joystick.active = false;
    document.querySelectorAll('.touch-btn.pressed').forEach(b => b.classList.remove('pressed'));
  }

  endFrame() {
    this.pressed.clear();
    this.released.clear();
  }
}

