const midiToFreq = (m) => 440 * Math.pow(2, (m - 69) / 12);

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.master = null;
    this.musicBus = null;
    this.sfxBus = null;
    this.trackName = null;
    this.track = null;
    this.combat = false;
    this.timer = null;
    this.nextBarTime = 0;
    this.bar = 0;
    this.volumes = { master: 0.8, music: 0.55, sfx: 0.7 };
    this.noiseBuffer = null;
    this.suspended = false;
    this.intensity = 0;
    this._musicFade = null;
  }

  async init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 22;
    comp.ratio.value = 4;
    comp.attack.value = 0.004;
    comp.release.value = 0.25;
    comp.connect(this.ctx.destination);
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volumes.master;
    this.master.connect(comp);
    this.musicBus = this.ctx.createGain();
    this.musicBus.gain.value = this.volumes.music;
    this.musicBus.connect(this.master);
    this.sfxBus = this.ctx.createGain();
    this.sfxBus.gain.value = this.volumes.sfx;
    this.sfxBus.connect(this.master);
    this.ready = true;
    this._makeNoise();
    this._scheduleLoop();
    if (this.trackName) this._startTrack(this.trackName);
  }

  _makeNoise() {
    const len = this.ctx.sampleRate * 1.2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buf;
  }

  setVolumes(v) {
    Object.assign(this.volumes, v);
    if (!this.ready) return;
    this.master.gain.setTargetAtTime(this.volumes.master, this.ctx.currentTime, 0.05);
    this.musicBus.gain.setTargetAtTime(this.volumes.music, this.ctx.currentTime, 0.05);
    this.sfxBus.gain.setTargetAtTime(this.volumes.sfx, this.ctx.currentTime, 0.05);
  }

  setTrack(name, { combat = false, restart = false } = {}) {
    const full = combat && TRACKS[name + 'Combat'] ? name + 'Combat' : name;
    this.combat = combat;
    if (full === this.trackName && !restart) return;
    this.trackName = full;
    this.track = TRACKS[full] || TRACKS.title;
    if (this.ready) this._startTrack(full);
  }

  _startTrack(name) {
    if (!this.ready) return;
    this.trackName = name;
    this.track = TRACKS[name] || TRACKS.title;
    this.bar = 0;
    this.nextBarTime = this.ctx.currentTime + 0.08;
  }

  _scheduleLoop() {
    if (this.timer) return;
    this.timer = setInterval(() => {
      if (!this.ready || this.suspended || !this.track) return;
      const now = this.ctx.currentTime;
      const spb = 60 / this.track.bpm;
      const barDur = spb * 4;
      while (this.nextBarTime < now + 0.5) {
        this._scheduleBar(this.nextBarTime, this.track, this.bar);
        this.nextBarTime += barDur;
        this.bar++;
      }
    }, 80);
  }

  _scheduleBar(t, tr, barIndex) {
    const spb = 60 / tr.bpm;
    const scale = SCALES[tr.scale] || SCALES.aeolian;
    const prog = tr.progression[barIndex % tr.progression.length];
    const chordRoot = tr.root + prog;
    const combat = this.combat || tr.mood === 'boss';
    // Pad armónico.
    if (tr.pad) {
      const notes = [0, 2, 4].map((n, i) => chordRoot + scale[(prog + n) % scale.length] + (n >= 4 ? 12 : 0));
      notes.forEach((m, i) => this._note(t + i * 0.03, midiToFreq(m), spb * 4, tr.pad.wave, tr.pad.gain * (0.8 + Math.random() * 0.3), {
        attack: tr.pad.attack, release: tr.pad.release, detune: tr.pad.detune, filter: 900 + i * 180, music: true,
      }));
    }
    // Bajo.
    if (tr.bass) {
      this._note(t, midiToFreq(chordRoot + tr.bass.octave * 12), spb * 3.7, tr.bass.wave, tr.bass.gain, {
        attack: 0.02, release: 0.7, filter: 300, music: true,
      });
      if (combat) this._note(t + spb * 2, midiToFreq(chordRoot + tr.bass.octave * 12), spb * 1.6, tr.bass.wave, tr.bass.gain * 0.8, { attack: 0.01, release: 0.4, filter: 280, music: true });
    }
    // Arpegio.
    if (tr.arp) {
      const steps = 8;
      for (let i = 0; i < steps; i++) {
        if (!combat && i % 2 === 1 && Math.random() < 0.3) continue;
        const pattern = tr.arp.pattern[i % tr.arp.pattern.length];
        const midi = chordRoot + scale[pattern % scale.length] + tr.arp.octave * 12;
        this._note(t + i * (spb * 4 / steps), midiToFreq(midi), spb * (combat ? 0.45 : 0.9), tr.arp.wave, tr.arp.gain * (0.7 + Math.random() * 0.4), {
          attack: 0.005, release: 0.35, filter: 1800, music: true,
        });
      }
    }
    // Melodía.
    if (tr.melody) {
      const beats = combat ? [0, 1, 2, 3] : [0, 2];
      for (const b of beats) {
        if (Math.random() > tr.melody.density + (combat ? 0.15 : 0)) continue;
        const deg = Math.floor(Math.random() * scale.length);
        const oct = tr.melody.octave + (Math.random() < 0.2 ? 1 : 0);
        const midi = chordRoot + scale[deg] + oct * 12;
        const dur = spb * (tr.melody.long ? 2.5 : 0.9);
        this._note(t + b * spb, midiToFreq(midi), dur, tr.melody.wave, tr.melody.gain * 0.85, {
          attack: 0.08, release: 0.6, filter: 2600, music: true,
        });
      }
    }
    // Percusión.
    if (tr.perc > 0) {
      const p = tr.perc;
      for (let i = 0; i < 8; i++) {
        const at = t + i * (spb / 2);
        if (i % 4 === 0) this._drum(at, 'kick', p * (combat ? 0.5 : 0.22));
        if (i % 4 === 2) this._drum(at, 'snare', p * (combat ? 0.32 : 0.1));
        if (combat && i % 2 === 1) this._drum(at, 'hat', p * 0.08);
      }
    }
  }

  _note(time, freq, dur, type, gain, opts = {}) {
    if (!this.ctx || gain <= 0) return;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const filt = this.ctx.createBiquadFilter();
    filt.type = 'lowpass';
    filt.frequency.value = opts.filter || 2200;
    filt.Q.value = opts.q || 0.7;
    osc.type = type;
    osc.frequency.value = freq;
    if (opts.detune) {
      const osc2 = this.ctx.createOscillator();
      const g2 = this.ctx.createGain();
      osc2.type = type;
      osc2.frequency.value = freq;
      osc2.detune.value = opts.detune;
      g2.gain.value = 0.45;
      osc2.connect(g2).connect(filt);
      osc2.start(time);
      osc2.stop(time + dur + (opts.release || 0.3) + 0.1);
    }
    const attack = Math.max(0.003, opts.attack ?? 0.02);
    const release = Math.max(0.05, opts.release ?? 0.3);
    g.gain.setValueAtTime(0.0001, time);
    g.gain.linearRampToValueAtTime(gain, time + attack);
    g.gain.setValueAtTime(gain, time + Math.max(attack, dur * 0.7));
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur + release);
    osc.connect(g).connect(filt).connect(opts.music ? this.musicBus : this.sfxBus);
    osc.start(time);
    osc.stop(time + dur + release + 0.1);
    osc.onended = () => { try { g.disconnect(); filt.disconnect(); } catch {} };
  }

  _drum(time, kind, gain) {
    if (!this.noiseBuffer || gain <= 0) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const g = this.ctx.createGain();
    const filt = this.ctx.createBiquadFilter();
    filt.type = kind === 'kick' ? 'lowpass' : 'highpass';
    filt.frequency.value = kind === 'kick' ? 120 : kind === 'snare' ? 800 : 5000;
    src.connect(filt).connect(g).connect(this.musicBus);
    const dur = kind === 'kick' ? 0.18 : kind === 'snare' ? 0.14 : 0.05;
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    src.start(time);
    src.stop(time + dur + 0.02);
  }

  sfx(name, { volume = 1, pan = 0 } = {}) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    const v = volume;
    const panner = this.ctx.createStereoPanner?.();
    if (panner) panner.pan.value = Math.max(-1, Math.min(1, pan));
    const out = (node) => { if (panner) { node.connect(panner); panner.connect(this.sfxBus); } else node.connect(this.sfxBus); };
    switch (name) {
      case 'ui': this._note(t, 880, 0.06, 'sine', 0.08 * v, { attack: 0.002, release: 0.08 }); break;
      case 'hover': this._note(t, 620, 0.04, 'sine', 0.04 * v, { attack: 0.002, release: 0.05 }); break;
      case 'attack': this._noiseSweep(t, 0.12, 0.18 * v, 900, 300, out); this._note(t, 220, 0.1, 'sawtooth', 0.05 * v, { attack: 0.002, release: 0.12 }); break;
      case 'heavy': this._noiseSweep(t, 0.22, 0.26 * v, 500, 120, out); this._note(t, 110, 0.2, 'sawtooth', 0.1 * v, { attack: 0.005, release: 0.25 }); break;
      case 'hit': this._noiseSweep(t, 0.1, 0.2 * v, 1800, 500, out); this._note(t, 160, 0.08, 'square', 0.08 * v, { attack: 0.002, release: 0.1 }); break;
      case 'crit': this._noiseSweep(t, 0.16, 0.26 * v, 3000, 700, out); this._note(t, 880, 0.18, 'triangle', 0.08 * v, { attack: 0.002, release: 0.2 }); break;
      case 'dodge': this._noiseSweep(t, 0.2, 0.12 * v, 400, 1600, out); break;
      case 'spell': this._note(t, 523, 0.3, 'sine', 0.08 * v, { attack: 0.01, release: 0.4 }); this._note(t + 0.04, 784, 0.3, 'sine', 0.06 * v, { attack: 0.01, release: 0.4 }); break;
      case 'fire': this._noiseSweep(t, 0.4, 0.18 * v, 1200, 300, out); break;
      case 'parry': this._note(t, 1320, 0.25, 'sine', 0.12 * v, { attack: 0.002, release: 0.4 }); this._note(t, 1760, 0.18, 'triangle', 0.06 * v, { attack: 0.002, release: 0.3 }); break;
      case 'potion': this._note(t, 440, 0.2, 'sine', 0.06 * v, { attack: 0.01, release: 0.25 }); this._note(t + 0.1, 660, 0.3, 'sine', 0.06 * v, { attack: 0.01, release: 0.3 }); break;
      case 'pickup': this._note(t, 880, 0.1, 'triangle', 0.06 * v, { attack: 0.002, release: 0.12 }); this._note(t + 0.07, 1174, 0.16, 'triangle', 0.05 * v, { attack: 0.002, release: 0.2 }); break;
      case 'gold': this._note(t, 1046, 0.08, 'sine', 0.05 * v, { attack: 0.002, release: 0.1 }); this._note(t + 0.05, 1568, 0.12, 'sine', 0.04 * v, { attack: 0.002, release: 0.16 }); break;
      case 'levelup': [523, 659, 784, 1046].forEach((f, i) => this._note(t + i * 0.1, f, 0.5, 'sine', 0.07 * v, { attack: 0.01, release: 0.6 })); break;
      case 'capture': [392, 523, 659, 784, 1046].forEach((f, i) => this._note(t + i * 0.09, f, 0.7, 'sine', 0.06 * v, { attack: 0.02, release: 0.8 })); break;
      case 'fail': this._note(t, 180, 0.4, 'sawtooth', 0.08 * v, { attack: 0.01, release: 0.5 }); this._note(t + 0.08, 140, 0.5, 'sawtooth', 0.06 * v, { attack: 0.01, release: 0.5 }); break;
      case 'death': [220, 196, 164, 110].forEach((f, i) => this._note(t + i * 0.18, f, 0.8, 'sawtooth', 0.06 * v, { attack: 0.02, release: 0.9 })); break;
      case 'waypoint': [392, 523, 659, 880].forEach((f, i) => this._note(t + i * 0.12, f, 0.9, 'sine', 0.05 * v, { attack: 0.03, release: 1 })); break;
      case 'door': this._noiseSweep(t, 0.7, 0.16 * v, 300, 80, out); break;
      case 'chest': this._note(t, 330, 0.2, 'triangle', 0.07 * v, { attack: 0.005, release: 0.3 }); this._note(t + 0.15, 660, 0.4, 'sine', 0.07 * v, { attack: 0.01, release: 0.5 }); break;
      case 'quest': [440, 554, 659].forEach((f, i) => this._note(t + i * 0.12, f, 0.6, 'sine', 0.06 * v, { attack: 0.01, release: 0.7 })); break;
      case 'buy': this._note(t, 1200, 0.08, 'triangle', 0.06 * v, { attack: 0.002, release: 0.1 }); this._note(t + 0.06, 900, 0.12, 'triangle', 0.05 * v, { attack: 0.002, release: 0.16 }); break;
      case 'error': this._note(t, 160, 0.18, 'square', 0.06 * v, { attack: 0.002, release: 0.2 }); break;
      case 'boss': [110, 104, 98, 82].forEach((f, i) => this._note(t + i * 0.25, f, 1.2, 'sawtooth', 0.09 * v, { attack: 0.05, release: 1.4, filter: 500 })); break;
      case 'step': this._noiseSweep(t, 0.05, 0.035 * v, 900, 400, out); break;
      case 'splash': this._noiseSweep(t, 0.25, 0.12 * v, 2000, 400, out); break;
      case 'thunder': this._noiseSweep(t, 1.4, 0.2 * v, 600, 60, out); break;
      default: break;
    }
  }

  _noiseSweep(time, dur, gain, f0, f1, out) {
    if (!this.noiseBuffer) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 1.2;
    f.frequency.setValueAtTime(f0, time);
    f.frequency.exponentialRampToValueAtTime(Math.max(40, f1), time + dur);
    src.connect(f).connect(g);
    out(g);
    g.gain.setValueAtTime(gain, time);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    src.start(time);
    src.stop(time + dur + 0.02);
  }

  suspend() {
    if (!this.ctx) return;
    this.suspended = true;
    this.ctx.suspend().catch(() => {});
  }
  resume() {
    if (!this.ctx) return;
    this.suspended = false;
    this.ctx.resume().catch(() => {});
  }
}

// Guardado local persistente con ranuras y ajustes.
const SAVE_KEY = 'la-espada-celestial.saves.v1';
const SETTINGS_KEY = 'la-espada-celestial.settings.v1';
const SLOTS = 3;

const DEFAULT_SETTINGS = {
  music: 0.55,
  sfx: 0.72,
  master: 0.85,
  textSpeed: 1,
  largeText: false,
  shake: true,
  flashes: true,
  damageNumbers: true,
  autoAim: true,
  difficulty: 'caballero',
  touchOpacity: 0.85,
  showFps: false,
};

function readJSON(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch { return fallback; }
}

export class SaveSystem {
  constructor() {
    this.slots = this._readSlots();
    this.settings = { ...DEFAULT_SETTINGS, ...readJSON(SETTINGS_KEY, {}) };
  }

  _readSlots() {
    const data = readJSON(SAVE_KEY, { slots: {} });
    const slots = {};
    for (let i = 1; i <= SLOTS; i++) slots[i] = data.slots?.[i] || null;
    return slots;
  }

  _writeSlots() {
    try { localStorage.setItem(SAVE_KEY, JSON.stringify({ version: 1, slots: this.slots })); }
    catch (e) { console.warn('No se pudo guardar la partida', e); return false; }
    return true;
  }

  save(slot, data) {
    const now = Date.now();
    const record = {
      version: 1,
      savedAt: now,
      meta: {
        name: data.player?.name || 'Peregrino',
        level: data.player?.level || 1,
        region: data.regionName || data.player?.region || 'Valdoria',
        playtime: data.playtime || 0,
        quest: data.questTitle || '',
      },
      data,
    };
    this.slots[slot] = record;
    return this._writeSlots();
  }

  load(slot) {
    return this.slots[slot]?.data || null;
  }

  latestSlot() {
    let best = null, bestTime = -1;
    for (let i = 1; i <= SLOTS; i++) {
      const s = this.slots[i];
      if (s && s.savedAt > bestTime) { bestTime = s.savedAt; best = i; }
    }
    return best;
  }

  latest() {
    const slot = this.latestSlot();
    return slot ? { slot, ...this.slots[slot] } : null;
  }

  remove(slot) {
    this.slots[slot] = null;
    this._writeSlots();
  }

  clearAll() {
    this.slots = { 1: null, 2: null, 3: null };
    try { localStorage.removeItem(SAVE_KEY); } catch {}
  }

  saveSettings() {
    try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(this.settings)); } catch {}
  }

  resetSettings() {
    this.settings = { ...DEFAULT_SETTINGS };
    this.saveSettings();
  }
}

export { DEFAULT_SETTINGS, SLOTS };

import { clamp, lerp } from './utils.js';

export class Camera {
  constructor() {
    this.x = 0; this.y = 0;
    this.targetX = 0; this.targetY = 0;
    this.zoom = 1;
    this.targetZoom = 1;
    this.shake = 0;
    this.shakeX = 0; this.shakeY = 0;
    this.width = 1280; this.height = 720;
    this.bounds = { x: 0, y: 0, w: 3200, h: 2400 };
    this.follow = 0.12;
    this.lookAhead = 22;
  }

  setViewport(w, h) { this.width = w; this.height = h; }
  setBounds(w, h, tile = 32) { this.bounds = { x: 0, y: 0, w: w * tile, h: h * tile }; }
  snapTo(x, y) { this.x = this.targetX = x; this.y = this.targetY = y; this.clampToBounds(); }
  addShake(amount) { this.shake = Math.min(26, this.shake + amount); }

  update(dt, tx, ty, vx = 0, vy = 0, reduceMotion = false) {
    this.targetX = tx + vx * this.lookAhead;
    this.targetY = ty + vy * this.lookAhead;
    this.x = lerp(this.x, this.targetX, 1 - Math.pow(0.001, dt));
    this.y = lerp(this.y, this.targetY, 1 - Math.pow(0.001, dt));
    this.zoom = lerp(this.zoom, this.targetZoom, 1 - Math.pow(0.005, dt));
    this.clampToBounds();
    if (this.shake > 0.05 && !reduceMotion) {
      this.shake *= Math.pow(0.0008, dt);
      this.shakeX = (Math.random() * 2 - 1) * this.shake;
      this.shakeY = (Math.random() * 2 - 1) * this.shake;
    } else {
      this.shake = 0; this.shakeX = 0; this.shakeY = 0;
    }
  }

  clampToBounds() {
    const halfW = this.width / (2 * this.zoom);
    const halfH = this.height / (2 * this.zoom);
    const b = this.bounds;
    if (b.w <= halfW * 2) this.x = b.x + b.w / 2;
    else this.x = clamp(this.x, b.x + halfW, b.x + b.w - halfW);
    if (b.h <= halfH * 2) this.y = b.y + b.h / 2;
    else this.y = clamp(this.y, b.y + halfH, b.y + b.h - halfH);
  }

  apply(ctx) {
    ctx.translate(this.width / 2, this.height / 2);
    ctx.scale(this.zoom, this.zoom);
    ctx.translate(-this.x + this.shakeX / this.zoom, -this.y + this.shakeY / this.zoom);
  }

  worldToScreen(x, y) {
    return {
      x: (x - this.x) * this.zoom + this.width / 2 + this.shakeX,
      y: (y - this.y) * this.zoom + this.height / 2 + this.shakeY,
    };
  }
  screenToWorld(x, y) {
    return {
      x: (x - this.width / 2) / this.zoom + this.x,
      y: (y - this.height / 2) / this.zoom + this.y,
    };
  }
  isVisible(x, y, margin = 80) {
    const halfW = this.width / (2 * this.zoom) + margin;
    const halfH = this.height / (2 * this.zoom) + margin;
    return Math.abs(x - this.x) < halfW && Math.abs(y - this.y) < halfH;
  }
}

import { clamp, randRange, TAU } from './utils.js';

const MAX_PARTICLES = 700;

export class Particles {
  constructor() {
    this.items = [];
    this.numbers = [];
    this.rings = [];
  }

  clear() { this.items.length = 0; this.numbers.length = 0; this.rings.length = 0; }

  spawn(type, x, y, opts = {}) {
    if (this.items.length >= MAX_PARTICLES) this.items.shift();
    const a = opts.angle ?? Math.random() * TAU;
    const speed = opts.speed ?? 60;
    const life = opts.life ?? randRange(Math.random, 0.4, 0.9);
    this.items.push({
      type, x, y,
      vx: Math.cos(a) * speed + (opts.vx || 0),
      vy: Math.sin(a) * speed + (opts.vy || 0),
      gravity: opts.gravity ?? 0,
      drag: opts.drag ?? 2.4,
      size: opts.size ?? randRange(Math.random, 1.5, 3.5),
      life, maxLife: life,
      color: opts.color || '#ffd98a',
      glow: opts.glow ?? true,
      spin: opts.spin ?? 0,
      rot: Math.random() * TAU,
      additive: opts.additive ?? true,
    });
  }

  burst(x, y, count, opts = {}) {
    for (let i = 0; i < count; i++) {
      this.spawn(opts.type || 'spark', x, y, {
        ...opts,
        angle: opts.angle !== undefined ? opts.angle + randRange(Math.random, -0.7, 0.7) : Math.random() * TAU,
        speed: (opts.speed ?? 90) * randRange(Math.random, 0.45, 1.25),
        size: (opts.size ?? 2.5) * randRange(Math.random, 0.6, 1.4),
        life: (opts.life ?? 0.7) * randRange(Math.random, 0.7, 1.3),
      });
    }
  }

  slash(x, y, angle, opts = {}) {
    this.rings.push({ kind: 'slash', x, y, angle, radius: opts.radius || 48, life: 0.22, maxLife: 0.22, color: opts.color || '#ffe6a8', width: opts.width || 8, arc: opts.arc || 1.5 });
  }
  ring(x, y, opts = {}) {
    this.rings.push({ kind: 'ring', x, y, radius: opts.radius || 30, target: opts.target || 90, life: opts.life || 0.4, maxLife: opts.life || 0.4, color: opts.color || '#ffd98a', width: opts.width || 3 });
  }
  beam(x, y, angle, opts = {}) {
    this.rings.push({ kind: 'beam', x, y, angle, radius: opts.radius || 180, life: opts.life || 0.18, maxLife: opts.life || 0.18, color: opts.color || '#fff2c4', width: opts.width || 10 });
  }
  number(x, y, text, color = '#ffe6a8', size = 16, crit = false) {
    this.numbers.push({ x, y, text, color, size, crit, life: 0.9, maxLife: 0.9, vy: -46, vx: randRange(Math.random, -16, 16) });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const p = this.items[i];
      p.life -= dt;
      if (p.life <= 0) { this.items.splice(i, 1); continue; }
      p.vy += p.gravity * dt;
      p.vx *= Math.exp(-p.drag * dt);
      p.vy *= Math.exp(-p.drag * dt);
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
    for (let i = this.numbers.length - 1; i >= 0; i--) {
      const n = this.numbers[i];
      n.life -= dt;
      if (n.life <= 0) { this.numbers.splice(i, 1); continue; }
      n.y += n.vy * dt;
      n.x += n.vx * dt;
      n.vy += 40 * dt;
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      if (r.life <= 0) this.rings.splice(i, 1);
    }
  }

  draw(ctx) {
    ctx.save();
    for (const p of this.items) {
      const t = clamp(p.life / p.maxLife, 0, 1);
      const alpha = p.type === 'smoke' ? t * 0.45 : t;
      ctx.globalCompositeOperation = p.additive ? 'lighter' : 'source-over';
      ctx.globalAlpha = alpha;
      ctx.fillStyle = p.color;
      if (p.type === 'leaf') {
        ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);
        ctx.beginPath(); ctx.ellipse(0, 0, p.size * 1.6, p.size * 0.7, 0, 0, TAU); ctx.fill();
        ctx.restore();
      } else if (p.type === 'smoke') {
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * (2.5 - t), 0, TAU); ctx.fill();
      } else if (p.type === 'star') {
        const s = p.size * (0.7 + t);
        ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);
        ctx.beginPath();
        for (let i = 0; i < 4; i++) {
          const a = i * Math.PI / 2;
          ctx.lineTo(Math.cos(a) * s, Math.sin(a) * s);
          ctx.lineTo(Math.cos(a + Math.PI / 4) * s * 0.32, Math.sin(a + Math.PI / 4) * s * 0.32);
        }
        ctx.closePath(); ctx.fill(); ctx.restore();
      } else {
        ctx.beginPath(); ctx.arc(p.x, p.y, Math.max(0.4, p.size * (0.5 + t * 0.6)), 0, TAU); ctx.fill();
      }
    }
    ctx.globalCompositeOperation = 'lighter';
    for (const r of this.rings) {
      const t = clamp(r.life / r.maxLife, 0, 1);
      ctx.globalAlpha = t;
      if (r.kind === 'slash') {
        ctx.strokeStyle = r.color;
        ctx.lineWidth = r.width * t;
        ctx.lineCap = 'round';
        ctx.beginPath();
        const start = r.angle - r.arc / 2;
        ctx.arc(r.x, r.y, r.radius * (1.25 - t * 0.25), start, start + r.arc);
        ctx.stroke();
        ctx.globalAlpha = t * 0.5;
        ctx.lineWidth = r.width * 2.4 * t;
        ctx.stroke();
      } else if (r.kind === 'beam') {
        ctx.strokeStyle = r.color;
        ctx.lineWidth = r.width * t;
        ctx.beginPath();
        ctx.moveTo(r.x, r.y);
        ctx.lineTo(r.x + Math.cos(r.angle) * r.radius, r.y + Math.sin(r.angle) * r.radius);
        ctx.stroke();
      } else {
        const radius = r.radius + (r.target - r.radius) * (1 - t);
        ctx.strokeStyle = r.color;
        ctx.lineWidth = r.width * t;
        ctx.beginPath(); ctx.arc(r.x, r.y, radius, 0, TAU); ctx.stroke();
      }
    }
    ctx.restore();
    // Números de daño.
    ctx.save();
    for (const n of this.numbers) {
      const t = clamp(n.life / n.maxLife, 0, 1);
      ctx.globalAlpha = Math.min(1, t * 2);
      ctx.font = `${n.crit ? 700 : 600} ${n.size * (n.crit ? 1.25 : 1)}px Cinzel, Georgia, serif`;
      ctx.textAlign = 'center';
      ctx.lineWidth = 3;
      ctx.strokeStyle = 'rgba(10,8,18,0.85)';
      ctx.strokeText(n.text, n.x, n.y);
      ctx.fillStyle = n.color;
      ctx.fillText(n.text, n.x, n.y);
    }
    ctx.restore();
  }
}

