input.content:
import { ITEMS, itemRarity } from '../data/items.js';
import { clamp } from '../core/utils.js';

const EQUIP_SLOTS = ['weapon', 'armor', 'helmet', 'accessory'];

export class Inventory {
  constructor(data = null) {
    this.items = {};
    this.equipment = { weapon: 'rusty_sword', armor: 'tunic', helmet: null, accessory: null };
    this.upgrades = {};
    this.captureBuff = 0;
    if (data) this.deserialize(data);
    else this.add('potion_lumen', 2), this.add('elixir_mana', 1), this.add('crystal_resonance', 1);
  }

  count(id) { return this.items[id] || 0; }
  has(id, qty = 1) { return this.count(id) >= qty; }

  add(id, qty = 1) {
    if (!ITEMS[id]) return false;
    this.items[id] = (this.items[id] || 0) + qty;
    return true;
  }

  remove(id, qty = 1) {
    if ((this.items[id] || 0) < qty) return false;
    this.items[id] -= qty;
    if (this.items[id] <= 0) delete this.items[id];
    return true;
  }

  equip(id) {
    const item = ITEMS[id];
    if (!item || !EQUIP_SLOTS.includes(item.type)) return false;
    if (!this.has(id)) return false;
    this.equipment[item.type] = id;
    return true;
  }

  unequip(slot) {
    if (slot === 'weapon' || slot === 'armor') return false;
    this.equipment[slot] = null;
    return true;
  }

  isEquipped(id) { return Object.values(this.equipment).includes(id); }

  upgradeLevel(id) { return this.upgrades[id] || 0; }

  upgradeStats(id) {
    const item = ITEMS[id];
    const lvl = this.upgradeLevel(id);
    if (!item || lvl <= 0) return {};
    const scale = lvl;
    if (item.type === 'weapon') return { atk: Math.round((item.atk || 4) * 0.12 * scale) + scale };
    if (item.type === 'armor') return { def: Math.round((item.def || 3) * 0.12 * scale) + scale, hp: scale * 6 };
    if (item.type === 'helmet') return { def: Math.round((item.def || 2) * 0.12 * scale) + scale, hp: scale * 4 };
    return { luck: scale };
  }

  upgradeCost(id) {
    const item = ITEMS[id];
    if (!item) return null;
    const lvl = this.upgradeLevel(id);
    if (lvl >= 5) return null;
    const rarity = item.rarity || 0;
    return {
      gold: 60 + rarity * 90 + lvl * 70,
      iron: 2 + lvl * 2,
      gem_shard: lvl >= 3 ? 1 : 0,
      living_ash: rarity >= 3 && lvl >= 2 ? 2 : 0,
    };
  }

  upgrade(id) {
    const cost = this.upgradeCost(id);
    if (!cost) return { ok: false, msg: 'Este objeto ya está al máximo.' };
    if (!this.has(id)) return { ok: false, msg: 'No tienes ese objeto.' };
    return { ok: true, cost };
  }

  applyUpgrade(id) {
    const cost = this.upgradeCost(id);
    if (!cost) return false;
    this.upgrades[id] = (this.upgrades[id] || 0) + 1;
    return true;
  }

  equipmentStats() {
    const stats = {};
    for (const slot of EQUIP_SLOTS) {
      const id = this.equipment[slot];
      if (!id) continue;
      const item = ITEMS[id];
      if (!item) continue;
      for (const [k, v] of Object.entries(item)) {
        if (typeof v === 'number' && ['atk', 'def', 'hp', 'mp', 'crit', 'speed', 'luck', 'int', 'str', 'lifesteal', 'fireRes', 'capture', 'dodge', 'hpRegen', 'manaRegen', 'damageReduction'].includes(k)) {
          stats[k] = (stats[k] || 0) + v;
        }
      }
      for (const [k, v] of Object.entries(this.upgradeStats(id))) stats[k] = (stats[k] || 0) + v;
    }
    return stats;
  }

  weapon() {
    const id = this.equipment.weapon;
    return id ? { id, ...ITEMS[id], upgrade: this.upgradeLevel(id) } : null;
  }

  weaponType() { return this.weapon()?.weaponType || 'sword'; }

  use(id, player, game) {
    const item = ITEMS[id];
    if (!item || item.type !== 'consumable' || !this.has(id)) return { ok: false, msg: 'No puedes usar eso.' };
    let msg = '';
    if (item.heal) {
      const amount = Math.round(player.maxHp * item.heal);
      player.heal(amount);
      msg = `Recuperas ${amount} de vida.`;
    } else if (item.mana) {
      const amount = Math.round(player.maxMp * item.mana);
      player.restoreMana(amount);
      msg = `Recuperas ${amount} de maná.`;
    } else if (item.stamina) {
      player.stamina = player.maxStamina;
      msg = 'Recuperas toda la resistencia.';
    } else if (item.captureBonus) {
      this.captureBuff = Math.max(this.captureBuff, item.captureBonus);
      msg = 'El siguiente intento de captura será más fácil.';
    } else if (item.escape) {
      game.escapeCombat();
      msg = 'El humo cubre tu huida.';
    } else if (item.cleanse) {
      player.status = {};
      msg = 'Las impurezas abandonan tu cuerpo.';
    }
    this.remove(id, 1);
    game.audio.sfx('potion');
    return { ok: true, msg };
  }

  buyPrice(id) {
    const item = ITEMS[id];
    return item ? Math.round(item.value * 1.15) : 0;
  }
  sellPrice(id) {
    const item = ITEMS[id];
    return item ? Math.max(1, Math.round(item.value * 0.55)) : 0;
  }

  serialize() {
    return { items: { ...this.items }, equipment: { ...this.equipment }, upgrades: { ...this.upgrades } };
  }
  deserialize(data) {
    this.items = { ...(data.items || {}) };
    this.equipment = { weapon: 'rusty_sword', armor: 'tunic', helmet: null, accessory: null, ...(data.equipment || {}) };
    this.upgrades = { ...(data.upgrades || {}) };
    this.captureBuff = 0;
  }
}

export const SHOPS = {
  sela: {
    name: 'Sela, mercader de Lumen',
    greeting: 'Pociones frescas, rumores más frescos. Nada devuelve el dinero.',
    stock: ['potion_lumen', 'elixir_mana', 'tonic_stamina', 'antidote', 'crystal_resonance', 'smoke_bomb', 'lucky_charm', 'pilgrim_blade', 'tunic', 'hood', 'iron'],
  },
  nira: {
    name: 'Nira, chatarrera de Cendra',
    greeting: 'Todo tiene un precio. Hasta el aire, si sabes envasarlo.',
    stock: ['potion_lumen', 'elixir_mana', 'tonic_stamina', 'crystal_resonance', 'smoke_bomb', 'ash_cloak', 'ash_hood', 'ember_pendant', 'obsidian_helm', 'living_ash'],
  },
};

export function itemDescription(id) {
  const item = ITEMS[id];
  if (!item) return '';
  const r = itemRarity(item);
  return `${r.name} · ${item.desc}`;
}

import { QUESTS } from '../data/quests.js';

export class QuestSystem {
  constructor(game) {
    this.game = game;
    this.active = {};
    this.completed = new Set();
    this.justCompleted = null;
  }

  start(id, silent = false) {
    const def = QUESTS[id];
    if (!def || this.active[id] || this.completed.has(id)) return false;
    this.active[id] = { stage: 0, progress: def.stages[0].objectives.map(() => 0), startedAt: Date.now() };
    if (!silent) {
      this.game.ui.toast('Nueva misión', def.title, 'quest');
      this.game.audio.sfx('quest');
    }
    this.refreshCollect(id);
    this.game.events.emit('questStart', { id, def });
    this.game.autosave();
    return true;
  }

  isActive(id) { return Boolean(this.active[id]); }
  isCompleted(id) { return this.completed.has(id); }
  stageIndex(id) { return this.active[id]?.stage ?? -1; }
  def(id) { return QUESTS[id]; }

  currentStage(id) {
    const a = this.active[id];
    if (!a) return null;
    return QUESTS[id]?.stages[a.stage] || null;
  }

  objectiveProgress(id, index) {
    return this.active[id]?.progress[index] || 0;
  }

  event(type, target, amount = 1) {
    for (const id of Object.keys(this.active)) {
      const def = QUESTS[id];
      const a = this.active[id];
      const stage = def?.stages[a.stage];
      if (!stage) continue;
      let changed = false;
      stage.objectives.forEach((obj, i) => {
        if (obj.type !== type || obj.target !== target) return;
        const need = obj.count || 1;
        const before = a.progress[i] || 0;
        a.progress[i] = Math.min(need, before + amount);
        if (a.progress[i] !== before) changed = true;
      });
      if (changed) this.check(id);
    }
  }

  refreshCollect(id = null) {
    const ids = id ? [id] : Object.keys(this.active);
    for (const qid of ids) {
      const def = QUESTS[qid], a = this.active[qid];
      if (!def || !a) continue;
      const stage = def.stages[a.stage];
      if (!stage) continue;
      let changed = false;
      stage.objectives.forEach((obj, i) => {
        if (obj.type !== 'collect') return;
        const need = obj.count || 1;
        const have = Math.min(need, this.game.inventory.count(obj.target));
        if (have !== a.progress[i]) { a.progress[i] = have; changed = true; }
      });
      if (changed) this.check(qid);
    }
  }

  check(id) {
    const def = QUESTS[id], a = this.active[id];
    if (!def || !a) return;
    const stage = def.stages[a.stage];
    if (!stage) return;
    const done = stage.objectives.every((obj, i) => (a.progress[i] || 0) >= (obj.count || 1));
    if (!done) return;
    if (a.stage < def.stages.length - 1) {
      a.stage++;
      a.progress = def.stages[a.stage].objectives.map(() => 0);
      this.game.ui.toast('Misión actualizada', def.stages[a.stage].text, 'quest');
      this.game.audio.sfx('quest');
      this.refreshCollect(id);
      this.check(id);
    } else {
      this.complete(id);
    }
  }

  complete(id) {
    const def = QUESTS[id];
    if (!def) return;
    delete this.active[id];
    this.completed.add(id);
    this.justCompleted = id;
    this.game.ui.toast('Misión completada', def.title, 'complete');
    this.game.audio.sfx('levelup');
    this.game.giveRewards(def.rewards || {});
    if (def.onComplete?.flags) {
      for (const [flag, value] of Object.entries(def.onComplete.flags)) this.game.setFlag(flag, value);
    }
    this.game.events.emit('questComplete', { id, def });
    if (def.next) this.start(def.next);
    this.game.autosave();
  }

  tracked() {
    const mains = Object.keys(this.active).filter(id => QUESTS[id]?.type === 'main');
    const sides = Object.keys(this.active).filter(id => QUESTS[id]?.type === 'side');
    return mains[0] || sides[0] || null;
  }

  trackedObjective() {
    const id = this.tracked();
    if (!id) return null;
    const def = QUESTS[id], a = this.active[id];
    const stage = def.stages[a.stage];
    if (!stage) return null;
    const obj = stage.objectives.find((o, i) => (a.progress[i] || 0) < (o.count || 1)) || stage.objectives[0];
    const idx = stage.objectives.indexOf(obj);
    return { quest: id, def, stage, objective: obj, progress: a.progress[idx] || 0, need: obj.count || 1 };
  }

  markers() {
    const out = [];
    for (const id of Object.keys(this.active)) {
      const def = QUESTS[id], a = this.active[id];
      const stage = def.stages[a.stage];
      if (!stage) continue;
      stage.objectives.forEach((obj, i) => {
        if ((a.progress[i] || 0) >= (obj.count || 1)) return;
        out.push({ ...obj, quest: id, main: def.type === 'main', progress: a.progress[i] || 0, need: obj.count || 1 });
      });
    }
    return out;
  }

  serialize() {
    return { active: JSON.parse(JSON.stringify(this.active)), completed: [...this.completed] };
  }
  deserialize(data) {
    this.active = data?.active || {};
    this.completed = new Set(data?.completed || []);
  }
}

import { CREATURES, creatureName, creaturePower } from '../data/creatures.js';
import { clamp } from '../core/utils.js';

export class Collection {
  constructor(game) {
    this.game = game;
    this.owned = {};
    this.active = null;
    this.captureBuff = 0;
  }

  has(id) { return Boolean(this.owned[id]); }
  get(id) { return this.owned[id] || null; }
  list() { return Object.keys(this.owned).map(id => ({ id, ...this.owned[id], def: CREATURES[id] })); }
  count() { return Object.keys(this.owned).length; }

  add(id, { bond = 1, level = 1, silent = false } = {}) {
    if (!CREATURES[id]) return false;
    if (this.owned[id]) {
      this.owned[id].bond = Math.min(5, this.owned[id].bond + 1);
      return false;
    }
    this.owned[id] = { bond, level, xp: 0, capturedAt: Date.now() };
    if (!this.active) this.active = id;
    if (!silent) {
      this.game.ui.toast('Nueva resonancia', creatureName(id, bond), 'creature');
      this.game.audio.sfx('capture');
    }
    this.game.events.emit('creatureAdded', { id });
    return true;
  }

  setActive(id) {
    if (!this.owned[id]) return false;
    this.active = id;
    this.game.events.emit('companionChanged', { id });
    return true;
  }

  gainXp(amount) {
    if (!this.active || !this.owned[this.active]) return;
    const c = this.owned[this.active];
    c.xp += amount;
    while (c.level < 10 && c.xp >= this.xpToNext(c.level)) {
      c.xp -= this.xpToNext(c.level);
      c.level++;
      this.game.ui.toast('Resonancia fortalecida', `${creatureName(this.active, c.bond)} alcanza el nivel ${c.level}.`, 'creature');
      this.game.audio.sfx('levelup');
    }
  }

  xpToNext(level) { return 60 + level * 35; }

  bondUp(id) {
    const c = this.owned[id];
    if (!c) return;
    c.bond = Math.min(5, c.bond + 1);
  }

  feed(id) {
    const c = this.owned[id];
    if (!c) return { ok: false, msg: 'No tienes esa resonancia.' };
    if (c.bond >= 5) return { ok: false, msg: 'El vínculo ya es absoluto.' };
    if (!this.game.inventory.has('resonance_essence', 2)) return { ok: false, msg: 'Necesitas 2 Esencias de Resonancia.' };
    this.game.inventory.remove('resonance_essence', 2);
    c.bond++;
    this.game.ui.toast('Vínculo fortalecido', `${creatureName(id, c.bond)} · Vínculo ${c.bond}`, 'creature');
    this.game.audio.sfx('capture');
    return { ok: true, msg: 'El vínculo se fortalece.' };
  }

  passiveStats() {
    if (!this.active) return {};
    const c = CREATURES[this.active];
    if (!c) return {};
    const stats = { ...(c.passive?.stats || {}) };
    if (stats.all) {
      for (const k of ['vit', 'mana', 'res', 'str', 'def', 'vel', 'int', 'luck']) stats[k] = (stats[k] || 0) + stats.all;
      delete stats.all;
    }
    return stats;
  }

  activeDef() {
    return this.active ? CREATURES[this.active] : null;
  }

  captureChance(enemy) {
    if (!enemy?.def?.capture || enemy.def.boss || enemy.def.human) return 0;
    const ratio = 1 - clamp(enemy.hp / enemy.maxHp, 0, 1);
    const base = (CREATURES[enemy.def.capture]?.captureBase || 0.2);
    const luck = this.game.player.stats.luck * 0.008;
    const ring = this.game.inventory.equipment.accessory === 'resonance_ring' ? 0.08 : 0;
    const int = this.game.player.stats.int * 0.006;
    return clamp(base * 0.45 + ratio * 0.55 + luck + ring + int + this.captureBuff, 0.05, 0.95);
  }

  serialize() {
    return { owned: JSON.parse(JSON.stringify(this.owned)), active: this.active };
  }
  deserialize(data) {
    this.owned = data?.owned || {};
    this.active = data?.active || Object.keys(this.owned)[0] || null;
  }
}

export function creatureSummary(id, entry) {
  const def = CREATURES[id];
  return {
    id,
    name: creatureName(id, entry.bond),
    element: def.element,
    role: def.role,
    level: entry.level,
    bond: entry.bond,
    power: creaturePower(id, entry.bond, entry.level),
    desc: def.desc,
    lore: def.lore,
    active: def.active,
    passive: def.passive,
  };
}

import { ORIGINS, SKILL_TREES, WEAPON_TYPES, ULTIMATES, DIFFICULTIES } from '../data/skills.js';
import { ITEMS } from '../data/items.js';
import { clamp, angleDiff, dist, TAU } from '../core/utils.js';

export const BASE_STATS = { vit: 5, mana: 5, res: 5, str: 5, def: 5, vel: 5, int: 5, luck: 5 };
export const DEFAULT_APPEARANCE = {
  skin: '#e8c9a8', hairStyle: 0, hairColor: '#3a2a1a', eyeColor: '#4a7a8a',
  outfit: '#4a6a4a', armorColor: '#6f8f63', cape: true, capeColor: '#7a3a4a', helmet: false,
};

export const SPELLS = [
  { id: 'rayo', name: 'Rayo Celestial', cost: 12, cooldown: 1.1, desc: 'Un proyectil de luz que atraviesa la penumbra.', color: '#ffe7a8' },
  { id: 'nova', name: 'Nova de Resonancia', cost: 20, cooldown: 5, desc: 'Una onda expansiva que daña y ralentiza a los enemigos cercanos.', color: '#c7a4ff' },
  { id: 'barrera', name: 'Barrera del Velo', cost: 16, cooldown: 8, desc: 'Un escudo de luz que absorbe daño y te cura ligeramente.', color: '#9fe8ff' },
];

export class Player {
  constructor(game, data = null) {
    this.game = game;
    this.radius = 10;
    this.x = 0; this.y = 0;
    this.vx = 0; this.vy = 0;
    this.facing = Math.PI / 2;
    this.anim = 'idle';
    this.animTime = 0;
    this.attackTime = 0;
    this.attackIndex = 0;
    this.comboTimer = 0;
    this.attackHit = new Set();
    this.heavy = false;
    this.dodgeTime = 0;
    this.dodgeCd = 0;
    this.invuln = 0;
    this.blocking = false;
    this.parryTimer = 0;
    this.parryCd = 0;
    this.castTime = 0;
    this.castSpell = null;
    this.hurtFlash = 0;
    this.dead = false;
    this.deadTime = 0;
    this.potionCd = 0;
    this.ult = 0;
    this.ultActive = 0;
    this.ultType = null;
    this.status = {};
    this.selectedSpell = 0;
    this.spellCooldowns = [0, 0, 0];
    this.stepTimer = 0;
    this.companionCooldown = 0;
    this.captureMode = false;
    this.lastSafe = null;
    this.kills = 0;
    this.captures = 0;
    this.damageDealt = 0;
    this.damageTaken = 0;
    this.playtime = 0;
    if (data) this.deserialize(data);
    else this.initNew();
  }

  get flags() { return this.game.flags; }
  get stats() { return this.baseStats; }
  get difficulty() { return DIFFICULTIES[this.game.settings.difficulty] || DIFFICULTIES.caballero; }

  initNew() {
    this.name = 'Peregrino';
    this.origin = 'brasa';
    this.appearance = { ...DEFAULT_APPEARANCE };
    this.baseStats = { ...BASE_STATS };
    this.bonusCrit = 0;
    this.level = 1;
    this.xp = 0;
    this.xpNext = 100;
    this.points = 8;
    this.skillPoints = 0;
    this.skills = {};
    this.gold = 60;
    this.hp = 100; this.mp = 30; this.stamina = 60;
    this.maxHp = 100; this.maxMp = 30; this.maxStamina = 60;
    this.region = 'valdoria';
    this.lastWaypoint = null;
    this.recalc(true);
    this.hp = this.maxHp; this.mp = this.maxMp; this.stamina = this.maxStamina;
  }

  applyOrigin(origin) {
    this.origin = origin;
    const o = ORIGINS[origin] || ORIGINS.brasa;
    this.baseStats = { ...BASE_STATS };
    for (const [k, v] of Object.entries(o.bonus)) {
      if (k === 'crit') this.bonusCrit += v * 0.02;
      else if (k === 'mana') this.baseStats.mana += v;
      else this.baseStats[k] = (this.baseStats[k] || 0) + v;
    }
    this.recalc(true);
    this.hp = this.maxHp; this.mp = this.maxMp; this.stamina = this.maxStamina;
  }

  recalc(full = false) {
    const eq = this.game.inventory?.equipmentStats() || {};
    const passive = this.game.collection?.passiveStats() || {};
    const s = this.baseStats;
    this.maxHp = Math.round(80 + (s.vit + (passive.vit || 0)) * 8 + (eq.hp || 0));
    this.maxMp = Math.round(30 + (s.mana + (passive.mana || 0)) * 4 + (eq.mp || 0));
    this.maxStamina = Math.round(60 + (s.res + (passive.res || 0)) * 4);
    this.attack = 6 + (s.str + (passive.str || 0)) * 1.55 + (eq.atk || 0);
    this.spellPower = 12 + (s.int + (passive.int || 0)) * 2.3 + (eq.int || 0) * 1.6;
    this.defense = (s.def + (passive.def || 0)) * 1.2 + (eq.def || 0);
    this.speed = 118 + (s.vel + (passive.vel || 0)) * 3.6 + (eq.speed || 0) * 1.8;
    this.crit = clamp(0.05 + (s.luck + (passive.luck || 0)) * 0.006 + (eq.crit || 0) / 100 + this.bonusCrit, 0, 0.85);
    this.luck = s.luck + (passive.luck || 0) + (eq.luck || 0);
    this.hpRegen = (eq.hpRegen || 0) + (passive.hpRegen || 0);
    this.manaRegen = 1 + (eq.manaRegen || 0) + (passive.manaRegen || 0);
    this.damageReduction = clamp((eq.damageReduction || 0) + (passive.damageReduction || 0) + this.defense / (this.defense + 180), 0, 0.75);
    this.lifesteal = (eq.lifesteal || 0) + (passive.lifesteal || 0);
    this.dodgeCdMax = 0.65 * (1 - (passive.dodgeCd || 0));
    this.weaponSpeed = WEAPON_TYPES[this.game.inventory?.weaponType()]?.speed || 1;
    this.maxHp = Math.max(1, this.maxHp); this.maxMp = Math.max(1, this.maxMp); this.maxStamina = Math.max(1, this.maxStamina);
    if (full) { this.hp = Math.min(this.hp, this.maxHp); this.mp = Math.min(this.mp, this.maxMp); this.stamina = Math.min(this.stamina, this.maxStamina); }
    this.hp = Math.min(this.hp, this.maxHp);
    this.mp = Math.min(this.mp, this.maxMp);
    this.stamina = Math.min(this.stamina, this.maxStamina);
  }

  hasSkill(id) { return Boolean(this.skills[id]); }
  skillBranch() { return this.origin === 'velo' ? 'velo' : this.origin === 'sombra' ? 'resonancia' : 'espada'; }

  unlockSkill(id) {
    const all = Object.values(SKILL_TREES).flatMap(t => t.nodes);
    const node = all.find(n => n.id === id);
    if (!node || this.skills[id] || this.skillPoints < node.cost) return false;
    if (node.requires && !this.skills[node.requires]) return false;
    this.skillPoints -= node.cost;
    this.skills[id] = true;
    if (node.ultimate) this.ultType = node.ultimate;
    this.game.ui.toast('Habilidad aprendida', node.name, 'skill');
    this.game.audio.sfx('levelup');
    return true;
  }

  allocate(stat) {
    if (this.points <= 0 || !(stat in this.baseStats)) return false;
    this.points--;
    this.baseStats[stat]++;
    this.recalc();
    return true;
  }

  heal(amount) {
    const before = this.hp;
    this.hp = Math.min(this.maxHp, this.hp + amount);
    if (this.hp > before) this.game.particles.number(this.x, this.y - 34, `+${Math.round(this.hp - before)}`, '#8fd18a', 14);
  }
  restoreMana(amount) {
    const before = this.mp;
    this.mp = Math.min(this.maxMp, this.mp + amount);
    if (this.mp > before) this.game.particles.number(this.x, this.y - 46, `+${Math.round(this.mp - before)}`, '#7fb7ff', 13);
  }

  gainXp(amount) {
    if (amount <= 0) return;
    this.xp += Math.round(amount * this.difficulty.xp);
    while (this.xp >= this.xpNext) {
      this.xp -= this.xpNext;
      this.level++;
      this.xpNext = 80 + this.level * 60;
      this.points += 2;
      this.skillPoints += 1;
      this.recalc(true);
      this.hp = this.maxHp; this.mp = this.maxMp; this.stamina = this.maxStamina;
      this.game.ui.toast('Nivel ' + this.level, 'Has ganado 2 puntos de atributo y 1 de habilidad.', 'level');
      this.game.audio.sfx('levelup');
      this.game.particles.burst(this.x, this.y - 20, 40, { color: '#ffe7a8', speed: 140, life: 1, size: 3 });
      this.game.autosave();
    }
  }

  addUlt(amount) { this.ult = clamp(this.ult + amount, 0, 100); }

  update(dt, input, world, game) {
    this.playtime += dt;
    if (this.dead) {
      this.deadTime += dt;
      this.animTime += dt;
      return;
    }
    // Temporizadores.
    this.invuln = Math.max(0, this.invuln - dt);
    this.dodgeCd = Math.max(0, this.dodgeCd - dt);
    this.potionCd = Math.max(0, this.potionCd - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    this.parryCd = Math.max(0, this.parryCd - dt);
    this.parryTimer = Math.max(0, this.parryTimer - dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt);
    this.ultActive = Math.max(0, this.ultActive - dt);
    this.spellCooldowns = this.spellCooldowns.map(v => Math.max(0, v - dt));
    this.companionCooldown = Math.max(0, this.companionCooldown - dt);
    this.castTime = Math.max(0, this.castTime - dt);
    this.dodgeTime = Math.max(0, this.dodgeTime - dt);
    for (const [k, v] of Object.entries(this.status)) {
      this.status[k] = v - dt;
      if (this.status[k] <= 0) delete this.status[k];
    }
    if (this.status.burn) this.hp -= 4 * dt;
    if (this.hp <= 0) { this.die(); return; }

    // Regeneración.
    const outOfCombat = !game.inCombat;
    this.stamina = Math.min(this.maxStamina, this.stamina + (outOfCombat ? 24 : 14) * dt);
    this.mp = Math.min(this.maxMp, this.mp + this.manaRegen * dt);
    if (outOfCombat) this.hp = Math.min(this.maxHp, this.hp + (2 + this.hpRegen) * dt);

    // Apuntado.
    const aim = this.getAimAngle(game, input);
    if (!this.attacking() && !this.dodging()) this.facing = aim;

    // Movimiento.
    const axis = input.axis();
    const moveScale = this.blocking ? 0.42 : (this.attacking() ? 0.22 : 1);
    let dx = axis.x * this.speed * moveScale * dt;
    let dy = axis.y * this.speed * moveScale * dt;
    if (this.dodging()) {
      const dashSpeed = 430 * (this.hasSkill('veil_step') ? 1.25 : 1);
      dx = Math.cos(this.dodgeAngle) * dashSpeed * dt;
      dy = Math.sin(this.dodgeAngle) * dashSpeed * dt;
    }
    if (dx || dy) {
      const moved = world.moveCircle(this.x, this.y, dx, dy, this.radius);
      this.x = moved.x; this.y = moved.y;
      if (!this.attacking() && !this.dodging()) {
        this.anim = axis.len > 0.7 ? 'run' : 'walk';
        this.stepTimer -= dt;
        if (this.stepTimer <= 0) { this.stepTimer = 0.32; game.audio.sfx('step', { volume: 0.35 }); }
      }
    } else if (!this.attacking() && !this.dodging() && !this.blocking && this.castTime <= 0) {
      this.anim = 'idle';
    }

    // Acciones.
    if (input.justPressed('attack') && !this.attacking() && !this.dodging() && this.castTime <= 0) this.startAttack(false, game);
    if (input.justPressed('heavy') && !this.attacking() && !this.dodging() && this.castTime <= 0) this.startAttack(true, game);
    if (input.justPressed('dodge') && !this.dodging() && this.dodgeCd <= 0 && this.stamina >= 16) this.startDodge(axis, game);
    this.blocking = input.down('block') && !this.attacking() && !this.dodging();
    if (input.justPressed('block') && this.parryCd <= 0) { this.parryTimer = this.difficulty.parryWindow; this.parryCd = 0.55; }
    if (input.justPressed('interact')) game.interact();
    if (input.justPressed('spell1')) { this.selectedSpell = 0; }
    if (input.justPressed('spell2')) { this.selectedSpell = 1; }
    if (input.justPressed('spell3')) { this.selectedSpell = 2; }
    if (input.justPressed('spell')) this.castSelected(game);
    if (input.justPressed('companion')) game.useCompanion();
    if (input.justPressed('ultimate')) this.useUltimate(game);
    if (input.justPressed('potion')) this.usePotion(game);

    // Ataque.
    if (this.attackTime > 0) {
      this.attackTime -= dt;
      this.animTime += dt;
      const phase = this.attackPhase;
      if (phase === 'active' && this.attackTime <= this.attackActiveEnd && !this.attackDone) {
        this.attackDone = true;
        this.resolveAttack(game);
      }
      if (this.attackTime <= 0) {
        this.anim = 'idle';
        this.attackPhase = null;
      }
    } else if (this.castTime > 0) {
      this.anim = 'cast';
    } else if (this.dodging()) {
      this.anim = 'dodge';
      this.invuln = Math.max(this.invuln, 0.08);
      if (Math.random() < 0.5) game.particles.spawn('smoke', this.x, this.y + 8, { color: '#c7a4ff', size: 5, life: 0.35, speed: 10, additive: false });
    } else if (this.blocking) {
      this.anim = 'block';
    }

    // Sombra del Velo (habilidad de esquiva).
    if (this.dodging() && this.hasSkill('veil_step') && Math.random() < 0.6) {
      game.particles.spawn('smoke', this.x, this.y, { color: '#7d6a9e', size: 4, life: 0.3, speed: 6, additive: false });
    }
    this.animTime += dt;
  }

  getAimAngle(game, input) {
    const axis = input.axis();
    if (input.touchMode) {
      const target = game.nearestEnemy(this.x, this.y, 320);
      if (target) return Math.atan2(target.y - this.y, target.x - this.x);
      if (axis.len > 0.1) return Math.atan2(axis.y, axis.x);
      return this.facing;
    }
    const w = game.camera.screenToWorld(input.mouse.x, input.mouse.y);
    if (game.autoAim && game.nearestEnemy(this.x, this.y, 260)) {
      const t = game.nearestEnemy(this.x, this.y, 260);
      return Math.atan2(t.y - this.y, t.x - this.x);
    }
    if (input.mouse.x || input.mouse.y) return Math.atan2(w.y - this.y, w.x - this.x);
    if (axis.len > 0.1) return Math.atan2(axis.y, axis.x);
    return this.facing;
  }

  attacking() { return this.attackTime > 0; }
  dodging() { return this.dodgeTime > 0; }

  startAttack(heavy, game) {
    if (heavy && this.stamina < 20) { game.ui.toast('Sin resistencia', 'No puedes ejecutar un ataque pesado.', 'warn'); return; }
    this.heavy = heavy;
    this.attackDone = false;
    this.attackHit.clear();
    if (heavy) {
      this.stamina -= 20;
      this.attackDuration = 0.62 / this.weaponSpeed;
      this.attackActiveEnd = this.attackDuration * 0.48;
      this.attackPhase = 'active';
      this.attackTime = this.attackDuration;
      this.anim = 'heavy';
      game.audio.sfx('heavy');
    } else {
      if (this.comboTimer > 0) this.attackIndex = (this.attackIndex + 1) % 3;
      else this.attackIndex = 0;
      this.comboTimer = 0.75;
      this.stamina = Math.max(0, this.stamina - 6);
      const speed = this.weaponSpeed * (this.hasSkill('blade_rhythm') ? 1.2 : 1);
      this.attackDuration = (0.36 + this.attackIndex * 0.05) / speed;
      this.attackActiveEnd = this.attackDuration * 0.5;
      this.attackPhase = 'active';
      this.attackTime = this.attackDuration;
      this.anim = 'attack' + this.attackIndex;
      game.audio.sfx('attack', { volume: 0.8 });
    }
    this.animTime = 0;
  }

  resolveAttack(game) {
    const wt = WEAPON_TYPES[game.inventory.weaponType()] || WEAPON_TYPES.sword;
    const range = wt.range + (this.heavy ? 10 : 0);
    const arc = wt.arc + (this.heavy ? 0.3 : 0);
    const base = (this.attack + (this.heavy ? 8 : 0)) * wt.damage * (this.heavy ? 1.55 : 1);
    const crit = Math.random() < this.crit;
    const dmg = Math.round(base * (crit ? 1.7 : 1));
    const hitAny = [];
    for (const e of game.enemies) {
      if (e.dead || e.captured) continue;
      const d = dist(this.x, this.y, e.x, e.y);
      if (d > range + e.radius) continue;
      const a = Math.atan2(e.y - this.y, e.x - this.x);
      if (Math.abs(angleDiff(this.facing, a)) > arc / 2) continue;
      if (this.attackHit.has(e)) continue;
      this.attackHit.add(e);
      const res = e.takeDamage(dmg, { source: 'player', crit, element: this.heavy ? 'fuego' : null, game });
      if (res) {
        hitAny.push(e);
        if (this.hasSkill('blade_edge') && this.heavy) e.applyStatus('burn', 4, game);
        if (this.lifesteal) this.heal(dmg * this.lifesteal);
        this.addUlt(crit ? 9 : 6);
        game.hitstop = Math.max(game.hitstop, this.heavy ? 0.09 : 0.045);
        game.camera.addShake(this.heavy ? 8 : 4);
        game.particles.burst(e.x, e.y - 10, this.heavy ? 18 : 10, { color: crit ? '#ffe7a8' : '#ffb86a', speed: 150, life: 0.5, size: 2.6 });
        game.particles.number(e.x, e.y - e.radius - 18, `${dmg}${crit ? '!' : ''}`, crit ? '#ffe7a8' : '#fff3d0', crit ? 22 : 16, crit);
        game.audio.sfx(crit ? 'crit' : 'hit', { pan: clamp((e.x - this.x) / 300, -1, 1) });
      }
    }
    if (hitAny.length) {
      this.damageDealt += dmg * hitAny.length;
    } else {
      // Golpe al aire: pequeña onda visual.
      game.particles.slash(this.x + Math.cos(this.facing) * 18, this.y + Math.sin(this.facing) * 18 - 6, this.facing, { radius: range * 0.7, color: this.heavy ? '#ff9a5c' : '#ffe7a8', arc, width: this.heavy ? 10 : 7 });
    }
    if (!this.heavy) {
      game.particles.slash(this.x + Math.cos(this.facing) * 16, this.y + Math.sin(this.facing) * 16 - 8, this.facing, { radius: range * 0.8, color: this.heavy ? '#ff9a5c' : '#ffe7a8', arc, width: this.heavy ? 11 : 7 });
    }
  }

  startDodge(axis, game) {
    this.stamina -= 16;
    this.dodgeTime = 0.3;
    this.dodgeCd = this.dodgeCdMax;
    this.invuln = 0.24;
    this.dodgeAngle = axis.len > 0.1 ? Math.atan2(axis.y, axis.x) : this.facing;
    this.anim = 'dodge';
    game.audio.sfx('dodge');
  }

  castSelected(game) {
    const spell = SPELLS[this.selectedSpell];
    if (!spell) return;
    this.castSpellById(spell.id, game);
  }

  castSpellById(id, game) {
    const spell = SPELLS.find(s => s.id === id);
    if (!spell) return;
    const cost = Math.round(spell.cost * (this.origin === 'velo' ? 0.9 : 1));
    if (this.mp < cost) { game.ui.toast('Maná insuficiente', spell.name, 'warn'); game.audio.sfx('error'); return; }
    if (this.spellCooldowns[SPELLS.indexOf(spell)] > 0) return;
    if (this.castTime > 0 || this.attacking() || this.dodging()) return;
    this.mp -= cost;
    this.spellCooldowns[SPELLS.indexOf(spell)] = spell.cooldown;
    this.castTime = 0.25;
    this.anim = 'cast';
    game.audio.sfx(id === 'rayo' ? 'spell' : id === 'nova' ? 'fire' : 'waypoint');
    const aim = this.facing;
    if (id === 'rayo') {
      game.spawnProjectile({
        x: this.x + Math.cos(aim) * 18, y: this.y + Math.sin(aim) * 18 - 8,
        vx: Math.cos(aim) * 430, vy: Math.sin(aim) * 430,
        radius: 9, damage: Math.round(this.spellPower * (this.game.inventory.weaponType() === 'staff' ? 1.2 : 1)),
        color: '#ffe7a8', owner: 'player', life: 1.1, pierce: false, element: 'luz',
        onHit: (enemy) => { if (this.hasSkill('veil_mark')) enemy.applyStatus('mark', 6, game); },
      });
      game.particles.beam(this.x, this.y - 8, aim, { radius: 40, color: '#ffe7a8', width: 5, life: 0.12 });
    } else if (id === 'nova') {
      game.particles.ring(this.x, this.y, { radius: 20, target: 130, color: '#c7a4ff', width: 8, life: 0.5 });
      for (const e of game.enemies) {
        if (e.dead) continue;
        if (dist(this.x, this.y, e.x, e.y) < 130 + e.radius) {
          const dmg = Math.round(this.spellPower * 0.9);
          e.takeDamage(dmg, { source: 'player', element: 'luz', game });
          e.applyStatus('slow', 2.5, game);
          if (this.hasSkill('veil_mark')) e.applyStatus('mark', 6, game);
          game.particles.number(e.x, e.y - 20, `${dmg}`, '#c7a4ff', 16);
        }
      }
      game.camera.addShake(9);
      this.addUlt(10);
    } else if (id === 'barrera') {
      this.status.shield = 7;
      this.shieldAmount = Math.round(this.maxHp * 0.25);
      this.heal(Math.round(this.maxHp * 0.12));
      game.particles.ring(this.x, this.y, { radius: 10, target: 42, color: '#9fe8ff', width: 4, life: 0.6 });
      game.particles.burst(this.x, this.y - 10, 22, { color: '#9fe8ff', speed: 70, life: 0.8, size: 2.5 });
    }
  }

  useUltimate(game) {
    if (!this.ultType) { game.ui.toast('Definitiva bloqueada', 'Aprende una habilidad definitiva en el árbol de habilidades.', 'warn'); return; }
    if (this.ult < 100 || this.ultActive > 0) { if (this.ult < 100) game.audio.sfx('error'); return; }
    this.ult = 0;
    this.ultActive = 1.2;
    this.invuln = 1.2;
    game.audio.sfx('boss');
    game.camera.addShake(18);
    if (this.ultType === 'blade') {
      game.particles.ring(this.x, this.y, { radius: 20, target: 170, color: '#ffe7a8', width: 12, life: 0.7 });
      for (let i = 0; i < 3; i++) {
        setTimeout(() => {
          if (!this.dead) {
            game.particles.slash(this.x, this.y, Math.random() * TAU, { radius: 110, color: '#ffe7a8', arc: TAU, width: 14 });
            for (const e of game.enemies) {
              if (!e.dead && dist(this.x, this.y, e.x, e.y) < 180 + e.radius) {
                const dmg = Math.round(this.attack * 2.4);
                e.takeDamage(dmg, { source: 'player', crit: true, game });
                game.particles.number(e.x, e.y - 24, `${dmg}`, '#ffe7a8', 24, true);
              }
            }
          }
        }, i * 180);
      }
      game.ui.toast('TORMENTA CELESTIAL', 'El acero recuerda su nombre.', 'ult');
    } else if (this.ultType === 'veil') {
      game.particles.ring(this.x, this.y, { radius: 20, target: 260, color: '#c7a4ff', width: 10, life: 0.8 });
      for (const e of game.enemies) {
        if (e.dead) continue;
        if (dist(this.x, this.y, e.x, e.y) < 260 + e.radius) {
          e.applyStatus('freeze', 4, game);
          const dmg = Math.round(this.spellPower * 1.8);
          e.takeDamage(dmg, { source: 'player', element: 'luz', game });
          game.particles.number(e.x, e.y - 22, `${dmg}`, '#c7a4ff', 22, true);
        }
      }
      this.mp = this.maxMp;
      game.ui.toast('NOVA DEL VELO', 'El silencio se vuelve forma.', 'ult');
    } else {
      this.heal(Math.round(this.maxHp * 0.5));
      game.summonAllCompanions();
      game.ui.toast('DESPERTAR', 'Todas tus resonancias responden.', 'ult');
    }
  }

  usePotion(game) {
    if (this.potionCd > 0) return;
    if (!game.inventory.has('potion_lumen')) { game.ui.toast('Sin pociones', 'No te queda Poción de Lumen.', 'warn'); return; }
    this.potionCd = 3.2;
    game.inventory.remove('potion_lumen', 1);
    this.heal(Math.round(this.maxHp * 0.45 * this.difficulty.potion));
    game.audio.sfx('potion');
    game.particles.burst(this.x, this.y - 10, 16, { color: '#ff7b7b', speed: 50, life: 0.7, size: 2.5 });
  }

  takeDamage(amount, { source = 'enemy', element = null, game = this.game, ignoreBlock = false } = {}) {
    if (this.dead || this.invuln > 0 || this.dodging()) return 0;
    if (this.parryTimer > 0 && !ignoreBlock) {
      this.parryTimer = 0;
      this.mp = Math.min(this.maxMp, this.mp + 15);
      this.addUlt(12);
      game.audio.sfx('parry');
      game.hitstop = 0.12;
      game.camera.addShake(7);
      game.particles.ring(this.x, this.y, { radius: 12, target: 70, color: '#ffe7a8', width: 5, life: 0.4 });
      if (this.hasSkill('blade_guard')) {
        for (const e of game.enemies) {
          if (!e.dead && dist(this.x, this.y, e.x, e.y) < 120) {
            e.stagger(1.6, game);
            e.takeDamage(Math.round(this.attack * 0.8), { source: 'player', game });
          }
        }
      }
      return 0;
    }
    let dmg = amount * (1 - this.damageReduction);
    if (this.blocking) {
      const staminaCost = dmg * 0.9;
      if (this.stamina >= staminaCost) {
        this.stamina -= staminaCost;
        dmg *= 0.25;
        game.particles.burst(this.x, this.y - 10, 6, { color: '#9fe8ff', speed: 70, life: 0.35, size: 2 });
      } else {
        this.stamina = 0;
        this.blocking = false;
        game.ui.toast('Guardia rota', 'La resistencia se ha agotado.', 'warn');
      }
    }
    if (this.status.shield > 0 && this.shieldAmount > 0) {
      const absorbed = Math.min(this.shieldAmount, dmg);
      this.shieldAmount -= absorbed;
      dmg -= absorbed;
      if (this.shieldAmount <= 0) delete this.status.shield;
    }
    dmg = Math.max(1, Math.round(dmg));
    this.hp -= dmg;
    this.damageTaken += dmg;
    this.addUlt(3);
    this.invuln = 0.55;
    this.hurtFlash = 0.25;
    game.camera.addShake(6);
    game.audio.sfx('hit');
    game.particles.number(this.x, this.y - 40, `-${dmg}`, '#ff7b7b', 16);
    game.particles.burst(this.x, this.y - 10, 10, { color: '#ff7b7b', speed: 90, life: 0.5, size: 2.2 });
    if (this.hp <= 0) this.die();
    return dmg;
  }

  die() {
    if (this.dead) return;
    this.dead = true;
    this.hp = 0;
    this.anim = 'dead';
    this.animTime = 0;
    this.game.audio.sfx('death');
    this.game.onPlayerDeath();
  }

  reviveAt(x, y) {
    this.dead = false;
    this.deadTime = 0;
    this.hp = Math.round(this.maxHp * 0.55);
    this.mp = Math.round(this.maxMp * 0.5);
    this.stamina = this.maxStamina;
    this.invuln = 2;
    this.status = {};
    this.x = x; this.y = y;
    this.anim = 'idle';
  }

  serialize() {
    return {
      name: this.name, origin: this.origin, appearance: { ...this.appearance },
      baseStats: { ...this.baseStats }, bonusCrit: this.bonusCrit,
      level: this.level, xp: this.xp, xpNext: this.xpNext, points: this.points,
      skillPoints: this.skillPoints, skills: { ...this.skills },
      gold: this.gold, hp: this.hp, mp: this.mp, stamina: this.stamina,
      region: this.region, x: this.x, y: this.y, lastWaypoint: this.lastWaypoint,
      kills: this.kills, captures: this.captures, damageDealt: this.damageDealt,
      damageTaken: this.damageTaken, playtime: this.playtime, ultType: this.ultType,
    };
  }
  deserialize(data) {
    this.name = data.name || 'Peregrino';
    this.origin = data.origin || 'brasa';
    this.appearance = { ...DEFAULT_APPEARANCE, ...(data.appearance || {}) };
    this.baseStats = { ...BASE_STATS, ...(data.baseStats || {}) };
    this.bonusCrit = data.bonusCrit || 0;
    this.level = data.level || 1;
    this.xp = data.xp || 0;
    this.xpNext = data.xpNext || (80 + this.level * 60);
    this.points = data.points || 0;
    this.skillPoints = data.skillPoints || 0;
    this.skills = { ...(data.skills || {}) };
    this.gold = data.gold || 0;
    this.hp = data.hp ?? 100;
    this.mp = data.mp ?? 30;
    this.stamina = data.stamina ?? 60;
    this.region = data.region || 'valdoria';
    this.x = data.x || 0; this.y = data.y || 0;
    this.lastWaypoint = data.lastWaypoint || null;
    this.kills = data.kills || 0;
    this.captures = data.captures || 0;
    this.damageDealt = data.damageDealt || 0;
    this.damageTaken = data.damageTaken || 0;
    this.playtime = data.playtime || 0;
    this.ultType = data.ultType || null;
    this.recalc(true);
    this.hp = Math.min(this.hp, this.maxHp);
    this.mp = Math.min(this.mp, this.maxMp);
    this.stamina = Math.min(this.stamina, this.maxStamina);
  }
}

import { dist, TAU } from '../core/utils.js';

export class Projectile {
  constructor(opts) {
    Object.assign(this, {
      x: 0, y: 0, vx: 0, vy: 0, radius: 8, damage: 10, color: '#ffe7a8',
      owner: 'player', life: 1.2, maxLife: 1.2, pierce: false, homing: 0,
      target: null, onHit: null, element: null, dead: false, trail: true,
      trailColor: null, glow: true, knockback: 0, hitSet: new Set(),
    }, opts);
    this.maxLife = this.life;
  }

  update(dt, game) {
    if (this.dead) return;
    this.life -= dt;
    if (this.life <= 0) { this.dead = true; return; }
    if (this.homing && this.target && !this.target.dead) {
      const a = Math.atan2(this.target.y - this.y, this.target.x - this.x);
      const speed = Math.hypot(this.vx, this.vy);
      this.vx += Math.cos(a) * speed * this.homing * dt;
      this.vy += Math.sin(a) * speed * this.homing * dt;
      const s = Math.hypot(this.vx, this.vy);
      if (s > 0) { this.vx = this.vx / s * speed; this.vy = this.vy / s * speed; }
    }
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    if (this.trail) {
      game.particles.spawn('spark', this.x, this.y, {
        color: this.trailColor || this.color, size: 1.8 + Math.random() * 1.4,
        life: 0.22, speed: 8, additive: true, drag: 4,
      });
    }
    if (game.world.isSolidPx(this.x, this.y)) {
      this.dead = true;
      game.particles.burst(this.x, this.y, 6, { color: this.color, speed: 70, life: 0.35, size: 2 });
      return;
    }
    if (this.owner === 'player') {
      for (const e of game.enemies) {
        if (e.dead || e.captured || this.hitSet.has(e)) continue;
        if (dist(this.x, this.y, e.x, e.y) < this.radius + e.radius) {
          this.hitSet.add(e);
          const res = e.takeDamage(this.damage, { source: 'player', element: this.element, game });
          if (res) {
            this.onHit?.(e);
            game.particles.burst(this.x, this.y, 12, { color: this.color, speed: 120, life: 0.4, size: 2.5 });
            game.audio.sfx('hit');
            game.camera.addShake(3);
          }
          if (!this.pierce) { this.dead = true; return; }
        }
      }
    } else {
      const p = game.player;
      if (!p.dead && dist(this.x, this.y, p.x, p.y) < this.radius + p.radius) {
        p.takeDamage(this.damage, { source: 'enemy', element: this.element, game });
        game.particles.burst(this.x, this.y, 10, { color: this.color, speed: 90, life: 0.4, size: 2.2 });
        this.dead = true;
        return;
      }
    }
  }

  draw(ctx) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = this.color;
    ctx.globalAlpha = 0.25;
    ctx.beginPath(); ctx.arc(this.x, this.y, this.radius * 2.4, 0, TAU); ctx.fill();
    ctx.globalAlpha = 1;
    ctx.beginPath(); ctx.arc(this.x, this.y, this.radius, 0, TAU); ctx.fill();
    ctx.fillStyle = '#fffbe8';
    ctx.beginPath(); ctx.arc(this.x, this.y, this.radius * 0.45, 0, TAU); ctx.fill();
    ctx.restore();
  }
}

export class Zone {
  constructor(opts) {
    Object.assign(this, {
      x: 0, y: 0, radius: 60, life: 2, maxLife: 2, damage: 0, tick: 0.5,
      color: '#ff9a5c', type: 'fire', owner: 'enemy', dead: false, warned: false,
      warnTime: 0.6, status: null, tickTimer: 0, hitOnce: false,
    }, opts);
    this.maxLife = this.life;
  }

  update(dt, game) {
    if (this.dead) return;
    this.life -= dt;
    this.tickTimer -= dt;
    if (this.life <= 0) { this.dead = true; return; }
    if (this.life > this.maxLife - this.warnTime) return; // telegraph
    if (this.owner === 'enemy') {
      const p = game.player;
      if (!p.dead && dist(this.x, this.y, p.x, p.y) < this.radius + p.radius && this.tickTimer <= 0) {
        this.tickTimer = this.tick;
        p.takeDamage(this.damage, { source: 'enemy', element: this.type, game });
        if (this.status) p.status[this.status] = 2;
      }
    }
    if (Math.random() < 0.3) {
      game.particles.spawn('ember', this.x + (Math.random() - 0.5) * this.radius * 1.6, this.y + (Math.random() - 0.5) * this.radius * 0.8, {
        color: this.color, size: 2, life: 0.6, speed: 20, gravity: -10, additive: true,
      });
    }
  }

  draw(ctx) {
    const t = this.life / this.maxLife;
    const warning = this.life > this.maxLife - this.warnTime;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    if (warning) {
      ctx.globalAlpha = 0.35 + Math.sin(this.life * 24) * 0.2;
      ctx.strokeStyle = this.color;
      ctx.lineWidth = 2;
      ctx.setLineDash([6, 5]);
      ctx.beginPath(); ctx.ellipse(this.x, this.y, this.radius, this.radius * 0.55, 0, 0, TAU); ctx.stroke();
      ctx.setLineDash([]);
    } else {
      ctx.globalAlpha = 0.22 * Math.min(1, t * 3);
      ctx.fillStyle = this.color;
      ctx.beginPath(); ctx.ellipse(this.x, this.y, this.radius, this.radius * 0.55, 0, 0, TAU); ctx.fill();
      ctx.globalAlpha = 0.7;
      ctx.strokeStyle = this.color;
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.ellipse(this.x, this.y, this.radius, this.radius * 0.55, 0, 0, TAU); ctx.stroke();
    }
    ctx.restore();
  }
}

import { ENEMIES } from '../data/enemies.js';
import { Projectile } from './combat.js';
import { clamp, dist, angleDiff, TAU, randRange } from '../core/utils.js';

export class Enemy {
  constructor(game, typeId, x, y, opts = {}) {
    this.game = game;
    this.typeId = typeId;
    this.def = ENEMIES[typeId];
    if (!this.def) throw new Error('Enemigo desconocido: ' + typeId);
    this.x = x; this.y = y;
    this.spawnX = x; this.spawnY = y;
    this.level = opts.level || this.def.level;
    this.elite = Boolean(opts.elite);
    this.radius = this.def.radius * (this.elite ? 1.15 : 1);
    this.scale = (this.def.scale || 1) * (this.elite ? 1.12 : 1);
    this.sprite = this.def.sprite;
    this.hp = this.maxHp = this.calcHp();
    this.attack = this.calcAtk();
    this.defense = this.def.def * (1 + Math.max(0, this.level - this.def.level) * 0.1);
    this.speed = this.def.speed * (this.elite ? 1.08 : 1);
    this.facing = Math.PI / 2;
    this.anim = 'idle';
    this.animTime = Math.random() * 4;
    this.state = this.def.behavior === 'flee' ? 'flee' : 'idle';
    this.stateTimer = 0;
    this.cooldown = randRange(Math.random, 0.4, 1.6);
    this.wanderTimer = randRange(Math.random, 1, 3);
    this.wanderTarget = null;
    this.path = [];
    this.pathTimer = 0;
    this.flash = 0;
    this.staggerTimer = 0;
    this.status = {};
    this.dead = false;
    this.captured = false;
    this.deathTime = 0;
    this.dashDir = 0;
    this.dashTimer = 0;
    this.enraged = false;
    this.aggro = false;
    this.hitPlayerThisDash = false;
    this.name = this.def.name + (this.elite ? ' · Élite' : '');
  }

  calcHp() {
    const d = this.def;
    const lvl = Math.max(0, this.level - d.level);
    return Math.round(d.hp * (1 + lvl * 0.17) * (this.elite ? 1.7 : 1) * this.game.difficulty.enemyHp);
  }
  calcAtk() {
    const d = this.def;
    const lvl = Math.max(0, this.level - d.level);
    return Math.round(d.atk * (1 + lvl * 0.12) * (this.elite ? 1.3 : 1) * this.game.difficulty.enemyDmg);
  }
  get hpRatio() { return clamp(this.hp / this.maxHp, 0, 1); }

  update(dt, game) {
    this.animTime += dt;
    this.flash = Math.max(0, this.flash - dt);
    if (this.dead) { this.deathTime += dt; return; }
    if (this.captured) return;

    for (const [k, v] of Object.entries(this.status)) {
      this.status[k] = v - dt;
      if (this.status[k] <= 0) delete this.status[k];
    }
    if (this.status.burn) {
      this.hp -= 5 * dt;
      if (Math.random() < 0.3) game.particles.spawn('ember', this.x + randRange(Math.random, -8, 8), this.y - 10, { color: '#ff9a5c', size: 2, life: 0.4, speed: 20, additive: true });
    }
    if (this.status.poison) this.hp -= 3 * dt;
    if (this.hp <= 0) { this.die(game); return; }
    if (this.status.freeze || this.status.stun) { this.anim = 'idle'; return; }

    const p = game.player;
    const d = dist(this.x, this.y, p.x, p.y);
    if (this.state === 'stagger') {
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) this.state = 'chase';
      return;
    }
    if (p.dead) { this.state = 'idle'; return; }
    if (d < this.def.aggro) this.aggro = true;
    if (d > this.def.aggro * 1.8) this.aggro = false;
    const slow = this.status.slow ? 0.55 : 1;
    const speed = this.speed * slow * (this.enraged ? 1.2 : 1);
    this.cooldown = Math.max(0, this.cooldown - dt);

    if (this.def.behavior === 'flee') {
      this.updateFlee(dt, game, d, speed);
      return;
    }
    if (!this.aggro) {
      this.updateIdle(dt, game, speed);
      return;
    }

    if (this.state === 'windup') {
      this.stateTimer -= dt;
      this.facing = Math.atan2(p.y - this.y, p.x - this.x);
      if (this.stateTimer <= 0) this.executeAttack(game, d);
      return;
    }
    if (this.state === 'recover') {
      this.stateTimer -= dt;
      if (this.stateTimer <= 0) this.state = 'chase';
      return;
    }
    if (this.state === 'dash') {
      this.updateDash(dt, game);
      return;
    }
    if (this.state === 'chase') {
      this.facing = Math.atan2(p.y - this.y, p.x - this.x);
      const range = this.def.range;
      const behavior = this.def.behavior;
      if (behavior === 'melee' || behavior === 'teleporter') {
        if (d <= range + p.radius && this.cooldown <= 0) this.startWindup('melee', 0.42, game);
        else this.moveToward(p.x, p.y, speed, dt, game);
      } else if (behavior === 'charger') {
        if (d <= range + p.radius && this.cooldown <= 0) this.startWindup('charge', 0.7, game);
        else this.moveToward(p.x, p.y, speed, dt, game);
      } else if (behavior === 'ranged') {
        if (d < range * 0.55) this.moveAway(p.x, p.y, speed * 0.9, dt, game);
        else if (d > range * 0.8) this.moveToward(p.x, p.y, speed, dt, game);
        else this.strafe(p.x, p.y, speed * 0.6, dt, game);
        if (d <= range && this.cooldown <= 0) this.startWindup('shoot', 0.55, game);
      } else if (behavior === 'breather') {
        if (d <= range + p.radius && this.cooldown <= 0) this.startWindup('breath', 0.8, game);
        else this.moveToward(p.x, p.y, speed, dt, game);
      } else if (behavior === 'beam') {
        if (d <= range && this.cooldown <= 0) this.startWindup('beam', 0.9, game);
        else this.moveToward(p.x, p.y, speed, dt, game);
      } else if (behavior === 'diver') {
        if (d <= range + p.radius && this.cooldown <= 0) this.startWindup('dive', 0.55, game);
        else this.moveToward(p.x, p.y, speed, dt, game);
      }
      return;
    }
    this.state = 'chase';
  }

  updateIdle(dt, game, speed) {
    this.wanderTimer -= dt;
    if (this.wanderTimer <= 0) {
      this.wanderTimer = randRange(Math.random, 2, 5);
      this.wanderTarget = this.game.world.randomFreeNear(this.spawnX, this.spawnY, 90);
    }
    if (this.wanderTarget) {
      const d = dist(this.x, this.y, this.wanderTarget.x, this.wanderTarget.y);
      if (d < 8) { this.wanderTarget = null; this.anim = 'idle'; }
      else { this.facing = Math.atan2(this.wanderTarget.y - this.y, this.wanderTarget.x - this.x); this.moveToward(this.wanderTarget.x, this.wanderTarget.y, speed * 0.32, dt, game); }
    }
  }

  updateFlee(dt, game, d, speed) {
    const p = game.player;
    if (d < 260) {
      const a = Math.atan2(this.y - p.y, this.x - p.x);
      this.facing = a;
      this.moveToward(this.x + Math.cos(a) * 100, this.y + Math.sin(a) * 100, speed, dt, game);
      this.anim = 'run';
    } else {
      this.anim = 'idle';
      this.updateIdle(dt, game, speed);
    }
  }

  moveToward(tx, ty, speed, dt, game) {
    const w = game.world;
    this.pathTimer -= dt;
    const dx = tx - this.x, dy = ty - this.y;
    const d = Math.hypot(dx, dy);
    if (d < 1) return;
    let mx = dx / d, my = dy / d;
    if (this.pathTimer <= 0 && w.circleBlocked(this.x + mx * 18, this.y + my * 18, this.radius)) {
      this.pathTimer = 0.8;
      this.path = w.findPath(this.x, this.y, tx, ty, 1800);
    }
    if (this.path.length) {
      const wp = this.path[0];
      const ddx = wp.x - this.x, ddy = wp.y - this.y;
      const dd = Math.hypot(ddx, ddy);
      if (dd < 10) this.path.shift();
      else { mx = ddx / dd; my = ddy / dd; }
    }
    const step = speed * dt;
    const moved = w.moveCircle(this.x, this.y, mx * step, my * step, this.radius);
    this.x = moved.x; this.y = moved.y;
    this.anim = 'walk';
    // Separación suave.
    for (const e of game.enemies) {
      if (e === this || e.dead) continue;
      const dd = dist(this.x, this.y, e.x, e.y);
      const min = this.radius + e.radius + 2;
      if (dd > 0 && dd < min) {
        const push = (min - dd) * 0.5;
        this.x += (this.x - e.x) / dd * push;
        this.y += (this.y - e.y) / dd * push;
      }
    }
  }

  moveAway(tx, ty, speed, dt, game) {
    const a = Math.atan2(this.y - ty, this.x - tx);
    this.moveToward(this.x + Math.cos(a) * 80, this.y + Math.sin(a) * 80, speed, dt, game);
  }
  strafe(tx, ty, speed, dt, game) {
    const a = Math.atan2(this.y - ty, this.x - tx) + Math.PI / 2;
    this.moveToward(this.x + Math.cos(a) * 70, this.y + Math.sin(a) * 70, speed, dt, game);
  }

  startWindup(type, duration, game) {
    this.state = 'windup';
    this.attackType = type;
    this.stateTimer = duration;
    this.anim = 'windup';
    if (type === 'shoot') this.facing = Math.atan2(game.player.y - this.y, game.player.x - this.x);
  }

  executeAttack(game, d) {
    const p = game.player;
    const def = this.def;
    if (this.attackType === 'melee') {
      this.facing = Math.atan2(p.y - this.y, p.x - this.x);
      if (dist(this.x, this.y, p.x, p.y) <= def.range + p.radius + 14) {
        p.takeDamage(this.attack, { source: 'enemy', game });
      }
      game.particles.slash(this.x + Math.cos(this.facing) * 18, this.y + Math.sin(this.facing) * 18 - 8, this.facing, { radius: 34, color: this.elite ? '#ffcf6a' : '#ff9a5c', arc: 1.4, width: 6 });
      game.audio.sfx('attack', { volume: 0.5 });
      this.state = 'recover'; this.stateTimer = 0.5; this.cooldown = 0.8;
    } else if (this.attackType === 'shoot') {
      const a = Math.atan2(p.y - this.y, p.x - this.x);
      const isFire = def.projectile === 'fire';
      game.spawnProjectile({
        x: this.x + Math.cos(a) * 18, y: this.y + Math.sin(a) * 18 - 8,
        vx: Math.cos(a) * 260, vy: Math.sin(a) * 260, radius: 8,
        damage: this.attack, color: isFire ? '#ff9a5c' : '#8fd18a', owner: 'enemy',
        life: 2.2, element: isFire ? 'fuego' : 'naturaleza',
      });
      game.audio.sfx(isFire ? 'fire' : 'spell', { volume: 0.5 });
      this.state = 'recover'; this.stateTimer = 0.65; this.cooldown = 1.5;
    } else if (this.attackType === 'charge') {
      this.state = 'dash';
      this.dashDir = Math.atan2(p.y - this.y, p.x - this.x);
      this.dashTimer = 0.42;
      this.hitPlayerThisDash = false;
      game.audio.sfx('heavy', { volume: 0.6 });
    } else if (this.attackType === 'breath') {
      const a = Math.atan2(p.y - this.y, p.x - this.x);
      const angleOk = Math.abs(angleDiff(a, Math.atan2(p.y - this.y, p.x - this.x))) < 0.7;
      if (d < def.range + p.radius + 30 && angleOk) p.takeDamage(this.attack, { source: 'enemy', element: 'fuego', game });
      for (let i = 0; i < 14; i++) {
        const aa = a + randRange(Math.random, -0.55, 0.55);
        game.particles.spawn('ember', this.x, this.y - 8, { angle: aa, speed: randRange(Math.random, 80, 220), color: '#ff7b3d', life: 0.7, size: 3, additive: true });
      }
      game.audio.sfx('fire');
      this.state = 'recover'; this.stateTimer = 0.9; this.cooldown = 2.2;
    } else if (this.attackType === 'beam') {
      const a = Math.atan2(p.y - this.y, p.x - this.x);
      const hit = this.lineHitsPlayer(a, 320, p, 16);
      game.particles.beam(this.x, this.y - 10, a, { radius: 320, color: '#ffe7a8', width: 9, life: 0.25 });
      if (hit) p.takeDamage(this.attack, { source: 'enemy', element: 'luz', game });
      game.audio.sfx('spell');
      this.state = 'recover'; this.stateTimer = 1; this.cooldown = 2.6;
    } else if (this.attackType === 'dive') {
      this.state = 'dash';
      this.dashDir = Math.atan2(p.y - this.y, p.x - this.x);
      this.dashTimer = 0.38;
      this.hitPlayerThisDash = false;
      game.audio.sfx('dodge', { volume: 0.6 });
    } else if (this.attackType === 'teleport') {
      const angle = Math.random() * TAU;
      const nx = p.x + Math.cos(angle) * 44, ny = p.y + Math.sin(angle) * 44;
      if (!game.world.circleBlocked(nx, ny, this.radius)) {
        game.particles.burst(this.x, this.y - 10, 16, { color: '#b49ad9', speed: 80, life: 0.4, size: 2.5 });
        this.x = nx; this.y = ny;
        game.particles.burst(this.x, this.y - 10, 16, { color: '#b49ad9', speed: 80, life: 0.4, size: 2.5 });
      }
      this.state = 'recover'; this.stateTimer = 0.5; this.cooldown = 1.8;
    }
  }

  lineHitsPlayer(angle, length, p, width) {
    const dx = p.x - this.x, dy = p.y - this.y;
    const proj = dx * Math.cos(angle) + dy * Math.sin(angle);
    if (proj < 0 || proj > length) return false;
    const perp = Math.abs(-dx * Math.sin(angle) + dy * Math.cos(angle));
    return perp < width + p.radius;
  }

  updateDash(dt, game) {
    this.dashTimer -= dt;
    this.anim = 'dash';
    const speed = this.def.behavior === 'diver' ? 460 : 360;
    const moved = game.world.moveCircle(this.x, this.y, Math.cos(this.dashDir) * speed * dt, Math.sin(this.dashDir) * speed * dt, this.radius);
    this.x = moved.x; this.y = moved.y;
    game.particles.spawn('smoke', this.x, this.y, { color: this.def.behavior === 'diver' ? '#ffe7a8' : '#ff9a5c', size: 4, life: 0.35, speed: 10, additive: false });
    const p = game.player;
    if (!this.hitPlayerThisDash && dist(this.x, this.y, p.x, p.y) < this.radius + p.radius + 8) {
      this.hitPlayerThisDash = true;
      p.takeDamage(this.attack * 1.15, { source: 'enemy', game });
      game.camera.addShake(7);
    }
    if (this.dashTimer <= 0) {
      this.state = 'recover';
      this.stateTimer = 0.8;
      this.cooldown = 1.4;
    }
  }

  takeDamage(amount, { source = 'player', crit = false, element = null, game = this.game } = {}) {
    if (this.dead || this.captured) return false;
    const mark = this.status.mark ? 1.2 : 1;
    const defense = this.defense / (this.defense + 100);
    const dmg = Math.max(1, Math.round(amount * (1 - defense) * mark));
    this.hp -= dmg;
    this.flash = 0.12;
    this.aggro = true;
    if (this.state === 'idle' || this.state === 'chase') {
      if (dmg > this.maxHp * 0.12) this.stagger(0.22, game);
    }
    if (this.hp <= 0) this.die(game);
    else if (this.hpRatio < 0.3 && !this.enraged && !this.def.boss) {
      this.enraged = true;
      game.particles.ring(this.x, this.y, { radius: 10, target: 50, color: '#ff7b4d', width: 3, life: 0.5 });
    }
    return true;
  }

  stagger(duration, game) {
    this.state = 'stagger';
    this.stateTimer = duration;
    this.anim = 'stagger';
    game.particles.ring(this.x, this.y, { radius: 8, target: 30, color: '#ffe7a8', width: 2, life: 0.3 });
  }

  applyStatus(type, duration, game) {
    this.status[type] = Math.max(this.status[type] || 0, duration);
    if (type === 'burn') game.particles.burst(this.x, this.y - 8, 6, { color: '#ff9a5c', speed: 40, life: 0.5, size: 2 });
  }

  die(game) {
    if (this.dead) return;
    this.dead = true;
    this.state = 'dead';
    this.deathTime = 0;
    this.hp = 0;
    game.particles.burst(this.x, this.y - 10, 26, { color: this.elite ? '#ffcf6a' : '#ffe7a8', speed: 140, life: 0.9, size: 3 });
    game.particles.ring(this.x, this.y, { radius: 6, target: 44, color: '#ffe7a8', width: 3, life: 0.5 });
    game.audio.sfx('death', { volume: 0.4 });
    game.onEnemyKilled(this);
  }

  captureSuccess(game) {
    this.captured = true;
    this.dead = true;
    this.deathTime = 0;
    game.particles.burst(this.x, this.y - 10, 34, { color: '#c7a4ff', speed: 110, life: 1.1, size: 3 });
    game.particles.ring(this.x, this.y, { radius: 8, target: 70, color: '#c7a4ff', width: 4, life: 0.7 });
    game.audio.sfx('capture');
  }

  drawHealthBar(ctx) {
    if (this.dead || this.captured || this.def.boss) return;
    const w = 34 + this.radius;
    const x = this.x - w / 2;
    const y = this.y - this.radius - 34;
    ctx.save();
    ctx.fillStyle = 'rgba(10,8,16,0.7)';
    ctx.fillRect(x - 1, y - 1, w + 2, 6);
    ctx.fillStyle = this.elite ? '#ffcf6a' : '#ff7b7b';
    ctx.fillRect(x, y, w * this.hpRatio, 4);
    if (this.status.mark) {
      ctx.fillStyle = '#c7a4ff';
      ctx.beginPath(); ctx.arc(x - 6, y + 2, 3, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }
}

