import { BOSSES } from '../data/enemies.js';
import { Projectile, Zone } from './combat.js';
import { clamp, dist, angleDiff, TAU, randRange } from '../core/utils.js';

// Jefes con fases, telegraphs legibles y patrones propios de cada reino.
export class Boss {
  constructor(game, id, x, y) {
    const def = BOSSES[id];
    if (!def) throw new Error('Jefe desconocido: ' + id);
    this.game = game;
    this.id = id;
    this.def = def;
    this.typeId = id;
    this.name = def.name;
    this.title = def.title;
    this.sprite = def.sprite;
    this.x = x;
    this.y = y;
    this.spawnX = x;
    this.spawnY = y;
    this.level = def.level;
    this.radius = def.radius;
    this.scale = def.scale || 1;
    this.maxHp = Math.round(def.hp * game.difficulty.enemyHp);
    this.hp = this.maxHp;
    this.attack = Math.round(def.atk * game.difficulty.enemyDmg);
    this.defense = def.def;
    this.speed = def.speed;
    this.facing = Math.PI / 2;
    this.anim = 'idle';
    this.animTime = 0;
    this.flash = 0;
    this.status = {};
    this.dead = false;
    this.captured = false;
    this.deathTime = 0;
    this.boss = true;
    this.phase = 0;
    this.phaseCount = def.phases.length;
    this.state = 'intro';
    this.stateTimer = 1.15;
    this.cooldown = 1.4;
    this.pattern = null;
    this.patternIndex = 0;
    this.dashDir = 0;
    this.dashTimer = 0;
    this.hitPlayerThisDash = false;
    this.introTimer = 1.15;
    this.transitionTimer = 0;
    this.invuln = 0;
    this.aggro = true;
    this.enraged = false;
    this.arena = def.arena || null;
    this.summoned = 0;
  }

  get hpRatio() { return clamp(this.hp / this.maxHp, 0, 1); }
  get isBoss() { return true; }

  update(dt, game) {
    this.animTime += dt;
    this.flash = Math.max(0, this.flash - dt);
    if (this.dead) { this.deathTime += dt; return; }
    this.invuln = Math.max(0, this.invuln - dt);
    if (this.introTimer > 0) {
      this.introTimer -= dt;
      this.anim = 'intro';
      return;
    }
    for (const [k, v] of Object.entries(this.status)) {
      this.status[k] = v - dt;
      if (this.status[k] <= 0) delete this.status[k];
    }
    if (this.status.burn) this.hp -= 4 * dt;
    if (this.status.poison) this.hp -= 2.5 * dt;
    if (this.hp <= 0) { this.die(game); return; }
    if (this.status.freeze || this.status.stun) {
      this.anim = 'stagger';
      return;
    }
    if (this.transitionTimer > 0) {
      this.transitionTimer -= dt;
      this.anim = 'roar';
      if (Math.random() < 0.5) {
        game.particles.spawn('spark', this.x + randRange(Math.random, -70, 70), this.y - 40, {
          color: this.def.id === 'dama' ? '#ff9a5c' : this.def.id === 'veil' ? '#c7a4ff' : '#8fd18a',
          speed: 80, life: 0.7, size: 3, additive: true,
        });
      }
      return;
    }

    const ratio = this.hpRatio;
    let targetPhase = 0;
    for (let i = 1; i < this.def.phases.length; i++) {
      if (ratio <= this.def.phases[i]) targetPhase = i;
    }
    if (targetPhase > this.phase) {
      this.phase = targetPhase;
      this.transitionTimer = 1.25;
      this.invuln = 0.9;
      this.state = 'recover';
      this.stateTimer = 1.25;
      this.cooldown = 1.2;
      game.camera.addShake(16);
      game.audio.sfx('boss');
      game.particles.ring(this.x, this.y, { radius: 24, target: 180, color: this.phaseColor(), width: 8, life: 0.9 });
      game.particles.burst(this.x, this.y - 30, 46, { color: this.phaseColor(), speed: 200, life: 1.1, size: 3.4 });
      game.ui.toast(`${this.name} · Fase ${this.phase + 1}`, this.phaseLine(), 'boss');
      return;
    }

    const p = game.player;
    const d = dist(this.x, this.y, p.x, p.y);
    const slow = this.status.slow ? 0.62 : 1;
    this.cooldown = Math.max(0, this.cooldown - dt);
    this.stateTimer -= dt;

    if (this.state === 'windup') {
      this.facing = Math.atan2(p.y - this.y, p.x - this.x);
      this.anim = 'windup';
      if (this.stateTimer <= 0) this.executePattern(game);
      return;
    }
    if (this.state === 'dash') {
      this.updateDash(dt, game);
      return;
    }
    if (this.state === 'recover') {
      this.anim = 'recover';
      if (this.stateTimer <= 0) this.state = 'chase';
      return;
    }

    // Persecución base.
    this.state = 'chase';
    this.facing = Math.atan2(p.y - this.y, p.x - this.x);
    const desired = this.def.range * 0.72;
    if (d > desired) this.moveToward(p.x, p.y, this.speed * slow, dt, game);
    else if (d < desired * 0.45) this.moveToward(this.x - (p.x - this.x), this.y - (p.y - this.y), this.speed * slow * 0.65, dt, game);
    if (this.cooldown <= 0 && d < this.def.aggro * 1.2) this.choosePattern(game, d);
  }

  phaseColor() {
    if (this.id === 'dama') return '#ff9a5c';
    if (this.id === 'veil') return '#c7a4ff';
    return '#8fd18a';
  }
  phaseLine() {
    if (this.id === 'guardian') return this.phase === 1 ? 'El bosque recuerda su furia.' : 'Las raíces se abren.';
    if (this.id === 'dama') return this.phase === 1 ? 'El primer fuego no pide permiso.' : 'La brasa despierta.';
    return ['El Velo te mira.', 'Los reflejos se multiplican.', 'No queda nada que recordar.'][Math.min(2, this.phase)];
  }

  choosePattern(game, d) {
    const pool = this.def.patterns;
    const usable = pool.filter((name, i) => {
      if (this.phase === 0 && (name === 'clones' || name === 'mirrors' || name === 'collapse')) return false;
      return i !== this.patternIndex || pool.length <= 2;
    });
    const pattern = usable[Math.floor(Math.random() * usable.length)] || pool[0];
    this.pattern = pattern;
    this.patternIndex = pool.indexOf(pattern);
    this.state = 'windup';
    this.anim = 'windup';
    const windup = this.windupFor(pattern);
    this.stateTimer = windup;
    this.state = 'windup';
    if (pattern === 'beam' || pattern === 'projectiles' || pattern === 'wave') {
      game.particles.ring(this.x, this.y - 10, { radius: 30, target: 70, color: this.phaseColor(), width: 3, life: windup * 0.9 });
    }
  }

  windupFor(pattern) {
    if (pattern === 'beam' || pattern === 'collapse') return 1.0;
    if (pattern === 'meteors' || pattern === 'wave' || pattern === 'roots') return 0.8;
    if (pattern === 'dash') return 0.55;
    return 0.62;
  }

  executePattern(game) {
    const p = game.player;
    const a = Math.atan2(p.y - this.y, p.x - this.x);
    const color = this.phaseColor();
    switch (this.pattern) {
      case 'roots': {
        for (let i = 0; i < 3; i++) {
          const ang = i === 0 ? 0 : Math.random() * TAU;
          const rad = i === 0 ? 0 : randRange(Math.random, 40, 120);
          game.spawnZone({
            x: p.x + Math.cos(ang) * rad, y: p.y + Math.sin(ang) * rad, radius: 58,
            damage: this.attack * 0.8, life: 2.0, warnTime: 0.75, color: '#8fd18a', type: 'naturaleza',
            status: 'poison', owner: 'enemy',
          });
        }
        game.audio.sfx('spell');
        break;
      }
      case 'sweep': {
        this.facing = a;
        const hit = dist(this.x, this.y, p.x, p.y) < 145 + p.radius && Math.abs(angleDiff(a, Math.atan2(p.y - this.y, p.x - this.x))) < 0.9;
        if (hit) p.takeDamage(this.attack * 1.15, { source: 'enemy', element: 'naturaleza', game });
        game.particles.slash(this.x + Math.cos(a) * 42, this.y + Math.sin(a) * 42 - 16, a, { radius: 125, color, arc: 1.9, width: 16 });
        game.camera.addShake(10);
        game.audio.sfx('heavy');
        break;
      }
      case 'summon': {
        const types = this.id === 'guardian' ? ['musgo', 'wraith'] : this.id === 'dama' ? ['imp', 'salamander'] : ['sentinel', 'seraph'];
        for (let i = 0; i < 2; i++) {
          const ang = Math.random() * TAU;
          const px = this.x + Math.cos(ang) * 95;
          const py = this.y + Math.sin(ang) * 95;
          if (!game.world.circleBlocked(px, py, 14)) {
            game.spawnEnemy(types[i % types.length], px, py, { level: this.level, summoned: true });
            game.particles.burst(px, py - 12, 20, { color, speed: 120, life: 0.8, size: 2.5 });
          }
        }
        game.ui.toast(this.name, 'Invoca a sus servidores.', 'boss');
        break;
      }
      case 'poison': {
        for (let i = 0; i < 2; i++) {
          const ang = Math.random() * TAU;
          game.spawnZone({
            x: this.x + Math.cos(ang) * randRange(Math.random, 50, 130), y: this.y + Math.sin(ang) * randRange(Math.random, 50, 130),
            radius: 46, damage: this.attack * 0.55, life: 3.4, warnTime: 0.5, color: '#8fd18a', type: 'naturaleza', status: 'poison', owner: 'enemy',
          });
        }
        break;
      }
      case 'wave': {
        const count = 14;
        for (let i = 0; i < count; i++) {
          const ang = (i / count) * TAU + Math.random() * 0.08;
          game.spawnProjectile({
            x: this.x + Math.cos(ang) * 30, y: this.y + Math.sin(ang) * 30 - 16,
            vx: Math.cos(ang) * 180, vy: Math.sin(ang) * 180, radius: 8,
            damage: this.attack * 0.65, color: '#ff9a5c', owner: 'enemy', life: 2.4, element: 'fuego',
          });
        }
        game.audio.sfx('fire');
        break;
      }
      case 'meteors': {
        for (let i = 0; i < 4; i++) {
          const ang = Math.random() * TAU;
          const rad = randRange(Math.random, 10, 160);
          game.spawnZone({
            x: p.x + Math.cos(ang) * rad, y: p.y + Math.sin(ang) * rad, radius: 48,
            damage: this.attack * 0.8, life: 2.2, warnTime: 1.0, color: '#ff7b4d', type: 'fuego', owner: 'enemy',
          });
        }
        game.camera.addShake(8);
        game.audio.sfx('thunder');
        break;
      }
      case 'dash': {
        this.state = 'dash';
        this.dashDir = a;
        this.dashTimer = 0.52;
        this.hitPlayerThisDash = false;
        game.audio.sfx('heavy');
        break;
      }
      case 'clones': {
        for (let i = 0; i < 5; i++) {
          const ang = a + (i - 2) * 0.24;
          game.spawnProjectile({
            x: this.x + Math.cos(ang) * 24, y: this.y + Math.sin(ang) * 24 - 18,
            vx: Math.cos(ang) * 260, vy: Math.sin(ang) * 260, radius: 7,
            damage: this.attack * 0.55, color: '#ffd08a', owner: 'enemy', life: 1.9, element: 'fuego', homing: 0.3, target: game.player,
          });
        }
        game.particles.ring(this.x, this.y - 20, { radius: 16, target: 90, color, width: 5, life: 0.5 });
        break;
      }
      case 'projectiles': {
        for (let i = -3; i <= 3; i++) {
          const ang = a + i * 0.17;
          game.spawnProjectile({
            x: this.x + Math.cos(ang) * 34, y: this.y + Math.sin(ang) * 34 - 20,
            vx: Math.cos(ang) * 255, vy: Math.sin(ang) * 255, radius: 8,
            damage: this.attack * 0.62, color: '#c7a4ff', owner: 'enemy', life: 2.4, element: 'luz',
          });
        }
        game.audio.sfx('spell');
        break;
      }
      case 'collapse': {
        game.spawnZone({
          x: this.x, y: this.y, radius: 190, damage: this.attack * 0.85, life: 2.4,
          warnTime: 1.15, color: '#7d6a9e', type: 'sombra', owner: 'enemy',
        });
        game.particles.ring(this.x, this.y, { radius: 30, target: 200, color, width: 7, life: 1.2 });
        game.audio.sfx('boss');
        break;
      }
      case 'mirrors': {
        const count = 4;
        for (let i = 0; i < count; i++) {
          const ang = (i / count) * TAU + this.animTime;
          game.spawnProjectile({
            x: this.x + Math.cos(ang) * 70, y: this.y + Math.sin(ang) * 70 - 20,
            vx: 0, vy: 0, radius: 7, damage: this.attack * 0.5, color: '#c7a4ff',
            owner: 'enemy', life: 2.6, element: 'luz', homing: 0.5, target: game.player,
          });
        }
        break;
      }
      case 'beam': {
        this.facing = a;
        const hit = this.lineHits(p, a, 460, 24);
        game.particles.beam(this.x, this.y - 24, a, { radius: 460, color, width: 18, life: 0.35 });
        game.particles.beam(this.x, this.y - 24, a, { radius: 460, color: '#fff3c4', width: 6, life: 0.35 });
        if (hit) p.takeDamage(this.attack * 1.25, { source: 'enemy', element: 'luz', game });
        game.camera.addShake(12);
        game.audio.sfx('spell');
        break;
      }
      default: break;
    }
    this.state = 'recover';
    this.stateTimer = this.pattern === 'dash' ? 0.5 : 0.75;
    this.cooldown = this.phase === 0 ? 2.1 : this.phase === 1 ? 1.65 : 1.3;
    this.pattern = null;
  }

  lineHits(p, angle, length, width) {
    const dx = p.x - this.x, dy = p.y - this.y;
    const proj = dx * Math.cos(angle) + dy * Math.sin(angle);
    if (proj < 0 || proj > length) return false;
    const perp = Math.abs(-dx * Math.sin(angle) + dy * Math.cos(angle));
    return perp < width + p.radius;
  }

  updateDash(dt, game) {
    this.dashTimer -= dt;
    this.anim = 'dash';
    const speed = 520;
    const moved = game.world.moveCircle(this.x, this.y, Math.cos(this.dashDir) * speed * dt, Math.sin(this.dashDir) * speed * dt, this.radius);
    this.x = moved.x; this.y = moved.y;
    if (Math.random() < 0.8) {
      game.particles.spawn('smoke', this.x, this.y, {
        color: this.phaseColor(), size: 8, life: 0.45, speed: 20, additive: false,
      });
    }
    const p = game.player;
    if (!this.hitPlayerThisDash && dist(this.x, this.y, p.x, p.y) < this.radius + p.radius + 10) {
      this.hitPlayerThisDash = true;
      p.takeDamage(this.attack * 1.2, { source: 'enemy', game });
      game.camera.addShake(12);
    }
    if (this.dashTimer <= 0) {
      this.state = 'recover';
      this.stateTimer = 0.6;
      this.cooldown = 1.5;
      game.camera.addShake(7);
    }
  }

  moveToward(tx, ty, speed, dt, game) {
    const dx = tx - this.x, dy = ty - this.y;
    const d = Math.hypot(dx, dy);
    if (d < 1) return;
    const moved = game.world.moveCircle(this.x, this.y, (dx / d) * speed * dt, (dy / d) * speed * dt, this.radius);
    this.x = moved.x; this.y = moved.y;
    this.anim = 'walk';
  }

  takeDamage(amount, { source = 'player', crit = false, element = null, game = this.game } = {}) {
    if (this.dead || this.invuln > 0) return false;
    const mark = this.status.mark ? 1.2 : 1;
    const defense = this.defense / (this.defense + 110);
    const dmg = Math.max(1, Math.round(amount * (1 - defense) * mark));
    this.hp -= dmg;
    this.flash = 0.1;
    if (dmg > this.maxHp * 0.06) {
      this.stateTimer = Math.max(0, this.stateTimer - 0.04);
      game.particles.burst(this.x, this.y - this.radius, 6, { color: this.phaseColor(), speed: 90, life: 0.4, size: 2 });
    }
    if (this.hp <= 0) this.die(game);
    return true;
  }

  applyStatus(type, duration, game) {
    if (type === 'freeze' || type === 'stun') {
      this.status[type] = Math.max(this.status[type] || 0, duration * 0.35);
      return;
    }
    this.status[type] = Math.max(this.status[type] || 0, duration * 0.7);
  }

  stagger(duration, game) {
    if (this.invuln > 0) return;
    this.state = 'recover';
    this.stateTimer = Math.max(this.stateTimer, duration * 0.6);
  }

  die(game) {
    if (this.dead) return;
    this.dead = true;
    this.state = 'dead';
    this.deathTime = 0;
    this.hp = 0;
    game.particles.burst(this.x, this.y - 30, 90, { color: this.phaseColor(), speed: 230, life: 1.6, size: 4 });
    game.particles.ring(this.x, this.y, { radius: 20, target: 260, color: this.phaseColor(), width: 12, life: 1.2 });
    game.particles.ring(this.x, this.y, { radius: 20, target: 160, color: '#fff3c4', width: 5, life: 0.9 });
    game.camera.addShake(26);
    game.audio.sfx('death');
    game.onBossDefeated(this);
  }
}

import { CREATURES, creatureName } from '../data/creatures.js';
import { clamp, dist, angleDiff, TAU, randRange } from '../core/utils.js';

// Resonancias que te acompañan: siguen, atacan y desatan su habilidad activa.
export class Companion {
  constructor(game, id, { x = 0, y = 0, temp = false, life = 0 } = {}) {
    this.game = game;
    this.id = id;
    this.def = CREATURES[id];
    this.x = x;
    this.y = y;
    this.vx = 0; this.vy = 0;
    this.facing = Math.PI / 2;
    this.anim = 'idle';
    this.animTime = Math.random() * 5;
    this.attackCd = randRange(Math.random, 0.5, 1.2);
    this.abilityCd = 0;
    this.abilityMax = this.def?.active?.cooldown || 16;
    this.temp = temp;
    this.life = life;
    this.radius = 11;
    this.dead = false;
    this.spawnPulse = 0.6;
    this.offsetAngle = Math.random() * TAU;
  }

  get entry() { return this.game.collection.owned[this.id] || { bond: 1, level: 1 }; }
  get power() {
    const bond = this.entry.bond || 1;
    const level = this.entry.level || 1;
    return 1 + (bond - 1) * 0.14 + (level - 1) * 0.09 + (this.def.rarity || 0) * 0.08;
  }

  update(dt, game) {
    this.animTime += dt;
    this.spawnPulse = Math.max(0, this.spawnPulse - dt);
    this.attackCd = Math.max(0, this.attackCd - dt);
    this.abilityCd = Math.max(0, this.abilityCd - dt);
    if (this.temp) {
      this.life -= dt;
      if (this.life <= 0) {
        this.dead = true;
        game.particles.burst(this.x, this.y - 10, 22, { color: this.def.colors[0], speed: 100, life: 0.8, size: 2.5 });
        return;
      }
    }
    if (this.def?.sprite === 'slime') this.anim = 'idle';
    const target = game.nearestEnemy(this.x, this.y, this.temp ? 460 : 520, { capturable: false });
    const p = game.player;
    let tx, ty;
    if (target) {
      const d = dist(this.x, this.y, target.x, target.y);
      const desired = this.def?.sprite === 'orb' || this.def?.sprite === 'moth' ? 120 : 48;
      if (d > desired) {
        tx = target.x; ty = target.y;
      } else if (d < desired * 0.55) {
        tx = this.x - (target.x - this.x); ty = this.y - (target.y - this.y);
      } else {
        const a = Math.atan2(target.y - this.y, target.x - this.x) + Math.PI / 2;
        tx = this.x + Math.cos(a) * 40; ty = this.y + Math.sin(a) * 40;
      }
      this.facing = Math.atan2(target.y - this.y, target.x - this.x);
      if (d < desired + 44 && this.attackCd <= 0) this.attack(target, game);
    } else {
      this.offsetAngle += dt * 0.45;
      const orbit = this.temp ? 58 : 42;
      tx = p.x + Math.cos(this.offsetAngle) * orbit - 20;
      ty = p.y + Math.sin(this.offsetAngle) * orbit * 0.7 - 8;
      this.facing = Math.atan2(p.y - this.y, p.x - this.x);
    }
    const dx = tx - this.x, dy = ty - this.y;
    const d = Math.hypot(dx, dy);
    if (d > 6) {
      const speed = (this.temp ? 190 : 155) * this.power;
      const moved = game.world.moveCircle(this.x, this.y, (dx / d) * speed * dt, (dy / d) * speed * dt, this.radius);
      this.x = moved.x; this.y = moved.y;
      this.anim = d > 34 ? 'walk' : 'idle';
      if (Math.random() < 0.08) {
        game.particles.spawn('spark', this.x, this.y - 8, {
          color: this.def.colors[0], size: 1.6, life: 0.35, speed: 8, additive: true,
        });
      }
    } else {
      this.anim = 'idle';
    }
  }

  attack(target, game) {
    const a = Math.atan2(target.y - this.y, target.x - this.x);
    const dmg = Math.round((8 + this.entry.level * 2.4 + (this.def.rarity || 0) * 4) * this.power);
    this.attackCd = this.temp ? 0.85 : 1.25 / (game.player.hasSkill('res_symphony') ? 1.35 : 1);
    const ranged = ['moth', 'orb', 'imp', 'eye', 'angel', 'bird'].includes(this.def.sprite);
    if (ranged) {
      game.spawnProjectile({
        x: this.x + Math.cos(a) * 12, y: this.y + Math.sin(a) * 12 - 8,
        vx: Math.cos(a) * 300, vy: Math.sin(a) * 300, radius: 6,
        damage: dmg, color: this.def.colors[0], owner: 'player', life: 1.5,
        element: this.def.element, trailColor: this.def.colors[1],
      });
    } else {
      target.takeDamage(dmg, { source: 'player', element: this.def.element, game });
      game.particles.slash(target.x, target.y - 8, a, { radius: 26, color: this.def.colors[0], arc: 1.3, width: 4 });
      game.particles.number(target.x, target.y - target.radius - 12, `${dmg}`, this.def.colors[1], 13);
    }
    this.anim = 'attack';
  }

  useAbility(game) {
    if (this.abilityCd > 0 || this.temp) return false;
    this.abilityCd = this.abilityMax * (game.player.hasSkill('res_bond') ? 0.75 : 1);
    const p = game.player;
    const color = this.def.colors[0];
    game.audio.sfx('spell');
    game.particles.ring(this.x, this.y, { radius: 12, target: 80, color, width: 4, life: 0.55 });
    switch (this.id) {
      case 'musgo': {
        p.heal(Math.round(p.maxHp * 0.28));
        delete p.status.burn;
        p.status.regen = 4;
        game.particles.burst(p.x, p.y - 12, 30, { color: '#8fd18a', speed: 60, life: 1.1, size: 2.5 });
        break;
      }
      case 'wolf': {
        const t = game.nearestEnemy(this.x, this.y, 360);
        if (t) {
          const a = Math.atan2(t.y - this.y, t.x - this.x);
          this.x = t.x - Math.cos(a) * 26;
          this.y = t.y - Math.sin(a) * 26;
          const dmg = Math.round((18 + this.entry.level * 3) * this.power);
          t.takeDamage(dmg, { source: 'player', game });
          t.applyStatus('burn', 5, game);
          game.particles.burst(t.x, t.y - 10, 22, { color: '#a9c98a', speed: 140, life: 0.7, size: 2.6 });
          game.particles.number(t.x, t.y - 26, `${dmg}`, '#a9c98a', 18, true);
        }
        break;
      }
      case 'firefly': {
        for (const e of game.enemies) {
          if (!e.dead && dist(this.x, this.y, e.x, e.y) < 260) {
            e.applyStatus('stun', 3, game);
            game.particles.spawn('star', e.x, e.y - 16, { color: '#ffe7a8', size: 4, life: 0.8, speed: 20 });
          }
        }
        game.revealSecrets();
        game.particles.burst(this.x, this.y - 10, 40, { color: '#ffe7a8', speed: 160, life: 1.2, size: 2.8 });
        break;
      }
      case 'deer': {
        p.status.shield = 8;
        p.shieldAmount = Math.round(p.maxHp * 0.4);
        game.particles.ring(p.x, p.y, { radius: 10, target: 54, color: '#bfefff', width: 5, life: 0.8 });
        break;
      }
      case 'imp': {
        const t = game.nearestEnemy(this.x, this.y, 400);
        if (t) {
          const a = Math.atan2(t.y - this.y, t.x - this.x);
          game.spawnProjectile({
            x: this.x, y: this.y - 10, vx: Math.cos(a) * 340, vy: Math.sin(a) * 340, radius: 9,
            damage: Math.round(24 * this.power), color: '#ff9a5c', owner: 'player', life: 1.6, element: 'fuego',
            onHit: (e) => game.spawnZone({ x: e.x, y: e.y, radius: 46, damage: Math.round(12 * this.power), life: 0.9, warnTime: 0.1, color: '#ff7b4d', type: 'fuego', owner: 'player' }),
          });
        }
        break;
      }
      case 'salamander': {
        for (const e of game.enemies) {
          if (!e.dead && dist(this.x, this.y, e.x, e.y) < 180) {
            const dmg = Math.round(20 * this.power);
            e.takeDamage(dmg, { source: 'player', element: 'fuego', game });
            e.applyStatus('burn', 4, game);
            game.particles.number(e.x, e.y - 24, `${dmg}`, '#ff9a5c', 16);
          }
        }
        game.particles.ring(this.x, this.y, { radius: 20, target: 180, color: '#ff6a3d', width: 9, life: 0.7 });
        game.camera.addShake(7);
        break;
      }
      case 'golem': {
        for (const e of game.enemies) {
          if (!e.dead && dist(this.x, this.y, e.x, e.y) < 230) {
            e.applyStatus('stun', 2.2, game);
            e.takeDamage(Math.round(14 * this.power), { source: 'player', game });
          }
        }
        game.particles.ring(this.x, this.y, { radius: 20, target: 230, color: '#8a7aa8', width: 10, life: 0.8 });
        game.camera.addShake(12);
        game.audio.sfx('heavy');
        break;
      }
      case 'raven': {
        p.invuln = Math.max(p.invuln, 3);
        p.status.veil = 3;
        game.particles.burst(p.x, p.y - 12, 30, { color: '#a08ab8', speed: 80, life: 0.9, size: 2.6, additive: false });
        break;
      }
      case 'sentinel': {
        const t = game.nearestEnemy(this.x, this.y, 460);
        if (t) {
          const a = Math.atan2(t.y - this.y, t.x - this.x);
          game.particles.beam(this.x, this.y - 12, a, { radius: 460, color: '#ffe7a8', width: 12, life: 0.3 });
          for (const e of game.enemies) {
            if (e.dead) continue;
            const dx = e.x - this.x, dy = e.y - this.y;
            const proj = dx * Math.cos(a) + dy * Math.sin(a);
            const perp = Math.abs(-dx * Math.sin(a) + dy * Math.cos(a));
            if (proj > 0 && proj < 460 && perp < 26 + e.radius) {
              e.takeDamage(Math.round(30 * this.power), { source: 'player', element: 'luz', game });
            }
          }
        }
        break;
      }
      case 'seraph': {
        for (let i = -2; i <= 2; i++) {
          const t = game.nearestEnemy(this.x, this.y, 440);
          const base = t ? Math.atan2(t.y - this.y, t.x - this.x) : this.facing;
          const a = base + i * 0.22;
          game.spawnProjectile({
            x: this.x, y: this.y - 12, vx: Math.cos(a) * 300, vy: Math.sin(a) * 300, radius: 6,
            damage: Math.round(15 * this.power), color: '#c7a4ff', owner: 'player', life: 1.5, element: 'luz',
          });
        }
        break;
      }
      case 'abyss': {
        for (const e of game.enemies) {
          if (e.dead) continue;
          const d = dist(this.x, this.y, e.x, e.y);
          if (d < 240 && d > 1) {
            const pull = Math.min(70, 260 * (1 - d / 260));
            e.x += (this.x - e.x) / d * pull;
            e.y += (this.y - e.y) / d * pull;
            e.takeDamage(Math.round(12 * this.power), { source: 'player', element: 'sombra', game });
            e.applyStatus('slow', 3, game);
          }
        }
        p.heal(Math.round(p.maxHp * 0.08));
        game.particles.ring(this.x, this.y, { radius: 240, target: 10, color: '#7d6a9e', width: 6, life: 0.7 });
        break;
      }
      case 'aurel': {
        for (const e of game.enemies) {
          if (!e.dead && dist(this.x, this.y, e.x, e.y) < 420) e.applyStatus('slow', 5, game);
        }
        p.heal(Math.round(p.maxHp * 0.25));
        p.addUlt(20);
        game.particles.ring(this.x, this.y, { radius: 20, target: 420, color: '#fff3c4', width: 8, life: 1.2 });
        game.particles.burst(this.x, this.y - 12, 60, { color: '#ffd98a', speed: 170, life: 1.4, size: 3 });
        game.camera.addShake(6);
        break;
      }
      default: {
        p.heal(Math.round(p.maxHp * 0.15));
        break;
      }
    }
    if (game.player.hasSkill('res_heal')) p.heal(Math.round(p.maxHp * 0.1));
    game.ui.toast(this.def.active.name, this.def.active.desc, 'creature');
    return true;
  }

  drawHealthRing(ctx) {
    if (this.temp) return;
    const pct = 1 - clamp(this.abilityCd / this.abilityMax, 0, 1);
    ctx.save();
    ctx.globalAlpha = 0.8;
    ctx.strokeStyle = 'rgba(10,8,16,0.7)';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(this.x, this.y + 1, 18, 0, TAU); ctx.stroke();
    ctx.strokeStyle = pct >= 1 ? this.def.colors[0] : 'rgba(255,231,168,0.5)';
    ctx.beginPath(); ctx.arc(this.x, this.y + 1, 18, -Math.PI / 2, -Math.PI / 2 + TAU * pct); ctx.stroke();
    ctx.restore();
  }
}

export function summonCompanions(game) {
  const ids = Object.keys(game.collection.owned);
  if (!ids.length) return 0;
  for (const id of ids) {
    const existing = game.companions.find(c => c.id === id && c.temp);
    if (existing) { existing.life = 8; continue; }
    const a = Math.random() * TAU;
    game.companions.push(new Companion(game, id, {
      x: game.player.x + Math.cos(a) * 42,
      y: game.player.y + Math.sin(a) * 42,
      temp: true,
      life: 8,
    }));
  }
  return ids.length;
}

