        const fx = x + 6 + hash2(tx * 9 + i, ty * 3, seed) * 20;
        const fy = y + 6 + hash2(tx * 3, ty * 9 + i, seed + 7) * 20;
        ctx.fillStyle = i % 2 ? cols[2] : (regionId === 'drakmor' ? '#ff7b4d' : '#f0e6b0');
        for (let k = 0; k < 5; k++) {
          const a = (k / 5) * TAU;
          ctx.beginPath(); ctx.arc(fx + Math.cos(a) * 2.2, fy + Math.sin(a) * 2.2, 1.4, 0, TAU); ctx.fill();
        }
        ctx.fillStyle = '#ffd98a';
        ctx.beginPath(); ctx.arc(fx, fy, 1.1, 0, TAU); ctx.fill();
      }
      break;
    case 8: // ceniza
      ctx.fillStyle = cols[0];
      ctx.fillRect(x, y, 32, 32);
      ctx.strokeStyle = 'rgba(255,120,60,0.25)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 2; i++) {
        ctx.beginPath();
        ctx.moveTo(x + 4 + h * 20, y + 6 + i * 12);
        ctx.lineTo(x + 12 + h2 * 16, y + 10 + i * 12);
        ctx.lineTo(x + 20 + h * 8, y + 8 + i * 12);
        ctx.stroke();
      }
      if (h > 0.86) {
        ctx.fillStyle = 'rgba(255,150,80,0.5)';
        ctx.beginPath(); ctx.arc(x + 10 + h2 * 12, y + 10 + h * 12, 1.4, 0, TAU); ctx.fill();
      }
      break;
    case 10: // vacío
      {
        const g = ctx.createRadialGradient(x + 16, y + 16, 2, x + 16, y + 16, 26);
        g.addColorStop(0, cols[2]);
        g.addColorStop(1, cols[1]);
        ctx.fillStyle = g;
        ctx.fillRect(x, y, 32, 32);
        for (let i = 0; i < 3; i++) {
          const sx = x + 4 + hash2(tx * 11 + i, ty * 7, seed) * 24;
          const sy = y + 4 + hash2(tx * 5, ty * 13 + i, seed + 3) * 24;
          ctx.fillStyle = `rgba(255,255,255,${0.2 + hash2(i, tx + ty, seed) * 0.5})`;
          ctx.beginPath(); ctx.arc(sx, sy, 0.7 + h * 1.1, 0, TAU); ctx.fill();
        }
      }
      break;
    case 14: // barro
      ctx.fillStyle = cols[0];
      ctx.fillRect(x, y, 32, 32);
      ctx.fillStyle = cols[1];
      ctx.globalAlpha = 0.5;
      ctx.beginPath(); ctx.ellipse(x + 12 + h * 10, y + 14 + h2 * 8, 7, 3, h * 3, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
      break;
    case 15: // cristal
      ctx.fillStyle = cols[1];
      ctx.fillRect(x, y, 32, 32);
      crystalShape(ctx, x + 9 + h * 6, y + 26, 14 + h2 * 8, 3, cols[2]);
      crystalShape(ctx, x + 23, y + 24, 9 + h * 7, 2, cols[0]);
      break;
    default: break;
  }

  // Borde suave para evitar un mosaico demasiado duro.
  if ((tile === 0 || tile === 8 || tile === 9 || tile === 14) && h2 > 0.72) {
    ctx.fillStyle = rgba(cols[2], 0.1);
    ctx.beginPath(); ctx.arc(x + 16, y + 16, 15, 0, TAU); ctx.fill();
  }
}

import { TAU, hash2, rgba } from '../../core/utils.js';
import { shadow, glowCircle, line, star, roundRect, flame, crystalShape } from './common.js';

export function drawProp(ctx, p, region, time) {
  const sway = Math.sin(time * 1.15 + (p.seed || 0) * 0.7) * 1.4;
  switch (p.type) {
    case 'tree': {
      shadow(ctx, p.x, p.y, 22 * p.scale, 8 * p.scale, 0.32);
      ctx.fillStyle = '#4a3524';
      ctx.beginPath();
      ctx.moveTo(p.x - 4 * p.scale, p.y);
      ctx.quadraticCurveTo(p.x - 3 * p.scale, p.y - 30 * p.scale, p.x - 6 * p.scale + sway, p.y - 54 * p.scale);
      ctx.lineTo(p.x + 6 * p.scale + sway, p.y - 54 * p.scale);
      ctx.quadraticCurveTo(p.x + 3 * p.scale, p.y - 30 * p.scale, p.x + 4 * p.scale, p.y);
      ctx.fill();
      const base = region === 'drakmor' ? ['#2a2020', '#5a3a2a', '#1a1212'] : region === 'kansordore' ? ['#4a4a6a', '#8a8ab8', '#2a2a4a'] : ['#2f5a37', '#5c8f4f', '#1e3c28'];
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU + (p.seed || 0);
        const cx = p.x + Math.cos(a) * 13 * p.scale + sway;
        const cy = p.y - 56 * p.scale + Math.sin(a) * 9 * p.scale;
        const r = (16 + (i % 2) * 5) * p.scale;
        const g = ctx.createRadialGradient(cx - r * 0.3, cy - r * 0.3, 1, cx, cy, r);
        g.addColorStop(0, base[1]);
        g.addColorStop(1, base[0]);
        ctx.fillStyle = g;
        ctx.beginPath(); ctx.arc(cx, cy, r, 0, TAU); ctx.fill();
      }
      ctx.fillStyle = base[2];
      ctx.globalAlpha = 0.5;
      ctx.beginPath(); ctx.arc(p.x - 6 * p.scale + sway, p.y - 46 * p.scale, 13 * p.scale, 0, TAU); ctx.fill();
      ctx.globalAlpha = 1;
      break;
    }
    case 'pine': {
      shadow(ctx, p.x, p.y, 18 * p.scale, 6 * p.scale, 0.3);
      ctx.fillStyle = '#4a3524';
      ctx.fillRect(p.x - 3 * p.scale, p.y - 20 * p.scale, 6 * p.scale, 20 * p.scale);
      for (let i = 0; i < 3; i++) {
        const yy = p.y - 18 * p.scale - i * 15 * p.scale;
        const ww = (20 - i * 4) * p.scale;
        ctx.fillStyle = i % 2 ? '#2f5a37' : '#3f6f45';
        ctx.beginPath();
        ctx.moveTo(p.x + sway * (i + 1) * 0.4, yy - 20 * p.scale);
        ctx.lineTo(p.x + ww, yy + 4 * p.scale);
        ctx.lineTo(p.x - ww, yy + 4 * p.scale);
        ctx.closePath(); ctx.fill();
      }
      break;
    }
    case 'deadtree': {
      shadow(ctx, p.x, p.y, 20 * p.scale, 6 * p.scale, 0.3);
      ctx.strokeStyle = '#2a1c18';
      ctx.lineWidth = 5 * p.scale;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.quadraticCurveTo(p.x - 4 * p.scale, p.y - 30 * p.scale, p.x + 3 * p.scale + sway, p.y - 58 * p.scale);
      ctx.stroke();
      for (let i = 0; i < 4; i++) {
        const yy = p.y - 22 * p.scale - i * 9 * p.scale;
        const dir = i % 2 ? 1 : -1;
        ctx.beginPath();
        ctx.moveTo(p.x + dir * 2 * p.scale, yy);
        ctx.quadraticCurveTo(p.x + dir * 18 * p.scale, yy - 8 * p.scale, p.x + dir * 26 * p.scale, yy - 20 * p.scale);
        ctx.stroke();
      }
      break;
    }
    case 'obsidian': {
      shadow(ctx, p.x, p.y, 18 * p.scale, 6 * p.scale, 0.35);
      for (let i = 0; i < 3; i++) {
        const hh = (34 + i * 10) * p.scale;
        crystalShape(ctx, p.x + (i - 1) * 8 * p.scale, p.y, hh, 5 * p.scale, '#5a4a6a');
      }
      glowCircle(ctx, p.x, p.y - 22 * p.scale, 28 * p.scale, '#ff7b4d', 0.12);
      break;
    }
    case 'bush':
      shadow(ctx, p.x, p.y, 13 * p.scale, 5 * p.scale, 0.25);
      for (let i = 0; i < 3; i++) {
        ctx.fillStyle = i % 2 ? '#4d7740' : '#5f8f4e';
        ctx.beginPath(); ctx.arc(p.x + (i - 1) * 7 * p.scale, p.y - 8 * p.scale, 9 * p.scale, 0, TAU); ctx.fill();
      }
      break;
    case 'flower':
      ctx.strokeStyle = '#3f6636';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y - 10 * p.scale); ctx.stroke();
      star(ctx, p.x, p.y - 12 * p.scale, 4 * p.scale, region === 'drakmor' ? '#ff9a5c' : '#f0e6b0', 5, time);
      break;
    case 'emberflower':
      glowCircle(ctx, p.x, p.y - 8, 16, '#ff7b4d', 0.3);
      ctx.strokeStyle = '#6a3020'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y - 12 * p.scale); ctx.stroke();
      flame(ctx, p.x, p.y - 6 * p.scale, 0.35 * p.scale, time, '#ff7b4d');
      break;
    case 'smallrock':
    case 'lavaRock':
    case 'moteStone': {
      shadow(ctx, p.x, p.y, 10 * p.scale, 4 * p.scale, 0.25);
      const col = p.type === 'lavaRock' ? '#4a3a3a' : p.type === 'moteStone' ? '#8a8aa8' : '#7a7a6a';
      ctx.fillStyle = col;
      ctx.beginPath();
      ctx.moveTo(p.x - 11 * p.scale, p.y);
      ctx.lineTo(p.x - 8 * p.scale, p.y - 12 * p.scale);
      ctx.lineTo(p.x + 2 * p.scale, p.y - 16 * p.scale);
      ctx.lineTo(p.x + 11 * p.scale, p.y - 6 * p.scale);
      ctx.lineTo(p.x + 9 * p.scale, p.y);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,0.16)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(p.x - 7 * p.scale, p.y - 10 * p.scale); ctx.lineTo(p.x + 1 * p.scale, p.y - 14 * p.scale); ctx.stroke();
      if (p.type === 'lavaRock') {
        glowCircle(ctx, p.x, p.y - 6, 16, '#ff7b4d', 0.18);
        ctx.strokeStyle = 'rgba(255,140,70,0.7)';
        ctx.beginPath(); ctx.moveTo(p.x - 4, p.y - 2); ctx.lineTo(p.x, p.y - 9); ctx.lineTo(p.x + 5, p.y - 5); ctx.stroke();
      }
      if (p.type === 'moteStone') {
        glowCircle(ctx, p.x, p.y - 10, 22, '#ffe7a8', 0.14);
      }
      break;
    }
    case 'bone':
      shadow(ctx, p.x, p.y, 9, 3, 0.2);
      ctx.strokeStyle = '#c8bca8'; ctx.lineWidth = 2; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(p.x - 7, p.y - 3); ctx.lineTo(p.x + 6, p.y - 8); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(p.x + 5, p.y - 2); ctx.lineTo(p.x - 2, p.y - 9); ctx.stroke();
      break;
    case 'bonePile':
      shadow(ctx, p.x, p.y, 18, 5, 0.25);
      for (let i = 0; i < 5; i++) {
        const a = hash2(i, p.seed, 5) * TAU;
        line(ctx, p.x + Math.cos(a) * 4, p.y + Math.sin(a) * 3, p.x + Math.cos(a) * 17, p.y + Math.sin(a) * 10 - 4, '#b8ac98', 2.2);
      }
      break;
    case 'crystalSpire': {
      shadow(ctx, p.x, p.y, 13 * p.scale, 5 * p.scale, 0.3);
      crystalShape(ctx, p.x, p.y, 44 * p.scale, 9 * p.scale, '#9fc9e8');
      crystalShape(ctx, p.x - 9 * p.scale, p.y, 26 * p.scale, 5 * p.scale, '#c7a4ff');
      glowCircle(ctx, p.x, p.y - 26 * p.scale, 38 * p.scale, '#9fe8ff', 0.16);
      break;
    }
    case 'column': {
      shadow(ctx, p.x, p.y, 13 * p.scale, 5 * p.scale, 0.3);
      const h = 70 * p.scale;
      ctx.fillStyle = '#c8c0d8';
      ctx.fillRect(p.x - 7 * p.scale, p.y - h, 14 * p.scale, h);
      ctx.fillStyle = '#a89ac0';
      ctx.fillRect(p.x - 7 * p.scale, p.y - h, 4 * p.scale, h);
      ctx.fillStyle = '#d8d0e8';
      ctx.fillRect(p.x - 12 * p.scale, p.y - h - 7 * p.scale, 24 * p.scale, 8 * p.scale);
      ctx.fillRect(p.x - 11 * p.scale, p.y - 5 * p.scale, 22 * p.scale, 6 * p.scale);
      ctx.strokeStyle = 'rgba(255,231,168,0.35)';
      ctx.lineWidth = 1;
      for (let i = 1; i < 4; i++) {
        ctx.beginPath(); ctx.moveTo(p.x - 5 * p.scale, p.y - h + i * 14 * p.scale); ctx.lineTo(p.x + 5 * p.scale, p.y - h + i * 14 * p.scale); ctx.stroke();
      }
      break;
    }
    case 'floatingRock': {
      const bob = Math.sin(time * 1.3 + p.seed) * 5;
      shadow(ctx, p.x, p.y + 14, 12, 4, 0.2);
      ctx.fillStyle = '#7a7a98';
      ctx.beginPath();
      ctx.moveTo(p.x - 13 * p.scale, p.y - 8 + bob);
      ctx.lineTo(p.x - 7 * p.scale, p.y - 22 + bob);
      ctx.lineTo(p.x + 8 * p.scale, p.y - 18 + bob);
      ctx.lineTo(p.x + 13 * p.scale, p.y - 3 + bob);
      ctx.lineTo(p.x + 2 * p.scale, p.y + 2 + bob);
      ctx.closePath(); ctx.fill();
      glowCircle(ctx, p.x, p.y - 10 + bob, 24, '#c7a4ff', 0.16);
      break;
    }
    case 'floatingObelisk': {
      const bob = Math.sin(time * 1.1 + p.seed) * 6;
      glowCircle(ctx, p.x, p.y - 40 + bob, 50, '#c7a4ff', 0.16);
      ctx.fillStyle = '#2a2440';
      ctx.beginPath();
      ctx.moveTo(p.x, p.y - 90 * p.scale + bob);
      ctx.lineTo(p.x + 12 * p.scale, p.y - 24 * p.scale + bob);
      ctx.lineTo(p.x + 6 * p.scale, p.y + bob);
      ctx.lineTo(p.x - 6 * p.scale, p.y + bob);
      ctx.lineTo(p.x - 12 * p.scale, p.y - 24 * p.scale + bob);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(199,164,255,0.7)';
      ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.moveTo(p.x, p.y - 78 * p.scale + bob); ctx.lineTo(p.x, p.y - 30 * p.scale + bob); ctx.stroke();
      star(ctx, p.x, p.y - 54 * p.scale + bob, 5, '#ffe7a8', 4, time * 0.4);
      break;
    }
    case 'pillar': {
      shadow(ctx, p.x, p.y, 16, 6, 0.3);
      ctx.fillStyle = '#8a8272';
      ctx.fillRect(p.x - 9, p.y - 62, 18, 62);
      ctx.fillStyle = '#a39a86';
      ctx.fillRect(p.x - 9, p.y - 62, 5, 62);
      ctx.fillStyle = '#6f685a';
      ctx.fillRect(p.x - 13, p.y - 5, 26, 7);
      break;
    }
    case 'fence': {
      shadow(ctx, p.x, p.y, 15, 4, 0.2);
      ctx.fillStyle = '#6a4a30';
      ctx.fillRect(p.x - 2, p.y - 22 * p.scale, 4, 22 * p.scale);
      ctx.fillRect(p.x - 14, p.y - 15 * p.scale, 28, 3);
      ctx.fillRect(p.x - 14, p.y - 7 * p.scale, 28, 3);
      break;
    }
    case 'well': {
      shadow(ctx, p.x, p.y, 22, 8, 0.3);
      ctx.fillStyle = '#8a8272';
      ctx.beginPath(); ctx.ellipse(p.x, p.y - 8, 20, 11, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#2a2a3a';
      ctx.beginPath(); ctx.ellipse(p.x, p.y - 10, 14, 7, 0, 0, TAU); ctx.fill();
      ctx.strokeStyle = '#6a4a30'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(p.x - 15, p.y - 14); ctx.lineTo(p.x - 15, p.y - 46); ctx.lineTo(p.x + 15, p.y - 46); ctx.lineTo(p.x + 15, p.y - 14); ctx.stroke();
      ctx.fillStyle = '#5a3a22';
      ctx.beginPath(); ctx.moveTo(p.x - 20, p.y - 46); ctx.lineTo(p.x, p.y - 58); ctx.lineTo(p.x + 20, p.y - 46); ctx.closePath(); ctx.fill();
      break;
    }
    case 'banner': {
      ctx.strokeStyle = '#4a3524'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.x, p.y - 58 * p.scale); ctx.stroke();
      const wave = Math.sin(time * 2 + p.seed) * 3;
      ctx.fillStyle = region === 'drakmor' ? '#8a2a1a' : region === 'kansordore' ? '#5a4a8a' : '#7a3a4a';
      ctx.beginPath();
      ctx.moveTo(p.x + 1, p.y - 55 * p.scale);
      ctx.quadraticCurveTo(p.x + 18 + wave, p.y - 48 * p.scale, p.x + 14 + wave, p.y - 34 * p.scale);
      ctx.lineTo(p.x + 1, p.y - 30 * p.scale);
      ctx.closePath(); ctx.fill();
      star(ctx, p.x + 6, p.y - 43 * p.scale, 4, '#ffe7a8', 4, 0);
      break;
    }
    case 'statue': {
      shadow(ctx, p.x, p.y, 15, 5, 0.3);
      ctx.fillStyle = '#8a8aa8';
      ctx.fillRect(p.x - 11, p.y - 12, 22, 12);
      ctx.fillStyle = '#b8b0c8';
      ctx.beginPath();
      ctx.moveTo(p.x - 8, p.y - 12);
      ctx.quadraticCurveTo(p.x - 10, p.y - 40, p.x - 4, p.y - 52);
      ctx.lineTo(p.x + 4, p.y - 52);
      ctx.quadraticCurveTo(p.x + 10, p.y - 40, p.x + 8, p.y - 12);
      ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.arc(p.x, p.y - 56, 6, 0, TAU); ctx.fill();
      glowCircle(ctx, p.x, p.y - 56, 22, '#ffe7a8', 0.1);
      break;
    }
    case 'runeStone': {
      shadow(ctx, p.x, p.y, 12, 4, 0.3);
      ctx.fillStyle = '#6a645a';
      ctx.beginPath();
      ctx.moveTo(p.x - 10, p.y);
      ctx.lineTo(p.x - 7, p.y - 38);
      ctx.lineTo(p.x + 3, p.y - 46);
      ctx.lineTo(p.x + 9, p.y - 30);
      ctx.lineTo(p.x + 8, p.y);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(143,209,138,0.6)';
      ctx.lineWidth = 1.3;
      ctx.beginPath(); ctx.arc(p.x, p.y - 25, 5, 0, TAU); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(p.x, p.y - 32); ctx.lineTo(p.x, p.y - 18); ctx.stroke();
      glowCircle(ctx, p.x, p.y - 25, 18, '#8fd18a', 0.15);
      break;
    }
    case 'ruinPillar': {
      shadow(ctx, p.x, p.y, 13, 5, 0.3);
      ctx.fillStyle = '#9a907c';
      ctx.fillRect(p.x - 8, p.y - 44, 16, 44);
      ctx.fillStyle = '#b8ac98';
      ctx.fillRect(p.x - 8, p.y - 44, 5, 44);
      ctx.fillStyle = '#6a645a';
      ctx.beginPath();
      ctx.moveTo(p.x - 8, p.y - 44);
      ctx.lineTo(p.x - 2, p.y - 54);
      ctx.lineTo(p.x + 8, p.y - 46);
      ctx.lineTo(p.x + 8, p.y - 44);
      ctx.closePath(); ctx.fill();
      break;
    }
    case 'arch': {
      ctx.strokeStyle = '#8a8272';
      ctx.lineWidth = 14;
      ctx.beginPath();
      ctx.moveTo(p.x - 38, p.y);
      ctx.lineTo(p.x - 38, p.y - 50);
      ctx.quadraticCurveTo(p.x, p.y - 96, p.x + 38, p.y - 50);
      ctx.lineTo(p.x + 38, p.y);
      ctx.stroke();
      ctx.strokeStyle = '#b8ac98';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(p.x - 38, p.y - 6);
      ctx.lineTo(p.x - 38, p.y - 50);
      ctx.quadraticCurveTo(p.x, p.y - 92, p.x + 38, p.y - 50);
      ctx.lineTo(p.x + 38, p.y - 6);
      ctx.stroke();
      break;
    }
    case 'fortressWall': {
      shadow(ctx, p.x, p.y, 17, 6, 0.35);
      ctx.fillStyle = '#4a3a32';
      ctx.fillRect(p.x - 15, p.y - 58, 30, 58);
      ctx.fillStyle = '#5a4a42';
      for (let i = 0; i < 4; i++) for (let j = 0; j < 2; j++) {
        ctx.fillRect(p.x - 14 + j * 15, p.y - 56 + i * 14, 13, 11);
      }
      glowCircle(ctx, p.x, p.y - 30, 24, '#ff7b4d', 0.1);
      break;
    }
    case 'forgeBig': {
      shadow(ctx, p.x, p.y, 50, 16, 0.35);
      ctx.fillStyle = '#3a302a';
      ctx.fillRect(p.x - 48, p.y - 50, 96, 50);
      ctx.fillStyle = '#2a2220';
      ctx.fillRect(p.x - 40, p.y - 42, 32, 42);
      ctx.fillStyle = '#ff7b4d';
      ctx.fillRect(p.x - 34, p.y - 26, 20, 16);
      glowCircle(ctx, p.x - 24, p.y - 18, 46, '#ff7b4d', 0.25);
      ctx.fillStyle = '#5a4a42';
      ctx.fillRect(p.x + 8, p.y - 22, 28, 16);
      ctx.fillStyle = '#8a8272';
      ctx.fillRect(p.x + 14, p.y - 30, 16, 8);
      break;
    }
    case 'seal': {
      glowCircle(ctx, p.x, p.y - 30, 64, '#ffe7a8', 0.16);
      ctx.strokeStyle = 'rgba(255,231,168,0.55)';
      ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(p.x, p.y - 24, 34, 0, TAU); ctx.stroke();
      ctx.beginPath(); ctx.arc(p.x, p.y - 24, 24, 0, TAU); ctx.stroke();
      star(ctx, p.x, p.y - 24, 16, '#ffe7a8', 8, time * 0.2);
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU + time * 0.1;
        ctx.strokeStyle = 'rgba(255,231,168,0.35)';
        ctx.beginPath();
        ctx.moveTo(p.x + Math.cos(a) * 36, p.y - 24 + Math.sin(a) * 36);
        ctx.lineTo(p.x + Math.cos(a) * 48, p.y - 24 + Math.sin(a) * 48);
        ctx.stroke();
      }
      break;
    }
    case 'elderHouse': case 'forge': case 'shop': case 'healer': case 'house':
    case 'outpost': case 'tent': case 'temple': case 'library': case 'shrine':
      drawHouse(ctx, p, region, time);
      break;
    default: break;
  }
}

function drawHouse(ctx, p, region, time) {
  const w = p.w || 100, h = p.h || 70;
  const x = p.x, y = p.y;
  const type = p.type;
  shadow(ctx, x, y + h * 0.48, w * 0.52, h * 0.18, 0.32);
  const wall = type === 'temple' || type === 'library' || type === 'shrine' ? '#c8c0d8' : region === 'drakmor' ? '#5a4a42' : region === 'kansordore' ? '#b8b0c8' : '#a89272';
  const roof = type === 'forge' ? '#4a3a32' : region === 'drakmor' ? '#3a2a2a' : region === 'kansordore' ? '#5a4a8a' : '#7a3a3a';
  const bx = x - w / 2, by = y - h * 0.3;
  ctx.fillStyle = wall;
  ctx.fillRect(bx, by, w, h * 0.78);
  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  ctx.fillRect(bx, by + h * 0.5, w, h * 0.28);
  // Tejado.
  ctx.fillStyle = roof;
  ctx.beginPath();
  if (type === 'tent') {
    ctx.moveTo(x, y - h * 1.1);
    ctx.lineTo(x + w * 0.62, y + h * 0.42);
    ctx.lineTo(x - w * 0.62, y + h * 0.42);
  } else {
    ctx.moveTo(bx - w * 0.1, by);
    ctx.lineTo(x, y - h * 0.78);
    ctx.lineTo(bx + w * 1.1, by);
  }
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.16)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x, y - h * 0.76); ctx.lineTo(bx - w * 0.06, by); ctx.stroke();

  // Puerta y ventanas.
  ctx.fillStyle = '#3a2a20';
  ctx.fillRect(x - w * 0.09, y + h * 0.08, w * 0.18, h * 0.4);
  ctx.fillStyle = 'rgba(255,220,150,0.75)';
  if (type === 'forge') {
    ctx.fillRect(x - w * 0.3, y - h * 0.05, w * 0.16, h * 0.16);
    glowCircle(ctx, x - w * 0.22, y + h * 0.02, w * 0.26, '#ff7b4d', 0.3);
  } else {
    ctx.fillRect(x - w * 0.32, y - h * 0.05, w * 0.12, h * 0.14);
    ctx.fillRect(x + w * 0.2, y - h * 0.05, w * 0.12, h * 0.14);
  }
  if (type === 'healer') {
    ctx.fillStyle = '#8fd18a';
    ctx.fillRect(x + w * 0.3, y - h * 0.34, w * 0.08, h * 0.16);
    ctx.fillRect(x + w * 0.25, y - h * 0.29, w * 0.18, h * 0.06);
  }
  if (type === 'shop') {
    for (let i = 0; i < 5; i++) {
      ctx.fillStyle = i % 2 ? '#d9b46a' : '#7a3a4a';
      ctx.fillRect(bx + (i / 5) * w, by + h * 0.25, w / 5, h * 0.1);
    }
  }
  if (type === 'temple' || type === 'library') {
    ctx.fillStyle = '#e8e0f0';
    for (let i = 0; i < 4; i++) {
      ctx.fillRect(bx + 6 + i * (w - 12) / 3.2, by + h * 0.05, 7, h * 0.7);
    }
    glowCircle(ctx, x, y - h * 0.2, w * 0.4, '#ffe7a8', 0.12);
  }
  if (type === 'forge') {
    // Chimenea y humo.
    ctx.fillStyle = '#4a3a32';
    ctx.fillRect(x + w * 0.28, y - h * 0.9, w * 0.14, h * 0.5);
    for (let i = 0; i < 4; i++) {
      const t = (time * 0.2 + i * 0.25) % 1;
      ctx.fillStyle = `rgba(120,110,105,${0.28 * (1 - t)})`;
      ctx.beginPath();
      ctx.arc(x + w * 0.35 + Math.sin(t * 5 + i) * 8, y - h * 0.95 - t * 40, 4 + t * 8, 0, TAU);
      ctx.fill();
    }
  }
  if (type === 'elderHouse') {
    ctx.strokeStyle = '#d9b46a'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(x, y - h * 0.1, w * 0.1, 0, TAU); ctx.stroke();
    star(ctx, x, y - h * 0.1, w * 0.06, '#ffe7a8', 4, 0);
  }
}

export function drawInteractable(ctx, it, state, time) {
  const x = it.x, y = it.y;
  const active = state?.active;
  const opened = state?.opened;
  switch (it.type) {
    case 'chest': {
      shadow(ctx, x, y + 4, 15, 5, 0.3);
      const c = opened ? '#5a4a3a' : '#8a6a3a';
      ctx.fillStyle = c;
      roundRect(ctx, x - 14, y - 12, 28, 18, 3); ctx.fill();
      ctx.fillStyle = opened ? '#3a2a1a' : '#b98a4a';
      if (opened) {
        ctx.save(); ctx.translate(x, y - 12); ctx.rotate(-0.5);
        roundRect(ctx, -14, -8, 28, 9, 3); ctx.fill(); ctx.restore();
        glowCircle(ctx, x, y - 8, 28, '#ffe7a8', 0.15);
      } else {
        roundRect(ctx, x - 14, y - 18, 28, 8, 3); ctx.fill();
        ctx.fillStyle = '#ffe7a8';
        ctx.fillRect(x - 3, y - 11, 6, 7);
        glowCircle(ctx, x, y - 10, 26, '#ffcf6a', 0.16);
      }
      break;
    }
    case 'altar': {
      shadow(ctx, x, y + 6, 26, 8, 0.35);
      ctx.fillStyle = '#8a8272';
      ctx.fillRect(x - 24, y - 16, 48, 16);
      ctx.fillStyle = '#a89e88';
      ctx.fillRect(x - 20, y - 26, 40, 10);
      glowCircle(ctx, x, y - 42, 54, '#ffe7a8', 0.2);
      const bob = Math.sin(time * 1.5) * 3;
      ctx.save();
      ctx.translate(x, y - 58 + bob);
      ctx.rotate(-0.2);
      ctx.fillStyle = '#e8f4ff';
      ctx.fillRect(-2, -26, 4, 34);
      ctx.fillStyle = '#d9b46a';
      ctx.fillRect(-8, 6, 16, 3);
      ctx.restore();
      star(ctx, x, y - 86 + bob, 7, '#fff3c4', 4, time * 0.5);
      break;
    }
    case 'lore': {
      shadow(ctx, x, y + 4, 15, 5, 0.28);
      ctx.fillStyle = '#6a645a';
      ctx.beginPath();
      ctx.moveTo(x - 13, y);
      ctx.lineTo(x - 11, y - 34);
      ctx.lineTo(x + 9, y - 38);
      ctx.lineTo(x + 13, y);
      ctx.closePath(); ctx.fill();
      ctx.strokeStyle = 'rgba(255,231,168,0.5)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 3; i++) {
        ctx.beginPath(); ctx.moveTo(x - 6, y - 27 + i * 6); ctx.lineTo(x + 6, y - 29 + i * 6); ctx.stroke();
      }
      glowCircle(ctx, x, y - 24, 22, '#ffe7a8', 0.12);
      break;
    }
    case 'herb': {
      if (opened) break;
      glowCircle(ctx, x, y - 8, 20, '#d9e8ff', 0.2);
      ctx.strokeStyle = '#5f8f4e'; ctx.lineWidth = 1.5;
      for (let i = 0; i < 4; i++) {
        const a = -Math.PI / 2 + (i - 1.5) * 0.45;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x + Math.cos(a) * 7, y - 10, x + Math.cos(a) * 13, y - 18); ctx.stroke();
      }
      star(ctx, x, y - 18, 5, '#e8f4ff', 5, time);
      break;
    }
    case 'ore': {
      if (opened) break;
      shadow(ctx, x, y + 3, 12, 4, 0.25);
      ctx.fillStyle = '#6a645a';
      ctx.beginPath(); ctx.moveTo(x - 12, y); ctx.lineTo(x - 7, y - 14); ctx.lineTo(x + 5, y - 17); ctx.lineTo(x + 12, y - 4); ctx.lineTo(x + 6, y); ctx.closePath(); ctx.fill();
      if (it.item === 'living_ash') {
        glowCircle(ctx, x, y - 8, 22, '#ff7b4d', 0.2);
        ctx.fillStyle = '#ff9a5c';
        ctx.beginPath(); ctx.arc(x, y - 9, 3, 0, TAU); ctx.fill();
      } else {
        glowCircle(ctx, x, y - 8, 18, '#9fc9e8', 0.15);
        crystalShape(ctx, x, y - 2, 14, 3, '#9fc9e8');
      }
      break;
    }
    case 'brazier': {
      shadow(ctx, x, y + 3, 10, 4, 0.3);
      ctx.fillStyle = '#5a4a42';
      ctx.fillRect(x - 3, y - 14, 6, 14);
      ctx.fillStyle = '#8a8272';
      ctx.beginPath(); ctx.ellipse(x, y - 16, 11, 5, 0, 0, TAU); ctx.fill();
      if (active) {
        flame(ctx, x, y - 16, 1.1, time, '#ff9a5c');
        glowCircle(ctx, x, y - 20, 34, '#ff9a5c', 0.24);
      } else {
        ctx.fillStyle = '#3a2a24';
        ctx.beginPath(); ctx.ellipse(x, y - 16, 7, 3, 0, 0, TAU); ctx.fill();
      }
      break;
    }
    case 'lever': {
      shadow(ctx, x, y + 3, 10, 4, 0.3);
      ctx.fillStyle = '#5a4a42';
      ctx.fillRect(x - 5, y - 26, 10, 26);
      ctx.strokeStyle = active ? '#8fd18a' : '#8a8272';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(x, y - 22);
      ctx.lineTo(x + (active ? 12 : -12), y - (active ? 34 : 34));
      ctx.stroke();
      ctx.fillStyle = active ? '#8fd18a' : '#ff9a5c';
      ctx.beginPath(); ctx.arc(x + (active ? 12 : -12), y - 34, 4, 0, TAU); ctx.fill();
      glowCircle(ctx, x, y - 28, active ? 30 : 18, active ? '#8fd18a' : '#ff9a5c', active ? 0.22 : 0.1);
      break;
    }
    case 'crystal': {
      const bob = Math.sin(time * 1.6 + (it.order || 0)) * 3;
      glowCircle(ctx, x, y - 26 + bob, active ? 40 : 24, active ? '#ffe7a8' : '#c7a4ff', active ? 0.28 : 0.14);
      crystalShape(ctx, x, y - 2 + bob, 38, 8, active ? '#ffe7a8' : '#c7a4ff');
      star(ctx, x, y - 52 + bob, 4, '#fff3c4', 4, time);
      break;
    }
    case 'page': {
      if (opened) break;
      const bob = Math.sin(time * 2 + x) * 4;
      glowCircle(ctx, x, y - 20 + bob, 26, '#e8d9a8', 0.2);
      ctx.save();
      ctx.translate(x, y - 20 + bob);
      ctx.rotate(Math.sin(time + x) * 0.12);
      ctx.fillStyle = '#e8d9a8';
      ctx.fillRect(-7, -10, 14, 20);
      ctx.strokeStyle = 'rgba(90,70,40,0.6)'; ctx.lineWidth = 1;
      for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(-4, -6 + i * 4); ctx.lineTo(4, -6 + i * 4); ctx.stroke(); }
      ctx.restore();
      break;
    }
    case 'gate': {
      glowCircle(ctx, x, y - 34, 46, '#ffe7a8', 0.16);
      ctx.strokeStyle = '#b8ac98'; ctx.lineWidth = 9;
      ctx.beginPath();
      ctx.moveTo(x - 26, y);
      ctx.lineTo(x - 26, y - 46);
      ctx.quadraticCurveTo(x, y - 80, x + 26, y - 46);
      ctx.lineTo(x + 26, y);
      ctx.stroke();
      ctx.strokeStyle = 'rgba(255,231,168,0.55)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(x, y - 36, 15, 0, TAU); ctx.stroke();
      break;
    }
    case 'bossdoor': {
      glowCircle(ctx, x, y - 36, 60, active ? '#8fd18a' : '#ffcf6a', 0.12);
      ctx.strokeStyle = '#5a4a42'; ctx.lineWidth = 16;
      ctx.beginPath();
      ctx.moveTo(x - 36, y);
      ctx.lineTo(x - 36, y - 54);
      ctx.quadraticCurveTo(x, y - 104, x + 36, y - 54);
      ctx.lineTo(x + 36, y);
      ctx.stroke();
      ctx.strokeStyle = '#8a8272'; ctx.lineWidth = 3;
      ctx.stroke();
      break;
    }
    case 'forge': {
      shadow(ctx, x, y + 4, 18, 6, 0.3);
      ctx.fillStyle = '#4a3a32';
      ctx.fillRect(x - 18, y - 14, 36, 14);
      ctx.fillStyle = '#6a5a50';
      ctx.fillRect(x - 8, y - 26, 16, 12);
      ctx.fillStyle = '#8a8272';
      ctx.beginPath(); ctx.moveTo(x - 14, y - 26); ctx.lineTo(x + 14, y - 26); ctx.lineTo(x + 8, y - 34); ctx.lineTo(x - 8, y - 34); ctx.closePath(); ctx.fill();
      glowCircle(ctx, x, y - 10, 24, '#ff7b4d', 0.18);
      break;
    }
    case 'sign': {
      shadow(ctx, x, y + 3, 8, 3, 0.25);
      ctx.fillStyle = '#6a4a30';
      ctx.fillRect(x - 2, y - 24, 4, 24);
      ctx.fillStyle = '#8a6248';
      ctx.fillRect(x - 14, y - 32, 28, 12);
      ctx.strokeStyle = 'rgba(40,26,16,0.6)'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(x - 10, y - 28); ctx.lineTo(x + 8, y - 28); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x - 10, y - 24); ctx.lineTo(x + 4, y - 24); ctx.stroke();
      break;
    }
    case 'survivor': break;
    default: break;
  }
}

import { TAU, clamp, rgba } from '../../core/utils.js';
import { ITEMS } from '../../data/items.js';
import { PORTRAITS } from '../../data/story.js';
import { shadow, glowCircle, line, roundRect, humanHair, eye } from './common.js';

function drawWeapon(ctx, type, color, side, swing, heavy) {
  ctx.save();
  ctx.rotate(swing);
  if (type === 'greatsword') {
    ctx.fillStyle = '#3a2a20';
    ctx.fillRect(-2.5, -3, 5, 12);
    ctx.fillStyle = '#c8b080';
    ctx.fillRect(-9, -5, 18, 3);
    const g = ctx.createLinearGradient(0, -8, 0, -52);
    g.addColorStop(0, '#f4f0e8');
    g.addColorStop(0.55, color);
    g.addColorStop(1, '#8a9ab0');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-5, -6);
    ctx.lineTo(-4, -48);
    ctx.lineTo(0, -56);
    ctx.lineTo(4, -48);
    ctx.lineTo(5, -6);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(0, -48); ctx.stroke();
  } else if (type === 'spear') {
    ctx.strokeStyle = '#8a6a48'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(0, 4); ctx.lineTo(0, -58); ctx.stroke();
    ctx.fillStyle = '#e8f4ff';
    ctx.beginPath(); ctx.moveTo(0, -74); ctx.lineTo(5, -56); ctx.lineTo(0, -50); ctx.lineTo(-5, -56); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = color; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, -70); ctx.lineTo(0, -54); ctx.stroke();
  } else if (type === 'staff') {
    ctx.strokeStyle = '#5a4030'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(0, 8); ctx.lineTo(0, -46); ctx.stroke();
    glowCircle(ctx, 0, -52, 18, color, 0.45);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -52, 5, 0, TAU); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.7)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, -52, 8, 0, TAU); ctx.stroke();
  } else {
    ctx.fillStyle = '#3a2a20';
    ctx.fillRect(-2, -2, 4, 10);
    ctx.fillStyle = '#c8b080';
    ctx.fillRect(-7, -4, 14, 3);
    const g = ctx.createLinearGradient(0, -6, 0, -38);
    g.addColorStop(0, '#ffffff');
    g.addColorStop(0.6, color);
    g.addColorStop(1, '#8a9ab0');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-3, -4);
    ctx.lineTo(-2.5, -34);
    ctx.lineTo(0, -42);
    ctx.lineTo(2.5, -34);
    ctx.lineTo(3, -4);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, -8); ctx.lineTo(0, -34); ctx.stroke();
  }
  ctx.restore();
}

export function drawHumanoid(ctx, x, y, opts = {}) {
  const {
    appearance = {}, anim = 'idle', animTime = 0, facing = Math.PI / 2, scale = 1,
    weapon = null, weaponType = 'sword', weaponColor = '#d8d2c4', armorColor = null,
    helmetColor = null, accessoryColor = null, capeColor = null, palette = null,
    npc = false, dead = false, flash = 0, blocking = false, showCape = true,
  } = opts;
  const t = animTime;
  const a = appearance;
  const skin = palette?.skin || a.skin || '#e8c9a8';
  const hairColor = palette?.hair || a.hairColor || '#3a2a1a';
  const outfit = palette?.cloth || a.outfit || '#4a6a4a';
  const armor = armorColor || a.armorColor || outfit;
  const cape = capeColor || a.capeColor || '#7a3a4a';
  const eyeColor = a.eyeColor || '#4a7a8a';
  const moving = anim === 'walk' || anim === 'run';
  const run = anim === 'run';
  const swing = moving ? Math.sin(t * (run ? 14 : 9)) : 0;
  const bob = moving ? Math.abs(Math.sin(t * (run ? 14 : 9))) * (run ? 2.6 : 1.4) : Math.sin(t * 2.2) * 0.7;
  const side = Math.cos(facing) < -0.15 ? -1 : 1;
  const fy = Math.sin(facing);
  const attack = anim.startsWith('attack') || anim === 'heavy';
  const attackT = attack ? clamp(t / (anim === 'heavy' ? 0.5 : 0.32), 0, 1) : 0;
  const swingAngle = attack
    ? (anim === 'heavy' ? -1.9 + attackT * 3.4 : -1.45 + attackT * 2.8) * side
    : (blocking ? -0.15 * side : -0.45 * side);
  const dodge = anim === 'dodge';
  const cast = anim === 'cast';
  const lean = dodge ? 10 * side : 0;

  ctx.save();
  ctx.translate(x + lean * 0.3, y - bob);
  ctx.scale(scale, scale);
  if (dead) {
    ctx.translate(0, -6);
    ctx.rotate(side * Math.PI * 0.46);
    ctx.globalAlpha = 0.82;
  }
  shadow(ctx, -lean * 0.3, 2 + bob, 12, 4.5, 0.3);

  // Piernas.
  const legSwing = moving ? swing * (run ? 6 : 4) : 0;
  ctx.fillStyle = '#2a2230';
  roundRect(ctx, -7 + legSwing, -15, 6, 16, 3); ctx.fill();
  roundRect(ctx, 1 - legSwing, -15, 6, 16, 3); ctx.fill();
  ctx.fillStyle = '#1a141c';
  roundRect(ctx, -8 + legSwing, -3, 8, 4, 2); ctx.fill();
  roundRect(ctx, 0 - legSwing, -3, 8, 4, 2); ctx.fill();

  // Capa.
  if (showCape && a.cape !== false) {
    const sway = Math.sin(t * (moving ? 8 : 2.4)) * (moving ? 5 : 2);
    ctx.fillStyle = cape;
    ctx.globalAlpha = 0.92;
    ctx.beginPath();
    ctx.moveTo(-9, -34);
    ctx.quadraticCurveTo(-15 - sway, -18, -13 - sway, 0);
    ctx.lineTo(4 + sway, -2);
    ctx.quadraticCurveTo(13 + sway, -18, 9, -34);
    ctx.closePath(); ctx.fill();
    ctx.globalAlpha = 1;
    ctx.strokeStyle = 'rgba(255,255,255,0.12)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-8, -32); ctx.quadraticCurveTo(-10 - sway, -16, -10 - sway, -2); ctx.stroke();
  }

  // Torso.
  const bodyGrad = ctx.createLinearGradient(0, -36, 0, -10);
  bodyGrad.addColorStop(0, armor);
  bodyGrad.addColorStop(1, '#2a2230');
  ctx.fillStyle = bodyGrad;
  roundRect(ctx, -10, -36, 20, 25, 5); ctx.fill();
  ctx.fillStyle = rgba('#ffffff', 0.12);
  roundRect(ctx, -9, -35, 8, 18, 4); ctx.fill();

  if (armorColor || npc) {
    ctx.strokeStyle = 'rgba(255,255,255,0.2)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(-9, -26); ctx.lineTo(9, -26); ctx.stroke();
    ctx.fillStyle = '#c8b080';
    ctx.fillRect(-11, -25, 22, 3);
  }
  // Cinturón.
  ctx.fillStyle = '#4a3524';
  ctx.fillRect(-10, -16, 20, 4);
  ctx.fillStyle = '#c8b080';
  ctx.fillRect(-2, -16, 4, 4);

  // Hombros / brazos.
  const armSwing = moving ? swing * (run ? 5 : 3) : 0;
  ctx.strokeStyle = skin;
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-9, -32);
  ctx.lineTo(-12 + armSwing, -20);
  ctx.stroke();
  const handX = 12 + (attack ? Math.cos(swingAngle) * 4 : 0);
  const handY = -22 + (attack ? Math.sin(swingAngle) * 2 : 0);
  ctx.beginPath();
  ctx.moveTo(9, -32);
  ctx.lineTo(handX, handY);
  ctx.stroke();
  ctx.fillStyle = skin;
  ctx.beginPath(); ctx.arc(handX, handY, 2.4, 0, TAU); ctx.fill();

  if (cast) {
    glowCircle(ctx, -13 + armSwing, -26, 18, '#ffe7a8', 0.4);
  }

  // Cabeza.
  const headY = -46;
  ctx.fillStyle = skin;
  ctx.beginPath(); ctx.arc(0, headY, 9, 0, TAU); ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.1)';
  ctx.beginPath(); ctx.ellipse(0, headY + 7, 7, 3, 0, 0, TAU); ctx.fill();

  const hasHelmet = a.helmet || helmetColor;
  if (!hasHelmet) {
    humanHair(ctx, a.hairStyle ?? 0, hairColor, headY, 9, facing, t);
  } else {
    ctx.fillStyle = helmetColor || '#9fc9d8';
    ctx.beginPath();
    ctx.arc(0, headY - 1, 9.6, Math.PI, TAU);
    ctx.lineTo(9.6, headY + 2);
    ctx.lineTo(5, headY + 2);
    ctx.lineTo(4, headY + 8);
    ctx.lineTo(-4, headY + 8);
    ctx.lineTo(-5, headY + 2);
    ctx.lineTo(-9.6, headY + 2);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, headY - 10); ctx.lineTo(0, headY + 8); ctx.stroke();
    ctx.fillStyle = '#c8b080';
    ctx.fillRect(-10, headY - 2, 20, 2);
    if ((a.helmetPlume ?? true) && a.cape !== false) {
      ctx.fillStyle = cape;
      ctx.beginPath(); ctx.moveTo(0, headY - 10); ctx.quadraticCurveTo(-6, headY - 20, -12, headY - 12); ctx.quadraticCurveTo(-6, headY - 10, 0, headY - 7); ctx.fill();
    }
  }

  // Rasgos faciales.
  if (fy > -0.45) {
    const ex = side * 1.8;
    eye(ctx, -3.4 + ex, headY + 1, 1.45, eyeColor);
    eye(ctx, 3.4 + ex, headY + 1, 1.45, eyeColor);
    ctx.strokeStyle = 'rgba(80,40,40,0.6)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.arc(ex, headY + 5.4, 2.2, 0.15, Math.PI - 0.15); ctx.stroke();
  } else {
    ctx.fillStyle = hairColor;
    ctx.beginPath(); ctx.arc(0, headY, 8.6, 0, TAU); ctx.fill();
  }

  // Arma.
  if (weapon && !npc) {
    ctx.save();
    ctx.translate(handX, handY);
    if (blocking) {
      ctx.translate(-side * 2, 0);
      ctx.rotate(side * -0.1);
    }
    drawWeapon(ctx, weaponType, weaponColor, side, swingAngle, anim === 'heavy');
    ctx.restore();
  }

  // Accesorio brillante.
  if (accessoryColor) {
    glowCircle(ctx, 0, -28, 13, accessoryColor, 0.28);
    ctx.fillStyle = accessoryColor;
    ctx.beginPath(); ctx.arc(0, -27, 2.2, 0, TAU); ctx.fill();
  }
  if (flash > 0) {
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = clamp(flash * 6, 0, 0.65);
    ctx.fillStyle = '#fff3c4';
    roundRect(ctx, -12, -52, 24, 54, 8); ctx.fill();
  }
  ctx.restore();
}

export function drawPlayer(ctx, player, time) {
  const inv = player.game.inventory;
  const weapon = inv?.weapon?.();
  const armorId = inv?.equipment?.armor;
  const helmetId = inv?.equipment?.helmet;
  const accId = inv?.equipment?.accessory;
  const armorItem = armorId ? ITEMS[armorId] : null;
  const helmetItem = helmetId ? ITEMS[helmetId] : null;
  const accItem = accId ? ITEMS[accId] : null;
  drawHumanoid(ctx, player.x, player.y, {
    appearance: player.appearance,
    anim: player.dead ? 'dead' : player.anim,
    animTime: player.animTime,
    facing: player.facing,
    scale: 1,
    weapon: weapon?.id || 'rusty_sword',
    weaponType: weapon?.weaponType || 'sword',
    weaponColor: weapon?.color || '#d8d2c4',
    armorColor: armorItem?.color || player.appearance.armorColor,
    helmetColor: helmetItem?.color || null,
    accessoryColor: accItem?.color || null,
    capeColor: player.appearance.capeColor,
    blocking: player.blocking,
    flash: player.hurtFlash,
    dead: player.dead,
    showCape: player.appearance.cape,
  });
  if (player.status?.veil) {
    ctx.save(); ctx.globalAlpha = 0.25;
    ctx.fillStyle = '#7d6a9e';
    ctx.beginPath(); ctx.arc(player.x, player.y - 24, 24, 0, TAU); ctx.fill(); ctx.restore();
  }
  if (player.status?.shield) {
    glowCircle(ctx, player.x, player.y - 22, 30, '#9fe8ff', 0.2);
    ctx.strokeStyle = 'rgba(159,232,255,0.45)'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(player.x, player.y - 22, 24, 0, TAU); ctx.stroke();
  }
  if (player.status?.regen) {
    if (Math.random() < 0.15) {
      player.game.particles.spawn('spark', player.x + (Math.random() - 0.5) * 20, player.y - Math.random() * 30, { color: '#8fd18a', size: 2, life: 0.6, speed: 12 });
    }
  }
}

export function drawNpc(ctx, npc, time) {
  const p = PORTRAITS[npc.id] || { name: npc.id, skin: '#d8b890', hair: '#3a2a1a', cloth: '#5a4a4a', accent: '#d9b46a' };
  const special = npc.id === 'aurel' || npc.id === 'echo' || npc.id === 'vela';
  drawHumanoid(ctx, npc.x, npc.y, {
    appearance: {
      skin: p.skin, hairColor: p.hair, hairStyle: npc.id === 'maren' ? 1 : npc.id === 'lyra' ? 2 : npc.id === 'kael' ? 0 : 3,
      eyeColor: p.accent, outfit: p.cloth, armorColor: npc.id === 'kael' ? '#5a5a6a' : null,
      cape: npc.id === 'kael' || npc.id === 'aurel', capeColor: p.cloth,
      helmet: npc.id === 'kael', helmetPlume: true,
    },
    anim: 'idle', animTime: time + (npc.x % 10), facing: Math.PI / 2 + Math.sin(time * 0.5 + npc.x) * 0.3,
    scale: npc.id === 'aurel' ? 0.9 : 1,
    npc: true, accessoryColor: p.accent,
    showCape: npc.id !== 'maren' && npc.id !== 'sela' && npc.id !== 'elina',
  });
  if (special || npc.id === 'aurel') {
    glowCircle(ctx, npc.x, npc.y - 26, 34, p.accent, 0.14);
    if (npc.id === 'aurel') {
      // Orejas y cola de zorro para el eco.
      ctx.fillStyle = p.accent;
      ctx.beginPath(); ctx.moveTo(npc.x - 8, npc.y - 54); ctx.lineTo(npc.x - 12, npc.y - 64); ctx.lineTo(npc.x - 3, npc.y - 58); ctx.fill();
      ctx.beginPath(); ctx.moveTo(npc.x + 8, npc.y - 54); ctx.lineTo(npc.x + 12, npc.y - 64); ctx.lineTo(npc.x + 3, npc.y - 58); ctx.fill();
      ctx.strokeStyle = p.accent; ctx.lineWidth = 4; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(npc.x + 8, npc.y - 16); ctx.quadraticCurveTo(npc.x + 26, npc.y - 12 + Math.sin(time * 2) * 4, npc.x + 22, npc.y - 30); ctx.stroke();
    }
  }
  if (npc.id === 'survivor1' || npc.id === 'survivor2' || npc.id === 'survivor3' || npc.id === 'survivor4') {
    // Los supervivientes llevan capas raídas.
    ctx.strokeStyle = 'rgba(40,30,26,0.4)'; ctx.lineWidth = 1;
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.moveTo(npc.x - 8 + i * 7, npc.y - 20); ctx.lineTo(npc.x - 10 + i * 7, npc.y - 2); ctx.stroke();
    }
  }
}

import { TAU, clamp, rgba } from '../../core/utils.js';
import { CREATURES } from '../../data/creatures.js';
import { shadow, glowCircle, line, star, roundRect, flame, crystalShape, eye } from './common.js';
import { drawHumanoid } from './characters.js';

export function drawEnemy(ctx, enemy, time) {
  const alpha = enemy.dead ? clamp(1 - enemy.deathTime / 2.4, 0, 1) : 1;
  if (alpha <= 0) return;
  ctx.save();
  ctx.globalAlpha = alpha;
  const t = enemy.animTime || time;
  const x = enemy.x, y = enemy.y;
  const s = enemy.scale || 1;
  const moving = enemy.anim === 'walk' || enemy.anim === 'run' || enemy.anim === 'dash';
  const bob = moving ? Math.abs(Math.sin(t * 10)) * 2 : Math.sin(t * 2.2) * 0.8;
  const facingLeft = Math.cos(enemy.facing) < 0;
  const flash = enemy.flash > 0;

  switch (enemy.sprite) {
    case 'slime': {
      shadow(ctx, x, y, 14 * s, 5 * s, 0.28);
      const squash = 1 + Math.sin(t * 4) * 0.08;
      const g = ctx.createRadialGradient(x - 4 * s, y - 18 * s, 2, x, y - 12 * s, 18 * s);
      g.addColorStop(0, '#c9f29a');
      g.addColorStop(0.45, '#7fbf6a');
      g.addColorStop(1, '#3f6636');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.ellipse(x, y - 12 * s * squash, 16 * s, 13 * s / squash, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      ctx.beginPath(); ctx.ellipse(x - 5 * s, y - 20 * s, 4 * s, 2.5 * s, -0.4, 0, TAU); ctx.fill();
      eye(ctx, x - 5 * s, y - 14 * s, 2.4 * s, '#2a3a2a');
      eye(ctx, x + 5 * s, y - 14 * s, 2.4 * s, '#2a3a2a');
      ctx.strokeStyle = '#2a3a2a'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(x, y - 8 * s, 3 * s, 0.2, Math.PI - 0.2); ctx.stroke();
      break;
    }
    case 'wolf': {
      shadow(ctx, x, y, 17 * s, 5 * s, 0.3);
      const leg = moving ? Math.sin(t * 14) * 4 : 0;
      ctx.strokeStyle = '#2f3a2f'; ctx.lineWidth = 3.4 * s; ctx.lineCap = 'round';
      for (let i = 0; i < 4; i++) {
        const lx = x - 10 * s + (i % 2) * 20 * s;
        const ly = y - 12 * s;
        ctx.beginPath(); ctx.moveTo(lx, ly); ctx.lineTo(lx + (i < 2 ? leg : -leg), y); ctx.stroke();
      }
      ctx.fillStyle = '#5d6b55';
      ctx.beginPath(); ctx.ellipse(x, y - 18 * s, 18 * s, 10 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#4a5746';
      ctx.beginPath(); ctx.ellipse(x, y - 20 * s, 12 * s, 8 * s, 0, 0, TAU); ctx.fill();
      // Espinas.
      ctx.strokeStyle = '#a9c98a'; ctx.lineWidth = 1.6 * s;
      for (let i = 0; i < 4; i++) {
        const sx = x - 9 * s + i * 6 * s;
        ctx.beginPath(); ctx.moveTo(sx, y - 26 * s); ctx.lineTo(sx + 2, y - 33 * s); ctx.stroke();
      }
      const hx = x + (facingLeft ? -16 : 16) * s;
      ctx.fillStyle = '#5d6b55';
      ctx.beginPath(); ctx.ellipse(hx, y - 25 * s, 8 * s, 7 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.moveTo(hx - 5 * s, y - 30 * s); ctx.lineTo(hx - 8 * s, y - 39 * s); ctx.lineTo(hx, y - 32 * s); ctx.fill();
      ctx.beginPath(); ctx.moveTo(hx + 5 * s, y - 30 * s); ctx.lineTo(hx + 8 * s, y - 39 * s); ctx.lineTo(hx, y - 32 * s); ctx.fill();
      eye(ctx, hx + (facingLeft ? -2 : 2) * s, y - 27 * s, 1.7 * s, '#ffcf6a');
      ctx.strokeStyle = '#a9c98a'; ctx.lineWidth = 2.4 * s;
      ctx.beginPath(); ctx.moveTo(x - (facingLeft ? 16 : -16) * s, y - 20 * s); ctx.quadraticCurveTo(x - (facingLeft ? 30 : -30) * s, y - 28 * s + Math.sin(t * 6) * 4, x - (facingLeft ? 24 : -24) * s, y - 34 * s); ctx.stroke();
      break;
    }
    case 'human': {
      drawHumanoid(ctx, x, y, {
        appearance: { skin: '#b88a62', hairColor: '#3a2a1a', hairStyle: 4, outfit: '#4a3a3a', armorColor: '#5a4a42', eyeColor: '#ffcf6a', cape: true, capeColor: '#3a2a2a' },
        anim: enemy.anim === 'windup' ? 'heavy' : enemy.anim, animTime: t, facing: enemy.facing,
        weapon: 'bandit', weaponType: 'sword', weaponColor: '#b9a98e', scale: s,
      });
      break;
    }
    case 'wraith': {
      const float = Math.sin(t * 2.4) * 4;
      shadow(ctx, x, y, 12 * s, 4 * s, 0.2);
      glowCircle(ctx, x, y - 24 * s + float, 30 * s, '#8fd18a', 0.16);
      ctx.fillStyle = '#2f4a3a';
      ctx.beginPath();
      ctx.moveTo(x, y - 48 * s + float);
      ctx.quadraticCurveTo(x + 17 * s, y - 32 * s + float, x + 12 * s, y - 6 * s + float);
      ctx.quadraticCurveTo(x + 6 * s, y + 2 * s, x, y - 4 * s + float);
      ctx.quadraticCurveTo(x - 6 * s, y + 2 * s, x - 12 * s, y - 6 * s + float);
      ctx.quadraticCurveTo(x - 17 * s, y - 32 * s + float, x, y - 48 * s + float);
      ctx.fill();
      ctx.fillStyle = '#1e3228';
      ctx.beginPath(); ctx.ellipse(x, y - 42 * s + float, 9 * s, 10 * s, 0, 0, TAU); ctx.fill();
      eye(ctx, x - 3.5 * s, y - 43 * s + float, 1.8 * s, '#8fd18a');
      eye(ctx, x + 3.5 * s, y - 43 * s + float, 1.8 * s, '#8fd18a');
      ctx.strokeStyle = 'rgba(143,209,138,0.5)'; ctx.lineWidth = 1.2 * s;
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * TAU + t * 0.3;
        ctx.beginPath(); ctx.moveTo(x + Math.cos(a) * 10 * s, y - 10 * s + float); ctx.lineTo(x + Math.cos(a) * 18 * s, y + Math.sin(a) * 6 * s); ctx.stroke();
      }
      break;
    }
    case 'imp': {
      const float = Math.sin(t * 4) * 3;
      shadow(ctx, x, y, 10 * s, 4 * s, 0.25);
      glowCircle(ctx, x, y - 18 * s + float, 24 * s, '#ff7b4d', 0.16);
      ctx.fillStyle = '#6a3020';
      ctx.beginPath(); ctx.ellipse(x, y - 15 * s + float, 10 * s, 12 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#ff8a5c';
      ctx.beginPath(); ctx.ellipse(x, y - 16 * s + float, 6 * s, 8 * s, 0, 0, TAU); ctx.fill();
      // Alas.
      ctx.fillStyle = 'rgba(90,40,30,0.85)';
      ctx.beginPath(); ctx.moveTo(x - 8 * s, y - 22 * s + float); ctx.quadraticCurveTo(x - 22 * s, y - 34 * s + float, x - 18 * s, y - 14 * s + float); ctx.closePath(); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 8 * s, y - 22 * s + float); ctx.quadraticCurveTo(x + 22 * s, y - 34 * s + float, x + 18 * s, y - 14 * s + float); ctx.closePath(); ctx.fill();
      // Cuernos.
      ctx.strokeStyle = '#ffd08a'; ctx.lineWidth = 2 * s;
      ctx.beginPath(); ctx.moveTo(x - 5 * s, y - 28 * s + float); ctx.lineTo(x - 9 * s, y - 37 * s + float); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x + 5 * s, y - 28 * s + float); ctx.lineTo(x + 9 * s, y - 37 * s + float); ctx.stroke();
      eye(ctx, x - 2.5 * s, y - 19 * s + float, 1.6 * s, '#ffcf6a');
      eye(ctx, x + 2.5 * s, y - 19 * s + float, 1.6 * s, '#ffcf6a');
      break;
    }
    case 'golem': {
      shadow(ctx, x, y, 24 * s, 8 * s, 0.38);
      const leg = moving ? Math.sin(t * 7) * 3 : 0;
      ctx.fillStyle = '#2a2a36';
      ctx.fillRect(x - 16 * s, y - 20 * s, 12 * s, 20 * s);
      ctx.fillRect(x + 4 * s, y - 20 * s, 12 * s, 20 * s);
      ctx.fillStyle = '#4a4a5e';
      roundRect(ctx, x - 22 * s, y - 54 * s, 44 * s, 38 * s, 6 * s); ctx.fill();
      ctx.fillStyle = '#5a5a72';
      roundRect(ctx, x - 18 * s, y - 50 * s, 16 * s, 26 * s, 4 * s); ctx.fill();
      ctx.fillStyle = '#3a3a4c';
      ctx.beginPath(); ctx.arc(x, y - 62 * s, 12 * s, 0, TAU); ctx.fill();
      glowCircle(ctx, x, y - 62 * s, 22 * s, '#8a7aa8', 0.2);
      eye(ctx, x - 4 * s, y - 64 * s, 1.8 * s, '#c7a4ff');
      eye(ctx, x + 4 * s, y - 64 * s, 1.8 * s, '#c7a4ff');
      ctx.strokeStyle = 'rgba(199,164,255,0.7)'; ctx.lineWidth = 1.6 * s;
      ctx.beginPath(); ctx.moveTo(x - 12 * s, y - 44 * s); ctx.lineTo(x, y - 34 * s); ctx.lineTo(x + 12 * s, y - 44 * s); ctx.stroke();
      ctx.fillStyle = '#3a3a4c';
      ctx.fillRect(x - 30 * s, y - 48 * s + leg, 8 * s, 30 * s);
      ctx.fillRect(x + 22 * s, y - 48 * s - leg, 8 * s, 30 * s);
      break;
    }
    case 'knight': {
      drawHumanoid(ctx, x, y, {
        appearance: { skin: '#c8a888', hairColor: '#2a2a2a', hairStyle: 0, outfit: '#3a3a4a', armorColor: '#4a4a5a', helmet: true, eyeColor: '#ff9a5c', cape: true, capeColor: '#2a1a1a' },
        anim: enemy.anim === 'windup' ? 'heavy' : enemy.anim, animTime: t, facing: enemy.facing,
        weapon: 'fallen', weaponType: 'greatsword', weaponColor: '#ff7b4d', helmetColor: '#5a5a6a', scale: s,
      });
      glowCircle(ctx, x, y - 30, 30, '#ff7b4d', 0.1);
      break;
    }
    case 'lizard': {
      shadow(ctx, x, y, 18 * s, 6 * s, 0.32);
      const leg = moving ? Math.sin(t * 12) * 4 : 0;
      ctx.strokeStyle = '#5a1f18'; ctx.lineWidth = 4 * s; ctx.lineCap = 'round';
      for (let i = 0; i < 4; i++) {
        const lx = x - 12 * s + (i % 2) * 24 * s;
        ctx.beginPath(); ctx.moveTo(lx, y - 10 * s); ctx.lineTo(lx + (i < 2 ? leg : -leg), y); ctx.stroke();
      }
      ctx.fillStyle = '#ff6a3d';
      ctx.beginPath(); ctx.ellipse(x, y - 15 * s, 20 * s, 10 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#ffb35c';
      ctx.beginPath(); ctx.ellipse(x, y - 20 * s, 14 * s, 5 * s, 0, 0, TAU); ctx.fill();
      const hx = x + (facingLeft ? -18 : 18) * s;
      ctx.fillStyle = '#ff6a3d';
      ctx.beginPath(); ctx.ellipse(hx, y - 20 * s, 8 * s, 6 * s, 0, 0, TAU); ctx.fill();
      eye(ctx, hx + (facingLeft ? -2 : 2) * s, y - 22 * s, 1.7 * s, '#ffcf6a');
      ctx.strokeStyle = '#ff6a3d'; ctx.lineWidth = 4 * s;
      ctx.beginPath(); ctx.moveTo(x - (facingLeft ? 16 : -16) * s, y - 16 * s); ctx.quadraticCurveTo(x - (facingLeft ? 30 : -30) * s, y - 10 * s + Math.sin(t * 5) * 5, x - (facingLeft ? 24 : -24) * s, y - 22 * s); ctx.stroke();
      for (let i = 0; i < 3; i++) flame(ctx, x - 8 * s + i * 8 * s, y - 22 * s, 0.28 * s, time + i, '#ff7b4d');
      break;
    }
    case 'orb': {
      const float = Math.sin(t * 2) * 5;
      glowCircle(ctx, x, y - 26 * s + float, 42 * s, '#ffe7a8', 0.22);
      ctx.strokeStyle = 'rgba(255,231,168,0.5)'; ctx.lineWidth = 1.4 * s;
      ctx.beginPath(); ctx.ellipse(x, y - 26 * s + float, 18 * s, 7 * s, 0.5, 0, TAU); ctx.stroke();
      ctx.beginPath(); ctx.ellipse(x, y - 26 * s + float, 18 * s, 7 * s, -0.5, 0, TAU); ctx.stroke();
      ctx.fillStyle = '#fffbe8';
      ctx.beginPath(); ctx.arc(x, y - 26 * s + float, 10 * s, 0, TAU); ctx.fill();
      eye(ctx, x, y - 26 * s + float, 5 * s, '#ffe7a8');
      break;
    }
    case 'angel': {
      const float = Math.sin(t * 2.2) * 4;
      shadow(ctx, x, y, 13 * s, 4 * s, 0.2);
      glowCircle(ctx, x, y - 34 * s + float, 34 * s, '#c7a4ff', 0.16);
      ctx.fillStyle = '#e8e0f0';
      ctx.beginPath(); ctx.moveTo(x - 8 * s, y - 38 * s + float); ctx.quadraticCurveTo(x - 30 * s, y - 52 * s + float, x - 26 * s, y - 18 * s + float); ctx.quadraticCurveTo(x - 18 * s, y - 30 * s + float, x - 8 * s, y - 30 * s + float); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 8 * s, y - 38 * s + float); ctx.quadraticCurveTo(x + 30 * s, y - 52 * s + float, x + 26 * s, y - 18 * s + float); ctx.quadraticCurveTo(x + 18 * s, y - 30 * s + float, x + 8 * s, y - 30 * s + float); ctx.fill();
      ctx.fillStyle = '#ffe7a8';
      ctx.beginPath(); ctx.ellipse(x, y - 18 * s + float, 8 * s, 18 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#f4efe8';
      ctx.beginPath(); ctx.arc(x, y - 42 * s + float, 8 * s, 0, TAU); ctx.fill();
      eye(ctx, x - 2.5 * s, y - 43 * s + float, 1.6 * s, '#c7a4ff');
      eye(ctx, x + 2.5 * s, y - 43 * s + float, 1.6 * s, '#c7a4ff');
      ctx.strokeStyle = '#ffe7a8'; ctx.lineWidth = 2 * s;
      ctx.beginPath(); ctx.ellipse(x, y - 56 * s + float, 11 * s, 4 * s, 0, 0, TAU); ctx.stroke();
      break;
    }
    case 'eye': {
      const float = Math.sin(t * 1.7) * 5;
      glowCircle(ctx, x, y - 30 * s + float, 40 * s, '#7d6a9e', 0.22);
      ctx.fillStyle = '#1e1628';
      ctx.beginPath(); ctx.arc(x, y - 30 * s + float, 18 * s, 0, TAU); ctx.fill();
      ctx.fillStyle = '#c7a4ff';
      ctx.beginPath(); ctx.ellipse(x, y - 30 * s + float, 12 * s, 8 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#0a0610';
      ctx.beginPath(); ctx.arc(x, y - 30 * s + float, 5 * s, 0, TAU); ctx.fill();
      ctx.fillStyle = '#fff3c4';
      ctx.beginPath(); ctx.arc(x - 2 * s, y - 32 * s + float, 1.5 * s, 0, TAU); ctx.fill();
      ctx.strokeStyle = 'rgba(125,106,158,0.6)'; ctx.lineWidth = 1.6 * s;
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * TAU + t * 0.2;
        ctx.beginPath();
        ctx.moveTo(x + Math.cos(a) * 14 * s, y - 24 * s + float + Math.sin(a) * 12 * s);
        ctx.quadraticCurveTo(x + Math.cos(a) * 22 * s, y - 10 * s + float, x + Math.cos(a) * 16 * s, y + 2 * s);
        ctx.stroke();
      }
      break;
    }
    case 'moth': {
      const float = Math.sin(t * 5) * 4;
      glowCircle(ctx, x, y - 24 * s + float, 26 * s, '#ffe7a8', 0.3);
      ctx.fillStyle = 'rgba(255,231,168,0.55)';
      ctx.beginPath(); ctx.ellipse(x - 9 * s, y - 28 * s + float, 11 * s, 7 * s, -0.5, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.ellipse(x + 9 * s, y - 28 * s + float, 11 * s, 7 * s, 0.5, 0, TAU); ctx.fill();
      ctx.fillStyle = '#ffb84d';
      ctx.beginPath(); ctx.ellipse(x, y - 24 * s + float, 4 * s, 8 * s, 0, 0, TAU); ctx.fill();
      star(ctx, x, y - 24 * s + float, 4 * s, '#fff3c4', 4, t);
      break;
    }
    case 'deer': {
      const float = Math.sin(t * 2) * 2;
      shadow(ctx, x, y, 16 * s, 5 * s, 0.25);
      ctx.strokeStyle = '#5f8fa8'; ctx.lineWidth = 2.6 * s; ctx.lineCap = 'round';
      for (let i = 0; i < 4; i++) {
        const lx = x - 10 * s + (i % 2) * 20 * s;
        ctx.beginPath(); ctx.moveTo(lx, y - 16 * s); ctx.lineTo(lx + (i < 2 ? 2 : -2) * s, y); ctx.stroke();
      }
      ctx.fillStyle = '#bfefff';
      ctx.beginPath(); ctx.ellipse(x, y - 22 * s, 16 * s, 9 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#e8fbff';
      ctx.beginPath(); ctx.ellipse(x - 3 * s, y - 26 * s, 10 * s, 4 * s, 0, 0, TAU); ctx.fill();
      const hx = x + (facingLeft ? -15 : 15) * s;
      ctx.fillStyle = '#bfefff';
      ctx.beginPath(); ctx.ellipse(hx, y - 30 * s + float, 6 * s, 8 * s, 0, 0, TAU); ctx.fill();
      eye(ctx, hx + (facingLeft ? -1 : 1) * s, y - 32 * s + float, 1.5 * s, '#5f8fa8');
      ctx.strokeStyle = '#e8fbff'; ctx.lineWidth = 1.5 * s;
      ctx.beginPath(); ctx.moveTo(hx, y - 37 * s + float); ctx.lineTo(hx - 4 * s, y - 50 * s + float); ctx.lineTo(hx - 10 * s, y - 54 * s + float); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(hx - 4 * s, y - 50 * s + float); ctx.lineTo(hx + 2 * s, y - 54 * s + float); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(hx, y - 37 * s + float); ctx.lineTo(hx + 4 * s, y - 50 * s + float); ctx.lineTo(hx + 10 * s, y - 54 * s + float); ctx.stroke();
      glowCircle(ctx, hx, y - 50 * s + float, 14 * s, '#bfefff', 0.25);
      break;
    }
    case 'bird': {
      const float = Math.sin(t * 3) * 6;
      shadow(ctx, x, y, 8 * s, 3 * s, 0.18);
      ctx.fillStyle = '#241c30';
      ctx.beginPath(); ctx.ellipse(x, y - 30 * s + float, 9 * s, 6 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x - 4 * s, y - 32 * s + float); ctx.quadraticCurveTo(x - 18 * s, y - 40 * s + float, x - 12 * s, y - 24 * s + float); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 4 * s, y - 32 * s + float); ctx.quadraticCurveTo(x + 18 * s, y - 40 * s + float, x + 12 * s, y - 24 * s + float); ctx.fill();
      ctx.fillStyle = '#a08ab8';
      ctx.beginPath(); ctx.arc(x + (facingLeft ? -8 : 8) * s, y - 34 * s + float, 3 * s, 0, TAU); ctx.fill();
      eye(ctx, x + (facingLeft ? -8 : 8) * s, y - 34 * s + float, 1.1 * s, '#c7a4ff');
      ctx.fillStyle = '#5a4a6e';
      ctx.beginPath(); ctx.moveTo(x + (facingLeft ? -12 : 12) * s, y - 33 * s + float); ctx.lineTo(x + (facingLeft ? -18 : 18) * s, y - 31 * s + float); ctx.lineTo(x + (facingLeft ? -12 : 12) * s, y - 29 * s + float); ctx.fill();
      if (Math.random() < 0.3) {
        enemy.game.particles.spawn('smoke', x + (Math.random() - 0.5) * 20, y - 20 * s + float, { color: '#5a4a6e', size: 4, life: 0.5, speed: 8, additive: false });
      }
      break;
    }
    default:
      drawHumanoid(ctx, x, y, { appearance: { skin: '#b88a62', hairColor: '#3a2a1a', outfit: '#5a4a3a' }, anim: enemy.anim, animTime: t, facing: enemy.facing, scale: s });
      break;
  }

  if (flash) {
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = clamp(enemy.flash * 5, 0, 0.7);
    ctx.fillStyle = '#fff3c4';
    ctx.beginPath(); ctx.arc(x, y - 24 * s, 20 * s, 0, TAU); ctx.fill();
  }
  if (enemy.status?.burn) {
    if (Math.random() < 0.4) enemy.game.particles.spawn('ember', x + (Math.random() - 0.5) * 16, y - 14 * s, { color: '#ff9a5c', size: 2, life: 0.4, speed: 20 });
  }
  ctx.restore();
}

export function drawBoss(ctx, boss, time) {
  const t = boss.animTime || time;
  const s = boss.scale || 1;
  const x = boss.x, y = boss.y;
  const alpha = boss.dead ? clamp(1 - boss.deathTime / 3.2, 0, 1) : 1;
  if (alpha <= 0) return;
  ctx.save();
  ctx.globalAlpha = alpha;
  const flash = boss.flash > 0;
  const phaseGlow = boss.phase === 0 ? '#8fd18a' : boss.phase === 1 ? '#ff9a5c' : '#c7a4ff';
  glowCircle(ctx, x, y - 50 * s, 90 * s, phaseGlow, 0.12);

  if (boss.sprite === 'treant') {
    shadow(ctx, x, y, 50 * s, 16 * s, 0.4);
    // Raíces.
    ctx.strokeStyle = '#2a3a24'; ctx.lineWidth = 12 * s; ctx.lineCap = 'round';
    for (let i = 0; i < 5; i++) {
      const a = Math.PI + (i / 4) * Math.PI;
      ctx.beginPath();
      ctx.moveTo(x, y - 30 * s);
      ctx.quadraticCurveTo(x + Math.cos(a) * 50 * s, y - 6 * s, x + Math.cos(a) * 72 * s, y + 8 * s);
      ctx.stroke();
    }
    // Tronco.
    ctx.fillStyle = '#4a3a2a';
    ctx.beginPath();
    ctx.moveTo(x - 26 * s, y);
    ctx.quadraticCurveTo(x - 34 * s, y - 80 * s, x - 18 * s, y - 120 * s);
    ctx.lineTo(x + 18 * s, y - 120 * s);
    ctx.quadraticCurveTo(x + 34 * s, y - 80 * s, x + 26 * s, y);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#2a2018'; ctx.lineWidth = 3 * s;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath(); ctx.moveTo(x - 20 * s + i * 10 * s, y - 8 * s); ctx.quadraticCurveTo(x - 24 * s + i * 12 * s, y - 60 * s, x - 12 * s + i * 6 * s, y - 112 * s); ctx.stroke();
    }
    // Ramas.
    ctx.strokeStyle = '#3a2e22'; ctx.lineWidth = 7 * s;
    for (let i = 0; i < 4; i++) {
      const dir = i % 2 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(x + dir * 10 * s, y - 100 * s);
      ctx.quadraticCurveTo(x + dir * 55 * s, y - 125 * s, x + dir * 72 * s, y - 154 * s);
      ctx.stroke();
    }
    // Copa.
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU;
      const cx = x + Math.cos(a) * 38 * s;
      const cy = y - 140 * s + Math.sin(a) * 24 * s;
      const g = ctx.createRadialGradient(cx - 6, cy - 6, 2, cx, cy, 30 * s);
      g.addColorStop(0, '#5c8f4f');
      g.addColorStop(1, '#1e3c28');
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(cx, cy, 28 * s, 0, TAU); ctx.fill();
    }
    // Rostro.
    glowCircle(ctx, x, y - 80 * s, 28 * s, '#8fd18a', 0.25);
    eye(ctx, x - 10 * s, y - 84 * s, 5 * s, '#8fd18a');
    eye(ctx, x + 10 * s, y - 84 * s, 5 * s, '#8fd18a');
    ctx.strokeStyle = '#1a1212'; ctx.lineWidth = 3 * s;
    ctx.beginPath(); ctx.arc(x, y - 64 * s, 10 * s, 0.15, Math.PI - 0.15); ctx.stroke();
  } else if (boss.sprite === 'flameLady') {
    shadow(ctx, x, y, 30 * s, 10 * s, 0.35);
    // Vestido de fuego.
    const g = ctx.createLinearGradient(x, y - 110 * s, x, y);
    g.addColorStop(0, '#ffd98a');
    g.addColorStop(0.45, '#ff7b3d');
    g.addColorStop(1, '#8a2a1a');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(x - 14 * s, y - 88 * s);
    ctx.quadraticCurveTo(x - 38 * s, y - 44 * s, x - 32 * s, y);
    ctx.quadraticCurveTo(x, y + 10 * s, x + 32 * s, y);
    ctx.quadraticCurveTo(x + 38 * s, y - 44 * s, x + 14 * s, y - 88 * s);
    ctx.closePath(); ctx.fill();
    // Brazos.
    ctx.strokeStyle = '#ffb07a'; ctx.lineWidth = 6 * s; ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(x - 14 * s, y - 82 * s); ctx.lineTo(x - 34 * s, y - 58 * s + Math.sin(t * 2) * 4); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(x + 14 * s, y - 82 * s); ctx.lineTo(x + 34 * s, y - 58 * s - Math.sin(t * 2) * 4); ctx.stroke();
    // Cabeza.
    ctx.fillStyle = '#ffb07a';
    ctx.beginPath(); ctx.arc(x, y - 98 * s, 13 * s, 0, TAU); ctx.fill();
    eye(ctx, x - 4 * s, y - 99 * s, 2.2 * s, '#fff3c4');
    eye(ctx, x + 4 * s, y - 99 * s, 2.2 * s, '#fff3c4');
    // Cabello de llamas.
    for (let i = 0; i < 7; i++) {
      flame(ctx, x - 18 * s + i * 6 * s, y - 108 * s, 0.6 * s + (i % 2) * 0.18 * s, time + i * 0.4, '#ff5a2a');
    }
    // Lágrima en el pecho.
    glowCircle(ctx, x, y - 72 * s, 22 * s, '#ffe7a8', 0.4);
    star(ctx, x, y - 72 * s, 6 * s, '#fff3c4', 4, t * 0.5);
    if (boss.phase > 0) {
      for (let i = 0; i < 3; i++) {
        const a = t * 0.8 + i * TAU / 3;
        glowCircle(ctx, x + Math.cos(a) * 48 * s, y - 58 * s + Math.sin(a) * 18 * s, 16 * s, '#ff9a5c', 0.3);
      }
    }
  } else if (boss.sprite === 'veil') {
    const float = Math.sin(t * 1.4) * 8;
    shadow(ctx, x, y, 34 * s, 11 * s, 0.35);
    // Manto.
    ctx.fillStyle = '#1a1228';
    ctx.beginPath();
    ctx.moveTo(x, y - 150 * s + float);
    ctx.quadraticCurveTo(x + 46 * s, y - 100 * s + float, x + 40 * s, y + 4 * s);
    ctx.quadraticCurveTo(x + 20 * s, y + 16 * s, x, y + 4 * s);
    ctx.quadraticCurveTo(x - 20 * s, y + 16 * s, x - 40 * s, y + 4 * s);
    ctx.quadraticCurveTo(x - 46 * s, y - 100 * s + float, x, y - 150 * s + float);
    ctx.fill();
    // Interior estrellado.
    ctx.fillStyle = 'rgba(199,164,255,0.16)';
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU + t * 0.15;
      const rr = 18 * s + (i % 3) * 6 * s;
      ctx.beginPath(); ctx.arc(x + Math.cos(a) * rr, y - 78 * s + float + Math.sin(a) * rr, 2 * s, 0, TAU); ctx.fill();
    }
    // Máscara.
    ctx.fillStyle = '#e8e0f0';
    ctx.beginPath(); ctx.ellipse(x, y - 122 * s + float, 17 * s, 22 * s, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = '#0a0610';
    ctx.beginPath(); ctx.ellipse(x, y - 124 * s + float, 12 * s, 8 * s, 0, 0, TAU); ctx.fill();
    eye(ctx, x - 5 * s, y - 125 * s + float, 2.2 * s, '#c7a4ff');
    eye(ctx, x + 5 * s, y - 125 * s + float, 2.2 * s, '#c7a4ff');
    // Fragmentos espejo.
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * TAU + t * 0.5;
      const rx = x + Math.cos(a) * 62 * s;
      const ry = y - 80 * s + Math.sin(a) * 30 * s;
      ctx.save(); ctx.translate(rx, ry); ctx.rotate(a);
      crystalShape(ctx, 0, 12 * s, 24 * s, 5 * s, '#c7a4ff');
      ctx.restore();
    }
  } else {
    drawHumanoid(ctx, x, y, { appearance: { skin: '#8a7a5a', hairColor: '#3a4a2a', outfit: '#2f4a2a' }, anim: boss.anim, animTime: t, facing: boss.facing, scale: s, weapon: 'boss', weaponType: 'greatsword', weaponColor: '#8fd18a' });
  }

  if (flash) {
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = clamp(boss.flash * 5, 0, 0.65);
    ctx.fillStyle = '#fff3c4';
    ctx.beginPath(); ctx.arc(x, y - 50 * s, 48 * s, 0, TAU); ctx.fill();
  }
  ctx.restore();
}

export function drawCreature(ctx, id, x, y, scale, time) {
  const def = CREATURES[id];
  if (!def) return;
  const s = scale || 1;
  const t = time || 0;
  const colors = def.colors || ['#8fd18a', '#c9f29a', '#4d7a4a'];
  const float = Math.sin(t * 2.5 + x * 0.1) * 2.5;
  switch (def.sprite) {
    case 'slime': {
      shadow(ctx, x, y, 10 * s, 4 * s, 0.25);
      const g = ctx.createRadialGradient(x - 3 * s, y - 12 * s, 1, x, y - 8 * s, 13 * s);
      g.addColorStop(0, colors[1]); g.addColorStop(0.5, colors[0]); g.addColorStop(1, colors[2]);
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.ellipse(x, y - 8 * s + float, 11 * s, 9 * s, 0, 0, TAU); ctx.fill();
      eye(ctx, x - 3.5 * s, y - 10 * s + float, 1.6 * s, '#2a3a2a');
      eye(ctx, x + 3.5 * s, y - 10 * s + float, 1.6 * s, '#2a3a2a');
      glowCircle(ctx, x, y - 10 * s + float, 18 * s, colors[0], 0.16);
      break;
    }
    case 'wolf': {
      shadow(ctx, x, y, 12 * s, 4 * s, 0.25);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 10 * s + float, 12 * s, 6 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 9 * s, y - 15 * s + float, 5 * s, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 6 * s, y - 19 * s + float); ctx.lineTo(x + 5 * s, y - 25 * s + float); ctx.lineTo(x + 9 * s, y - 20 * s + float); ctx.fill();
      eye(ctx, x + 10 * s, y - 16 * s + float, 1.2 * s, '#ffe7a8');
      ctx.strokeStyle = colors[1]; ctx.lineWidth = 1.4 * s;
      ctx.beginPath(); ctx.moveTo(x - 10 * s, y - 12 * s + float); ctx.lineTo(x - 18 * s, y - 18 * s + float); ctx.stroke();
      break;
    }
    case 'moth': {
      glowCircle(ctx, x, y - 12 * s + float, 18 * s, colors[0], 0.3);
      ctx.fillStyle = rgba(colors[0], 0.55);
      ctx.beginPath(); ctx.ellipse(x - 6 * s, y - 14 * s + float, 7 * s, 4.5 * s, -0.5, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.ellipse(x + 6 * s, y - 14 * s + float, 7 * s, 4.5 * s, 0.5, 0, TAU); ctx.fill();
      ctx.fillStyle = colors[1];
      ctx.beginPath(); ctx.ellipse(x, y - 12 * s + float, 2.5 * s, 5 * s, 0, 0, TAU); ctx.fill();
      star(ctx, x, y - 12 * s + float, 2.5 * s, '#fff3c4', 4, t);
      break;
    }
    case 'deer': {
      shadow(ctx, x, y, 11 * s, 3.5 * s, 0.2);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 10 * s + float, 10 * s, 5 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 9 * s, y - 17 * s + float, 4 * s, 0, TAU); ctx.fill();
      ctx.strokeStyle = colors[1]; ctx.lineWidth = 1.2 * s;
      ctx.beginPath(); ctx.moveTo(x + 9 * s, y - 21 * s + float); ctx.lineTo(x + 6 * s, y - 28 * s + float); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x + 9 * s, y - 21 * s + float); ctx.lineTo(x + 12 * s, y - 28 * s + float); ctx.stroke();
      glowCircle(ctx, x + 9 * s, y - 24 * s + float, 10 * s, colors[0], 0.2);
      break;
    }
    case 'imp': {
      glowCircle(ctx, x, y - 12 * s + float, 16 * s, colors[0], 0.2);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 10 * s + float, 6 * s, 7 * s, 0, 0, TAU); ctx.fill();
      ctx.strokeStyle = colors[1]; ctx.lineWidth = 1.2 * s;
      ctx.beginPath(); ctx.moveTo(x - 3 * s, y - 16 * s + float); ctx.lineTo(x - 5 * s, y - 21 * s + float); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x + 3 * s, y - 16 * s + float); ctx.lineTo(x + 5 * s, y - 21 * s + float); ctx.stroke();
      eye(ctx, x - 1.8 * s, y - 11 * s + float, 1.1 * s, '#ffe7a8');
      eye(ctx, x + 1.8 * s, y - 11 * s + float, 1.1 * s, '#ffe7a8');
      break;
    }
    case 'lizard': {
      shadow(ctx, x, y, 13 * s, 4 * s, 0.25);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 9 * s + float, 13 * s, 6 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 11 * s, y - 12 * s + float, 4 * s, 0, TAU); ctx.fill();
      eye(ctx, x + 12 * s, y - 13 * s + float, 1.1 * s, '#ffe7a8');
      flame(ctx, x - 3 * s, y - 13 * s + float, 0.22 * s, t, colors[0]);
      break;
    }
    case 'golem': {
      shadow(ctx, x, y, 14 * s, 5 * s, 0.3);
      ctx.fillStyle = colors[0];
      roundRect(ctx, x - 11 * s, y - 28 * s + float, 22 * s, 20 * s, 3 * s); ctx.fill();
      ctx.fillStyle = colors[2];
      ctx.beginPath(); ctx.arc(x, y - 32 * s + float, 6 * s, 0, TAU); ctx.fill();
      eye(ctx, x - 2 * s, y - 33 * s + float, 1.1 * s, colors[1]);
      eye(ctx, x + 2 * s, y - 33 * s + float, 1.1 * s, colors[1]);
      break;
    }
    case 'bird': {
      shadow(ctx, x, y, 7 * s, 3 * s, 0.15);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 18 * s + float, 7 * s, 5 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x - 2 * s, y - 20 * s + float); ctx.quadraticCurveTo(x - 12 * s, y - 25 * s + float, x - 8 * s, y - 13 * s + float); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 2 * s, y - 20 * s + float); ctx.quadraticCurveTo(x + 12 * s, y - 25 * s + float, x + 8 * s, y - 13 * s + float); ctx.fill();
      eye(ctx, x + 5 * s, y - 20 * s + float, 1 * s, colors[1]);
      break;
    }
    case 'orb': {
      glowCircle(ctx, x, y - 18 * s + float, 24 * s, colors[0], 0.3);
      ctx.fillStyle = colors[1];
      ctx.beginPath(); ctx.arc(x, y - 18 * s + float, 8 * s, 0, TAU); ctx.fill();
      eye(ctx, x, y - 18 * s + float, 4 * s, colors[0]);
      break;
    }
    case 'angel': {
      glowCircle(ctx, x, y - 22 * s + float, 24 * s, colors[0], 0.2);
      ctx.fillStyle = colors[1];
      ctx.beginPath(); ctx.moveTo(x - 4 * s, y - 24 * s + float); ctx.quadraticCurveTo(x - 18 * s, y - 32 * s + float, x - 14 * s, y - 12 * s + float); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 4 * s, y - 24 * s + float); ctx.quadraticCurveTo(x + 18 * s, y - 32 * s + float, x + 14 * s, y - 12 * s + float); ctx.fill();
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 16 * s + float, 5 * s, 10 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(x, y - 28 * s + float, 4 * s, 0, TAU); ctx.fill();
      break;
    }
    case 'eye': {
      glowCircle(ctx, x, y - 18 * s + float, 22 * s, colors[0], 0.3);
      ctx.fillStyle = colors[2];
      ctx.beginPath(); ctx.arc(x, y - 18 * s + float, 10 * s, 0, TAU); ctx.fill();
      ctx.fillStyle = colors[1];
      ctx.beginPath(); ctx.ellipse(x, y - 18 * s + float, 7 * s, 4.5 * s, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#0a0610';
      ctx.beginPath(); ctx.arc(x, y - 18 * s + float, 3 * s, 0, TAU); ctx.fill();
      break;
    }
    case 'spirit': {
      glowCircle(ctx, x, y - 18 * s + float, 28 * s, colors[0], 0.28);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.ellipse(x, y - 16 * s + float, 11 * s, 8 * s, 0, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 8 * s, y - 23 * s + float, 5 * s, 0, TAU); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 5 * s, y - 28 * s + float); ctx.lineTo(x + 3 * s, y - 34 * s + float); ctx.lineTo(x + 8 * s, y - 29 * s + float); ctx.fill();
      ctx.beginPath(); ctx.moveTo(x + 11 * s, y - 28 * s + float); ctx.lineTo(x + 12 * s, y - 34 * s + float); ctx.lineTo(x + 14 * s, y - 27 * s + float); ctx.fill();
      eye(ctx, x + 9 * s, y - 23 * s + float, 1.4 * s, '#4a7a8a');
      ctx.strokeStyle = colors[1]; ctx.lineWidth = 2 * s;
      ctx.beginPath(); ctx.moveTo(x - 10 * s, y - 14 * s + float); ctx.quadraticCurveTo(x - 24 * s, y - 10 * s + float, x - 20 * s, y - 26 * s + float); ctx.stroke();
      break;
    }
    default: {
      glowCircle(ctx, x, y - 14 * s + float, 18 * s, colors[0], 0.2);
      ctx.fillStyle = colors[0];
      ctx.beginPath(); ctx.arc(x, y - 14 * s + float, 8 * s, 0, TAU); ctx.fill();
      break;
    }
  }
}

export function drawCompanion(ctx, comp, time) {
  drawCreature(ctx, comp.id, comp.x, comp.y, comp.temp ? 0.95 : 0.82, time + comp.animTime);
  comp.drawHealthRing(ctx);
}

import { TAU, rgba } from '../../core/utils.js';
import { PORTRAITS } from '../../data/story.js';
import { glowCircle, star, eye, humanHair, roundRect } from './common.js';

export function drawPortrait(ctx, w, h, portraitId, player, time = 0) {
  const p = portraitId === 'player'
    ? { name: player?.name || 'Tú', skin: player?.appearance?.skin || '#e8c9a8', hair: player?.appearance?.hairColor || '#3a2a1a', cloth: player?.appearance?.outfit || '#4a6a4a', accent: '#ffe7a8', role: 'Jugador Cero' }
    : PORTRAITS[portraitId] || { name: 'Eco', skin: '#c7a4ff', hair: '#e8e0ff', cloth: '#3a2a5a', accent: '#ffe7a8', role: '' };
  const cx = w / 2;
  ctx.clearRect(0, 0, w, h);
  // Fondo.
  const bg = ctx.createLinearGradient(0, 0, 0, h);
  bg.addColorStop(0, '#16101f');
  bg.addColorStop(0.55, '#241a30');
  bg.addColorStop(1, '#0c0812');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);
  const halo = ctx.createRadialGradient(cx, h * 0.32, 4, cx, h * 0.38, w * 0.62);
  halo.addColorStop(0, rgba(p.accent, 0.3));
  halo.addColorStop(0.55, rgba(p.accent, 0.09));
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, w, h);
  // Estrellas tenues.
  for (let i = 0; i < 18; i++) {
    const sx = (Math.sin(i * 37.1 + 4) * 0.5 + 0.5) * w;
    const sy = (Math.cos(i * 17.7 + 2) * 0.5 + 0.5) * h * 0.72;
    ctx.fillStyle = `rgba(255,255,255,${0.04 + (i % 3) * 0.04})`;
    ctx.beginPath(); ctx.arc(sx, sy, 0.8 + (i % 2), 0, TAU); ctx.fill();
  }

  const baseY = h * 0.44;
  const headR = w * 0.155;

  // Casos especiales.
  if (portraitId === 'veil') {
    ctx.fillStyle = '#0a0610';
    ctx.beginPath();
    ctx.moveTo(cx, h * 0.08);
    ctx.quadraticCurveTo(cx + w * 0.42, h * 0.4, cx + w * 0.34, h);
    ctx.lineTo(cx - w * 0.34, h);
    ctx.quadraticCurveTo(cx - w * 0.42, h * 0.4, cx, h * 0.08);
    ctx.fill();
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU + time * 0.1;
      const rr = w * (0.18 + (i % 3) * 0.04);
      ctx.fillStyle = `rgba(199,164,255,${0.2 + (i % 2) * 0.2})`;
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * rr, h * 0.44 + Math.sin(a) * rr * 0.7, 1.4, 0, TAU); ctx.fill();
    }
    ctx.fillStyle = '#e8e0f0';
    ctx.beginPath(); ctx.ellipse(cx, h * 0.38, w * 0.13, h * 0.14, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = '#0a0610';
    ctx.beginPath(); ctx.ellipse(cx, h * 0.37, w * 0.09, h * 0.055, 0, 0, TAU); ctx.fill();
    eye(ctx, cx - w * 0.04, h * 0.365, w * 0.018, '#c7a4ff');
    eye(ctx, cx + w * 0.04, h * 0.365, w * 0.018, '#c7a4ff');
    ctx.strokeStyle = 'rgba(199,164,255,0.55)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(cx, h * 0.38, w * 0.2, 0.2, Math.PI - 0.2); ctx.stroke();
    return;
  }
  if (portraitId === 'jarra') {
    glowCircle(ctx, cx, h * 0.48, w * 0.4, '#ffe7a8', 0.3);
    const g = ctx.createLinearGradient(cx - 40, h * 0.3, cx + 40, h * 0.75);
    g.addColorStop(0, '#fff3c4'); g.addColorStop(0.45, '#d9b46a'); g.addColorStop(1, '#6a4a1a');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(cx, h * 0.58, w * 0.16, h * 0.2, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#8a6a2a';
    ctx.beginPath(); ctx.ellipse(cx, h * 0.34, w * 0.08, h * 0.035, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = '#ffe7a8';
    ctx.beginPath(); ctx.ellipse(cx, h * 0.34, w * 0.05, h * 0.018, 0, 0, TAU); ctx.fill();
    for (let i = 0; i < 5; i++) {
      star(ctx, cx + Math.sin(time + i * 2) * w * 0.22, h * 0.28 + Math.cos(time * 0.7 + i) * h * 0.16, 3 + i % 2, '#fff3c4', 4, time * 0.4 + i);
    }
    return;
  }
  if (portraitId === 'guardian') {
    glowCircle(ctx, cx, h * 0.38, w * 0.38, '#8fd18a', 0.2);
    ctx.fillStyle = '#3a2e22';
    ctx.beginPath();
    ctx.moveTo(cx - w * 0.28, h);
    ctx.quadraticCurveTo(cx - w * 0.34, h * 0.44, cx - w * 0.18, h * 0.2);
    ctx.lineTo(cx + w * 0.18, h * 0.2);
    ctx.quadraticCurveTo(cx + w * 0.34, h * 0.44, cx + w * 0.28, h);
    ctx.closePath(); ctx.fill();
    for (let i = 0; i < 5; i++) {
      ctx.strokeStyle = '#2a2018'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(cx - w * 0.18 + i * w * 0.09, h * 0.22); ctx.quadraticCurveTo(cx - w * 0.22 + i * w * 0.11, h * 0.55, cx - w * 0.1 + i * w * 0.05, h); ctx.stroke();
    }
    for (let i = 0; i < 5; i++) {
      const a = Math.PI + (i / 4) * Math.PI;
      ctx.fillStyle = i % 2 ? '#5c8f4f' : '#2f5a37';
      ctx.beginPath(); ctx.arc(cx + Math.cos(a) * w * 0.32, h * 0.16 + Math.sin(a) * h * 0.14, w * 0.13, 0, TAU); ctx.fill();
    }
    eye(ctx, cx - w * 0.07, h * 0.38, w * 0.025, '#8fd18a');
    eye(ctx, cx + w * 0.07, h * 0.38, w * 0.025, '#8fd18a');
    ctx.strokeStyle = '#1a1212'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(cx, h * 0.47, w * 0.08, 0.2, Math.PI - 0.2); ctx.stroke();
    return;
  }
  if (portraitId === 'aurel') {
    glowCircle(ctx, cx, h * 0.42, w * 0.4, '#ffe7a8', 0.3);
    // Zorro espiritual.
    ctx.fillStyle = '#ffd98a';
    ctx.beginPath(); ctx.ellipse(cx, h * 0.55, w * 0.2, h * 0.16, 0, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(cx, h * 0.38, w * 0.14, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.moveTo(cx - w * 0.11, h * 0.3); ctx.lineTo(cx - w * 0.16, h * 0.18); ctx.lineTo(cx - w * 0.04, h * 0.27); ctx.fill();
    ctx.beginPath(); ctx.moveTo(cx + w * 0.11, h * 0.3); ctx.lineTo(cx + w * 0.16, h * 0.18); ctx.lineTo(cx + w * 0.04, h * 0.27); ctx.fill();
    eye(ctx, cx - w * 0.055, h * 0.37, w * 0.02, '#4a7a8a');
    eye(ctx, cx + w * 0.055, h * 0.37, w * 0.02, '#4a7a8a');
    ctx.fillStyle = '#6a4a2a';
    ctx.beginPath(); ctx.ellipse(cx, h * 0.43, w * 0.03, w * 0.02, 0, 0, TAU); ctx.fill();
    ctx.strokeStyle = '#ffd98a'; ctx.lineWidth = 5; ctx.lineCap = 'round';
