  // Sombra lateral.
  ctx.fillStyle = 'rgba(0,0,0,0.08)';
  ctx.beginPath(); ctx.ellipse(cx + headR * 0.34, baseY + 2, headR * 0.5, headR * 0.86, 0, 0, TAU); ctx.fill();
