14:   { id: 'barrera', name: 'Barrera del Velo', cost: 16, cooldown: 8, desc: 'Un escudo de luz que absorbe daño y te cura ligeramente.', color: '#9fe8ff' },
15: ];
16: 
17: export class Player {
18:   constructor(game, data = null) {
19:     this.game = game;
20:     this.radius = 10;
21:     this.x = 0; this.y = 0;
22:     this.vx = 0; this.vy = 0;
23:     this.facing = Math.PI / 2;
24:     this.anim = 'idle';
25:     this.animTime = 0;
26:     this.attackTime = 0;
27:     this.attackIndex = 0;
28:     this.comboTimer = 0;
29:     this.attackHit = new Set();
30:     this.heavy = false;
31:     this.dodgeTime = 0;
32:     this.dodgeCd = 0;
33:     this.invuln = 0;
34:     this.blocking = false;
35:     this.parryTimer = 0;
36:     this.parryCd = 0;
37:     this.castTime = 0;
38:     this.castSpell = null;
39:     this.hurtFlash = 0;
40:     this.dead = false;
41:     this.deadTime = 0;
42:     this.potionCd = 0;
43:     this.ult = 0;
44:     this.ultActive = 0;
45:     this.ultType = null;
46:     this.status = {};
47:     this.selectedSpell = 0;
48:     this.spellCooldowns = [0, 0, 0];
49:     this.stepTimer = 0;
50:     this.companionCooldown = 0;
51:     this.captureMode = false;
52:     this.lastSafe = null;
53:     this.kills = 0;
54:     this.captures = 0;
55:     this.damageDealt = 0;
56:     this.damageTaken = 0;
57:     this.playtime = 0;
58:     if (data) this.deserialize(data);
59:     else this.initNew();
60:   }
61: 
62:   get flags() { return this.game.flags; }
63:   get stats() { return this.baseStats; }
64:   get difficulty() { return DIFFICULTIES[this.game.settings.difficulty] || DIFFICULTIES.caballero; }
65: 
66:   initNew() {
67:     this.name = 'Peregrino';
68:     this.origin = 'brasa';
69:     this.appearance = { ...DEFAULT_APPEARANCE };
70:     this.baseStats = { ...BASE_STATS };
71:     this.bonusCrit = 0;
72:     this.level = 1;
73:     this.xp = 0;
74:     this.xpNext = 100;
75:     this.points = 8;
76:     this.skillPoints = 0;
77:     this.skills = {};
78:     this.gold = 60;
79:     this.hp = 100; this.mp = 30; this.stamina = 60;
80:     this.maxHp = 100; this.maxMp = 30; this.maxStamina = 60;
81:     this.region = 'valdoria';
82:     this.lastWaypoint = null;
83:     this.recalc(true);
84:     this.hp = this.maxHp; this.mp = this.maxMp; this.stamina = this.maxStamina;
85:   }
86: 
87:   applyOrigin(origin) {
88:     this.origin = origin;
89:     const o = ORIGINS[origin] || ORIGINS.brasa;
90:     this.baseStats = { ...BASE_STATS };
91:     for (const [k, v] of Object.entries(o.bonus)) {
92:       if (k === 'crit') this.bonusCrit += v * 0.02;
93:       else if (k === 'mana') this.baseStats.mana += v;
94:       else this.baseStats[k] = (this.baseStats[k] || 0) + v;
95:     }
96:     this.recalc(true);
97:     this.hp = this.maxHp; this.mp = this.maxMp; this.stamina = this.maxStamina;
98:   }
99: 
100:   recalc(full = false) {
101:     const eq = this.game.inventory?.equipmentStats() || {};
102:     const passive = this.game.collection?.passiveStats() || {};
103:     const s = this.baseStats;
104:     this.maxHp = Math.round(80 + (s.vit + (passive.vit || 0)) * 8 + (eq.hp || 0));
105:     this.maxMp = Math.round(30 + (s.mana + (passive.mana || 0)) * 4 + (eq.mp || 0));
106:     this.maxStamina = Math.round(60 + (s.res + (passive.res || 0)) * 4);
107:     this.attack = 6 + (s.str + (passive.str || 0)) * 1.55 + (eq.atk || 0);
108:     this.spellPower = 12 + (s.int + (passive.int || 0)) * 2.3 + (eq.int || 0) * 1.6;
109:     this.defense = (s.def + (passive.def || 0)) * 1.2 + (eq.def || 0);
110:     this.speed = 118 + (s.vel + (passive.vel || 0)) * 3.6 + (eq.speed || 0) * 1.8;
111:     this.crit = clamp(0.05 + (s.luck + (passive.luck || 0)) * 0.006 + (eq.crit || 0) / 100 + this.bonusCrit, 0, 0.85);
112:     this.luck = s.luck + (passive.luck || 0) + (eq.luck || 0);
113:     this.hpRegen = (eq.hpRegen || 0) + (passive.hpRegen || 0);
114:     this.manaRegen = 1 + (eq.manaRegen || 0) + (passive.manaRegen || 0);
115:     this.damageReduction = clamp((eq.damageReduction || 0) + (passive.damageReduction || 0) + this.defense / (this.defense + 180), 0, 0.75);
116:     this.lifesteal = (eq.lifesteal || 0) + (passive.lifesteal || 0);
117:     this.dodgeCdMax = 0.65 * (1 - (passive.dodgeCd || 0));
118:     this.weaponSpeed = WEAPON_TYPES[this.game.inventory?.weaponType()]?.speed || 1;
119:     this.maxHp = Math.max(1, this.maxHp); this.maxMp = Math.max(1, this.maxMp); this.maxStamina = Math.max(1, this.maxStamina);
120:     if (full) { this.hp = Math.min(this.hp, this.maxHp); this.mp = Math.min(this.mp, this.maxMp); this.stamina = Math.min(this.stamina, this.maxStamina); }
121:     this.hp = Math.min(this.hp, this.maxHp);
122:     this.mp = Math.min(this.mp, this.maxMp);
123:     this.stamina = Math.min(this.stamina, this.maxStamina);
124:   }
125: 
126:   hasSkill(id) { return Boolean(this.skills[id]); }
127:   skillBranch() { return this.origin === 'velo' ? 'velo' : this.origin === 'sombra' ? 'resonancia' : 'espada'; }
128: 
129:   unlockSkill(id) {
130:     const all = Object.values(SKILL_TREES).flatMap(t => t.nodes);
131:     const node = all.find(n => n.id === id);
132:     if (!node || this.skills[id] || this.skillPoints < node.cost) return false;
133:     if (node.requires && !this.skills[node.requires]) return false;
134:     this.skillPoints -= node.cost;
135:     this.skills[id] = true;
136:     if (node.ultimate) this.ultType = node.ultimate;
137:     this.game.ui.toast('Habilidad aprendida', node.name, 'skill');
138:     this.game.audio.sfx('levelup');
139:     return true;
140:   }
141: 
142:   allocate(stat) {
143:     if (this.points <= 0 || !(stat in this.baseStats)) return false;
144:     this.points--;
145:     this.baseStats[stat]++;
146:     this.recalc();
147:     return true;
148:   }
149: 
150:   heal(amount) {
151:     const before = this.hp;
152:     this.hp = Math.min(this.maxHp, this.hp + amount);
153:     if (this.hp > before) this.game.particles.number(this.x, this.y - 34, `+${Math.round(this.hp - before)}`, '#8fd18a', 14);
154:   }
155:   restoreMana(amount) {
156:     const before = this.mp;
157:     this.mp = Math.min(this.maxMp, this.mp + amount);
158:     if (this.mp > before) this.game.particles.number(this.x, this.y - 46, `+${Math.round(this.mp - before)}`, '#7fb7ff', 13);
159:   }
160: 
161:   gainXp(amount) {
162:     if (amount <= 0) return;
163:     this.xp += Math.round(amount * this.difficulty.xp);
164:     while (this.xp >= this.xpNext) {
165:       this.xp -= this.xpNext;
166:       this.level++;
167:       this.xpNext = 80 + this.level * 60;
168:       this.points += 2;
169:       this.skillPoints += 1;
170:       this.recalc(true);
171:       this.hp = this.maxHp; this.mp = this.maxMp; this.stamina = this.maxStamina;
172:       this.game.ui.toast('Nivel ' + this.level, 'Has ganado 2 puntos de atributo y 1 de habilidad.', 'level');
173:       this.game.audio.sfx('levelup');
174:       this.game.particles.burst(this.x, this.y - 20, 40, { color: '#ffe7a8', speed: 140, life: 1, size: 3 });
175:       this.game.autosave();
176:     }
177:   }
178: 
179:   addUlt(amount) { this.ult = clamp(this.ult + amount, 0, 100); }
180: 
181:   update(dt, input, world, game) {
182:     this.playtime += dt;
183:     if (this.dead) {
184:       this.deadTime += dt;
185:       this.animTime += dt;
186:       return;
187:     }
188:     // Temporizadores.
189:     this.invuln = Math.max(0, this.invuln - dt);
190:     this.dodgeCd = Math.max(0, this.dodgeCd - dt);
191:     this.potionCd = Math.max(0, this.potionCd - dt);
192:     this.comboTimer = Math.max(0, this.comboTimer - dt);
193:     this.parryCd = Math.max(0, this.parryCd - dt);
194:     this.parryTimer = Math.max(0, this.parryTimer - dt);
195:     this.hurtFlash = Math.max(0, this.hurtFlash - dt);
196:     this.ultActive = Math.max(0, this.ultActive - dt);
197:     this.spellCooldowns = this.spellCooldowns.map(v => Math.max(0, v - dt));
198:     this.companionCooldown = Math.max(0, this.companionCooldown - dt);
199:     this.castTime = Math.max(0, this.castTime - dt);
200:     this.dodgeTime = Math.max(0, this.dodgeTime - dt);
201:     for (const [k, v] of Object.entries(this.status)) {
202:       this.status[k] = v - dt;
203:       if (this.status[k] <= 0) delete this.status[k];
204:     }
205:     if (this.status.burn) this.hp -= 4 * dt;
206:     if (this.hp <= 0) { this.die(); return; }
207: 
208:     // Regeneración.
209:     const outOfCombat = !game.inCombat;
210:     this.stamina = Math.min(this.maxStamina, this.stamina + (outOfCombat ? 24 : 14) * dt);
211:     this.mp = Math.min(this.maxMp, this.mp + this.manaRegen * dt);
212:     if (outOfCombat) this.hp = Math.min(this.maxHp, this.hp + (2 + this.hpRegen) * dt);
213: 
214:     // Apuntado.
215:     const aim = this.getAimAngle(game, input);
216:     if (!this.attacking() && !this.dodging()) this.facing = aim;
217: 
218:     // Movimiento.
219:     const axis = input.axis();
220:     const moveScale = this.blocking ? 0.42 : (this.attacking() ? 0.22 : 1);
221:     let dx = axis.x * this.speed * moveScale * dt;
222:     let dy = axis.y * this.speed * moveScale * dt;
223:     if (this.dodging()) {
224:       const dashSpeed = 430 * (this.hasSkill('veil_step') ? 1.25 : 1);
225:       dx = Math.cos(this.dodgeAngle) * dashSpeed * dt;
226:       dy = Math.sin(this.dodgeAngle) * dashSpeed * dt;
227:     }
228:     if (dx || dy) {
229:       const moved = world.moveCircle(this.x, this.y, dx, dy, this.radius);
230:       this.x = moved.x; this.y = moved.y;
231:       if (!this.attacking() && !this.dodging()) {
232:         this.anim = axis.len > 0.7 ? 'run' : 'walk';
233:         this.stepTimer -= dt;
234:         if (this.stepTimer <= 0) { this.stepTimer = 0.32; game.audio.sfx('step', { volume: 0.35 }); }
235:       }
236:     } else if (!this.attacking() && !this.dodging() && !this.blocking && this.castTime <= 0) {
237:       this.anim = 'idle';
238:     }
239: 
240:     // Acciones.
241:     if (input.justPressed('attack') && !this.attacking() && !this.dodging() && this.castTime <= 0) this.startAttack(false, game);
242:     if (input.justPressed('heavy') && !this.attacking() && !this.dodging() && this.castTime <= 0) this.startAttack(true, game);
243:     if (input.justPressed('dodge') && !this.dodging() && this.dodgeCd <= 0 && this.stamina >= 16) this.startDodge(axis, game);
244:     this.blocking = input.down('block') && !this.attacking() && !this.dodging();
245:     if (input.justPressed('block') && this.parryCd <= 0) { this.parryTimer = this.difficulty.parryWindow; this.parryCd = 0.55; }
246:     if (input.justPressed('interact')) game.interact();
247:     if (input.justPressed('spell1')) { this.selectedSpell = 0; }
248:     if (input.justPressed('spell2')) { this.selectedSpell = 1; }
249:     if (input.justPressed('spell3')) { this.selectedSpell = 2; }
250:     if (input.justPressed('spell')) this.castSelected(game);
251:     if (input.justPressed('companion')) game.useCompanion();
252:     if (input.justPressed('ultimate')) this.useUltimate(game);
253:     if (input.justPressed('potion')) this.usePotion(game);
254: 
255:     // Ataque.
256:     if (this.attackTime > 0) {
257:       this.attackTime -= dt;
258:       this.animTime += dt;
259:       const phase = this.attackPhase;
260:       if (phase === 'active' && this.attackTime <= this.attackActiveEnd && !this.attackDone) {
261:         this.attackDone = true;
262:         this.resolveAttack(game);
263:       }
264:       if (this.attackTime <= 0) {
265:         this.anim = 'idle';
266:         this.attackPhase = null;
267:       }
268:     } else if (this.castTime > 0) {
269:       this.anim = 'cast';
270:     } else if (this.dodging()) {
271:       this.anim = 'dodge';
272:       this.invuln = Math.max(this.invuln, 0.08);
273:       if (Math.random() < 0.5) game.particles.spawn('smoke', this.x, this.y + 8, { color: '#c7a4ff', size: 5, life: 0.35, speed: 10, additive: false });
274:     } else if (this.blocking) {
275:       this.anim = 'block';
276:     }
277: 
278:     // Sombra del Velo (habilidad de esquiva).
279:     if (this.dodging() && this.hasSkill('veil_step') && Math.random() < 0.6) {
280:       game.particles.spawn('smoke', this.x, this.y, { color: '#7d6a9e', size: 4, life: 0.3, speed: 6, additive: false });
281:     }
282:     this.animTime += dt;
283:   }
284: 
285:   getAimAngle(game, input) {
286:     const axis = input.axis();
287:     if (input.touchMode) {
288:       const target = game.nearestEnemy(this.x, this.y, 320);
289:       if (target) return Math.atan2(target.y - this.y, target.x - this.x);
290:       if (axis.len > 0.1) return Math.atan2(axis.y, axis.x);
291:       return this.facing;
292:     }
293:     const w = game.camera.screenToWorld(input.mouse.x, input.mouse.y);
294:     if (game.autoAim && game.nearestEnemy(this.x, this.y, 260)) {
295:       const t = game.nearestEnemy(this.x, this.y, 260);
296:       return Math.atan2(t.y - this.y, t.x - this.x);
297:     }
298:     if (input.mouse.x || input.mouse.y) return Math.atan2(w.y - this.y, w.x - this.x);
299:     if (axis.len > 0.1) return Math.atan2(axis.y, axis.x);
300:     return this.facing;
301:   }
302: 
303:   attacking() { return this.attackTime > 0; }
304:   dodging() { return this.dodgeTime > 0; }
305: 
306:   startAttack(heavy, game) {
307:     if (heavy && this.stamina < 20) { game.ui.toast('Sin resistencia', 'No puedes ejecutar un ataque pesado.', 'warn'); return; }
308:     this.heavy = heavy;
309:     this.attackDone = false;
310:     this.attackHit.clear();
311:     if (heavy) {
312:       this.stamina -= 20;
313:       this.attackDuration = 0.62 / this.weaponSpeed;
314:       this.attackActiveEnd = this.attackDuration * 0.48;
315:       this.attackPhase = 'active';
316:       this.attackTime = this.attackDuration;
317:       this.anim = 'heavy';
318:       game.audio.sfx('heavy');
319:     } else {
320:       if (this.comboTimer > 0) this.attackIndex = (this.attackIndex + 1) % 3;
321:       else this.attackIndex = 0;
322:       this.comboTimer = 0.75;
323:       this.stamina = Math.max(0, this.stamina - 6);
324:       const speed = this.weaponSpeed * (this.hasSkill('blade_rhythm') ? 1.2 : 1);
325:       this.attackDuration = (0.36 + this.attackIndex * 0.05) / speed;
326:       this.attackActiveEnd = this.attackDuration * 0.5;
327:       this.attackPhase = 'active';
328:       this.attackTime = this.attackDuration;
329:       this.anim = 'attack' + this.attackIndex;
330:       game.audio.sfx('attack', { volume: 0.8 });
331:     }
332:     this.animTime = 0;
333:   }
334: 
335:   resolveAttack(game) {
336:     const wt = WEAPON_TYPES[game.inventory.weaponType()] || WEAPON_TYPES.sword;
337:     const range = wt.range + (this.heavy ? 10 : 0);
338:     const arc = wt.arc + (this.heavy ? 0.3 : 0);
339:     const base = (this.attack + (this.heavy ? 8 : 0)) * wt.damage * (this.heavy ? 1.55 : 1);
340:     const crit = Math.random() < this.crit;
341:     const dmg = Math.round(base * (crit ? 1.7 : 1));
342:     const hitAny = [];
343:     for (const e of game.enemies) {
344:       if (e.dead || e.captured) continue;
345:       const d = dist(this.x, this.y, e.x, e.y);
346:       if (d > range + e.radius) continue;
347:       const a = Math.atan2(e.y - this.y, e.x - this.x);
348:       if (Math.abs(angleDiff(this.facing, a)) > arc / 2) continue;
349:       if (this.attackHit.has(e)) continue;
350:       this.attackHit.add(e);
351:       const res = e.takeDamage(dmg, { source: 'player', crit, element: this.heavy ? 'fuego' : null, game });
352:       if (res) {
353:         hitAny.push(e);
354:         if (this.hasSkill('blade_edge') && this.heavy) e.applyStatus('burn', 4, game);
355:         if (this.lifesteal) this.heal(dmg * this.lifesteal);
356:         this.addUlt(crit ? 9 : 6);
357:         game.hitstop = Math.max(game.hitstop, this.heavy ? 0.09 : 0.045);
358:         game.camera.addShake(this.heavy ? 8 : 4);
359:         game.particles.burst(e.x, e.y - 10, this.heavy ? 18 : 10, { color: crit ? '#ffe7a8' : '#ffb86a', speed: 150, life: 0.5, size: 2.6 });
360:         game.particles.number(e.x, e.y - e.radius - 18, `${dmg}${crit ? '!' : ''}`, crit ? '#ffe7a8' : '#fff3d0', crit ? 22 : 16, crit);
361:         game.audio.sfx(crit ? 'crit' : 'hit', { pan: clamp((e.x - this.x) / 300, -1, 1) });
362:       }
363:     }
364:     if (hitAny.length) {
365:       this.damageDealt += dmg * hitAny.length;
366:     } else {
367:       // Golpe al aire: pequeña onda visual.
368:       game.particles.slash(this.x + Math.cos(this.facing) * 18, this.y + Math.sin(this.facing) * 18 - 6, this.facing, { radius: range * 0.7, color: this.heavy ? '#ff9a5c' : '#ffe7a8', arc, width: this.heavy ? 10 : 7 });
369:     }
370:     if (!this.heavy) {
371:       game.particles.slash(this.x + Math.cos(this.facing) * 16, this.y + Math.sin(this.facing) * 16 - 8, this.facing, { radius: range * 0.8, color: this.heavy ? '#ff9a5c' : '#ffe7a8', arc, width: this.heavy ? 11 : 7 });
372:     }
373:   }
374: 
375:   startDodge(axis, game) {
376:     this.stamina -= 16;
377:     this.dodgeTime = 0.3;
378:     this.dodgeCd = this.dodgeCdMax;
379:     this.invuln = 0.24;
380:     this.dodgeAngle = axis.len > 0.1 ? Math.atan2(axis.y, axis.x) : this.facing;
381:     this.anim = 'dodge';
382:     game.audio.sfx('dodge');
383:   }
384: 
385:   castSelected(game) {
386:     const spell = SPELLS[this.selectedSpell];
387:     if (!spell) return;
388:     this.castSpellById(spell.id, game);
389:   }
390: 
391:   castSpellById(id, game) {
392:     const spell = SPELLS.find(s => s.id === id);
393:     if (!spell) return;
394:     const cost = Math.round(spell.cost * (this.origin === 'velo' ? 0.9 : 1));
395:     if (this.mp < cost) { game.ui.toast('Maná insuficiente', spell.name, 'warn'); game.audio.sfx('error'); return; }
396:     if (this.spellCooldowns[SPELLS.indexOf(spell)] > 0) return;
397:     if (this.castTime > 0 || this.attacking() || this.dodging()) return;
398:     this.mp -= cost;
399:     this.spellCooldowns[SPELLS.indexOf(spell)] = spell.cooldown;
400:     this.castTime = 0.25;
401:     this.anim = 'cast';
402:     game.audio.sfx(id === 'rayo' ? 'spell' : id === 'nova' ? 'fire' : 'waypoint');
403:     const aim = this.facing;
404:     if (id === 'rayo') {
405:       game.spawnProjectile({
406:         x: this.x + Math.cos(aim) * 18, y: this.y + Math.sin(aim) * 18 - 8,
407:         vx: Math.cos(aim) * 430, vy: Math.sin(aim) * 430,
408:         radius: 9, damage: Math.round(this.spellPower * (this.game.inventory.weaponType() === 'staff' ? 1.2 : 1)),
409:         color: '#ffe7a8', owner: 'player', life: 1.1, pierce: false, element: 'luz',
410:         onHit: (enemy) => { if (this.hasSkill('veil_mark')) enemy.applyStatus('mark', 6, game); },
411:       });
412:       game.particles.beam(this.x, this.y - 8, aim, { radius: 40, color: '#ffe7a8', width: 5, life: 0.12 });
413:     } else if (id === 'nova') {
414:       game.particles.ring(this.x, this.y, { radius: 20, target: 130, color: '#c7a4ff', width: 8, life: 0.5 });
415:       for (const e of game.enemies) {
416:         if (e.dead) continue;
417:         if (dist(this.x, this.y, e.x, e.y) < 130 + e.radius) {
418:           const dmg = Math.round(this.spellPower * 0.9);
419:           e.takeDamage(dmg, { source: 'player', element: 'luz', game });
420:           e.applyStatus('slow', 2.5, game);
421:           if (this.hasSkill('veil_mark')) e.applyStatus('mark', 6, game);
422:           game.particles.number(e.x, e.y - 20, `${dmg}`, '#c7a4ff', 16);
423:         }
