/* ── Muerte y final ─────────────────────────────────────────────────── */
.death-screen { background: radial-gradient(ellipse at 50% 50%, rgba(90, 20, 24, 0.32), rgba(4, 3, 8, 0.96)); align-items: center; justify-content: center; text-align: center; }
.death-content { max-width: 540px; padding: 24px; animation: fadeIn 0.8s ease both; }
.death-content h2 { font-size: clamp(38px, 7vw, 74px); color: #ffb3b3; letter-spacing: 0.18em; text-shadow: 0 0 50px rgba(255, 70, 70, 0.3); }
.death-content p { color: var(--muted); font-size: 17px; font-style: italic; margin: 16px 0 28px; }
.death-actions { display: flex; flex-direction: column; gap: 9px; align-items: center; }
.ending-screen {
  background:
    radial-gradient(ellipse at 50% 20%, rgba(80, 60, 110, 0.3), transparent 60%),
    linear-gradient(180deg, rgba(6, 4, 12, 0.97), rgba(10, 7, 18, 0.99));
  overflow-y: auto;
  align-items: center;
  justify-content: flex-start;
  padding: calc(30px + var(--safe-top)) 18px calc(30px + var(--safe-bottom));
}
.ending-content { max-width: 760px; text-align: center; animation: fadeIn 1.4s ease both; }
.ending-content h2 { font-size: clamp(34px, 6vw, 72px); letter-spacing: 0.14em; margin: 4px 0; }
.ending-content > p:first-of-type { color: var(--gold); }
#ending-subtitle { color: var(--muted); font-style: italic; font-size: 18px; margin: 6px 0 26px; }
.ending-lines { display: flex; flex-direction: column; gap: 16px; text-align: left; margin: 0 auto 24px; }
.ending-lines p { margin: 0; font-size: 17px; line-height: 1.6; color: #d8cdbd; opacity: 0; animation: fadeUp 1s ease forwards; }
.ending-epilogue { font-family: var(--font-display); font-size: 13px; letter-spacing: 0.16em; color: var(--gold-bright); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 14px; margin: 24px 0; }
.ending-stats { display: flex; justify-content: center; gap: 24px; flex-wrap: wrap; margin-bottom: 24px; }
.ending-stats div { text-align: center; }
.ending-stats strong { display: block; font-size: 22px; color: var(--gold-bright); }
.ending-stats span { font-size: 10px; color: var(--muted); letter-spacing: 0.14em; text-transform: uppercase; }
.ending-actions { display: flex; justify-content: center; }

/* ── Toasts ─────────────────────────────────────────────────────────── */
.toasts {
  position: absolute;
  top: calc(90px + var(--safe-top));
  right: calc(18px + var(--safe-right));
  z-index: 45;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
  width: min(330px, 78vw);
}
.toast {
  padding: 10px 13px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--gold);
  background: linear-gradient(90deg, rgba(18, 13, 28, 0.96), rgba(10, 8, 18, 0.92));
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.45);
  animation: toastIn 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  backdrop-filter: blur(6px);
}
.toast.out { animation: toastOut 0.35s ease forwards; }
.toast strong { display: block; font-family: var(--font-display); font-size: 10px; letter-spacing: 0.12em; color: var(--gold-bright); text-transform: uppercase; }
.toast span { display: block; margin-top: 2px; font-size: 13px; line-height: 1.3; color: var(--muted); }
.toast.quest { border-left-color: var(--cyan); }
.toast.quest strong { color: var(--cyan); }
.toast.complete { border-left-color: var(--green); }
.toast.complete strong { color: var(--green); }
.toast.level, .toast.skill, .toast.ult { border-left-color: var(--violet); }
.toast.level strong, .toast.skill strong, .toast.ult strong { color: var(--violet); }
.toast.boss { border-left-color: #ff7b4d; }
.toast.boss strong { color: #ff9a5c; }
.toast.creature { border-left-color: var(--green); }
.toast.creature strong { color: var(--green); }
.toast.warn { border-left-color: var(--red); }
.toast.warn strong { color: var(--red); }
.toast.loot { border-left-color: var(--gold); }

/* ── Carga / fatal ──────────────────────────────────────────────────── */
.loading {
  position: absolute; inset: 0; z-index: 60;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px;
  background: rgba(6, 4, 12, 0.92);
  backdrop-filter: blur(5px);
}
.loading-rune { font-size: 34px; color: var(--gold); animation: pulse 1.4s infinite; }
.loading p { margin: 0; font-family: var(--font-display); font-size: 12px; letter-spacing: 0.22em; color: var(--muted); text-transform: uppercase; }
.fatal {
  position: absolute; inset: 0; z-index: 100;
  display: flex; align-items: center; justify-content: center;
  padding: 30px; background: #0a0812; color: #ffb3b3;
  font-family: monospace; font-size: 13px; white-space: pre-wrap; overflow: auto;
}

/* ── Animaciones ────────────────────────────────────────────────────── */
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes fadeUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes fadeDown { from { opacity: 0; transform: translateY(-10px); } to { opacity: 1; transform: translateY(0); } }
@keyframes titleIn { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
@keyframes dialogueIn { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toastIn { from { opacity: 0; transform: translateX(24px); } to { opacity: 1; transform: translateX(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(24px); } }
@keyframes pulse { 0%, 100% { opacity: 0.6; } 50% { opacity: 1; } }
@keyframes bounce { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }
@keyframes rotateHint { 0%, 100% { transform: rotate(0deg); } 50% { transform: rotate(90deg); } }
@keyframes ultPulse { 0%, 100% { box-shadow: 0 0 0 rgba(255, 231, 168, 0); } 50% { box-shadow: 0 0 26px rgba(255, 231, 168, 0.55); } }

/* ── Responsive ─────────────────────────────────────────────────────── */
@media (max-width: 980px) {
  .hud-top { grid-template-columns: minmax(220px, 300px) 1fr minmax(180px, 230px); gap: 10px; }
  .hud-vitals { padding: 8px; }
  .portrait-frame { width: 52px; height: 52px; }
  .vitals-name em { display: none; }
  .hud-map { padding: 6px; }
  .creator-layout { grid-template-columns: 250px minmax(0, 1fr); }
  .stat-grid { grid-template-columns: repeat(4, 1fr); }
}

@media (max-width: 760px) {
  .hud-top { grid-template-columns: minmax(0, 1fr) auto; }
  .hud-center { position: absolute; top: calc(72px + var(--safe-top)); left: 50%; transform: translateX(-50%); width: min(88vw, 520px); }
  .hud-map { display: none; }
  .hud-vitals { max-width: 62vw; }
  .boss-bar { width: 100%; }
  .hud-menu-buttons { bottom: calc(80px + var(--safe-bottom)); }
