391:   castSpellById(id, game) {
392:     const spell = SPELLS.find(s => s.id === id);
393:     if (!spell) return;
394:     const cost = Math.round(spell.cost * (this.origin === 'velo' ? 0.9 : 1));
395:     if (this.mp < cost) { game.ui.toast('Maná insuficiente', spell.name, 'warn'); game.audio.sfx('error'); return; }
396:     if (this.spellCooldowns[SPELLS.indexOf(spell)] > 0) return;
397:     if (this.castTime > 0 || this.attacking() || this.dodging()) return;
398:     this.mp -= cost;
399:     this.spellCooldowns[SPELLS.indexOf(spell)] = spell.cooldown;
400:     this.castTime = 0.25;
401:     this.anim = 'cast';
402:     game.audio.sfx(id === 'rayo' ? 'spell' : id === 'nova' ? 'fire' : 'waypoint');
403:     const aim = this.facing;
404:     if (id === 'rayo') {
405:       game.spawnProjectile({
406:         x: this.x + Math.cos(aim) * 18, y: this.y + Math.sin(aim) * 18 - 8,
407:         vx: Math.cos(aim) * 430, vy: Math.sin(aim) * 430,
408:         radius: 9, damage: Math.round(this.spellPower * (this.game.inventory.weaponType() === 'staff' ? 1.2 : 1)),
409:         color: '#ffe7a8', owner: 'player', life: 1.1, pierce: false, element: 'luz',
410:         onHit: (enemy) => { if (this.hasSkill('veil_mark')) enemy.applyStatus('mark', 6, game); },
411:       });
412:       game.particles.beam(this.x, this.y - 8, aim, { radius: 40, color: '#ffe7a8', width: 5, life: 0.12 });
413:     } else if (id === 'nova') {
414:       game.particles.ring(this.x, this.y, { radius: 20, target: 130, color: '#c7a4ff', width: 8, life: 0.5 });
415:       for (const e of game.enemies) {
416:         if (e.dead) continue;
417:         if (dist(this.x, this.y, e.x, e.y) < 130 + e.radius) {
418:           const dmg = Math.round(this.spellPower * 0.9);
419:           e.takeDamage(dmg, { source: 'player', element: 'luz', game });
420:           e.applyStatus('slow', 2.5, game);
421:           if (this.hasSkill('veil_mark')) e.applyStatus('mark', 6, game);
422:           game.particles.number(e.x, e.y - 20, `${dmg}`, '#c7a4ff', 16);
423:         }
424:       }
425:       game.camera.addShake(9);
426:       this.addUlt(10);
427:     } else if (id === 'barrera') {
428:       this.status.shield = 7;
429:       this.shieldAmount = Math.round(this.maxHp * 0.25);
430:       this.heal(Math.round(this.maxHp * 0.12));
431:       game.particles.ring(this.x, this.y, { radius: 10, target: 42, color: '#9fe8ff', width: 4, life: 0.6 });
432:       game.particles.burst(this.x, this.y - 10, 22, { color: '#9fe8ff', speed: 70, life: 0.8, size: 2.5 });
433:     }
434:   }
