456:             }
457:           }
458:         }, i * 180);
459:       }
460:       game.ui.toast('TORMENTA CELESTIAL', 'El acero recuerda su nombre.', 'ult');
461:     } else if (this.ultType === 'veil') {
462:       game.particles.ring(this.x, this.y, { radius: 20, target: 260, color: '#c7a4ff', width: 10, life: 0.8 });
463:       for (const e of game.enemies) {
464:         if (e.dead) continue;
465:         if (dist(this.x, this.y, e.x, e.y) < 260 + e.radius) {
466:           e.applyStatus('freeze', 4, game);
467:           const dmg = Math.round(this.spellPower * 1.8);
468:           e.takeDamage(dmg, { source: 'player', element: 'luz', game });
469:           game.particles.number(e.x, e.y - 22, `${dmg}`, '#c7a4ff', 22, true);
470:         }
471:       }
472:       this.mp = this.maxMp;
473:       game.ui.toast('NOVA DEL VELO', 'El silencio se vuelve forma.', 'ult');
474:     } else {
475:       this.heal(Math.round(this.maxHp * 0.5));
476:       game.summonAllCompanions();
477:       game.ui.toast('DESPERTAR', 'Todas tus resonancias responden.', 'ult');
