481:   usePotion(game) {
482:     if (this.potionCd > 0) return;
483:     if (!game.inventory.has('potion_lumen')) { game.ui.toast('Sin pociones', 'No te queda Poción de Lumen.', 'warn'); return; }
484:     this.potionCd = 3.2;
485:     game.inventory.remove('potion_lumen', 1);
486:     this.heal(Math.round(this.maxHp * 0.45 * this.difficulty.potion));
487:     game.audio.sfx('potion');
488:     game.particles.burst(this.x, this.y - 10, 16, { color: '#ff7b7b', speed: 50, life: 0.7, size: 2.5 });
489:   }
490: 
491:   takeDamage(amount, { source = 'enemy', element = null, game = this.game, ignoreBlock = false } = {}) {
492:     if (this.dead || this.invuln > 0 || this.dodging()) return 0;
493:     if (this.parryTimer > 0 && !ignoreBlock) {
494:       this.parryTimer = 0;
495:       this.mp = Math.min(this.maxMp, this.mp + 15);
496:       this.addUlt(12);
497:       game.audio.sfx('parry');
498:       game.hitstop = 0.12;
499:       game.camera.addShake(7);
500:       game.particles.ring(this.x, this.y, { radius: 12, target: 70, color: '#ffe7a8', width: 5, life: 0.4 });
501:       if (this.hasSkill('blade_guard')) {
502:         for (const e of game.enemies) {
503:           if (!e.dead && dist(this.x, this.y, e.x, e.y) < 120) {
504:             e.stagger(1.6, game);
505:             e.takeDamage(Math.round(this.attack * 0.8), { source: 'player', game });
506:           }
507:         }
508:       }
509:       return 0;
510:     }
511:     let dmg = amount * (1 - this.damageReduction);
512:     if (this.blocking) {
513:       const staminaCost = dmg * 0.9;
514:       if (this.stamina >= staminaCost) {
515:         this.stamina -= staminaCost;
516:         dmg *= 0.25;
517:         game.particles.burst(this.x, this.y - 10, 6, { color: '#9fe8ff', speed: 70, life: 0.35, size: 2 });
518:       } else {
519:         this.stamina = 0;
520:         this.blocking = false;
521:         game.ui.toast('Guardia rota', 'La resistencia se ha agotado.', 'warn');
522:       }
523:     }
524:     if (this.status.shield > 0 && this.shieldAmount > 0) {
525:       const absorbed = Math.min(this.shieldAmount, dmg);
526:       this.shieldAmount -= absorbed;
527:       dmg -= absorbed;
528:       if (this.shieldAmount <= 0) delete this.status.shield;
529:     }
530:     dmg = Math.max(1, Math.round(dmg));
531:     this.hp -= dmg;
532:     this.damageTaken += dmg;
533:     this.addUlt(3);
534:     this.invuln = 0.55;
535:     this.hurtFlash = 0.25;
536:     game.camera.addShake(6);
