405:   syncHud(dt = 0, force = false) {
406:     const game = this.game;
407:     const p = game.player;
408:     if (!p) return;
409:     this.hudTimer -= dt;
410:     if (!force && this.hudTimer > 0) return;
411:     this.hudTimer = 0.075;
412: 
413:     const setBar = (id, txt, value, max, label) => {
414:       const bar = $(id);
415:       if (bar) bar.style.width = `${clamp(value / Math.max(1, max), 0, 1) * 100}%`;
416:       const t = $(txt);
417:       if (t) t.textContent = label || `${Math.ceil(value)} / ${Math.round(max)}`;
418:     };
419:     setBar('bar-hp', 'txt-hp', p.hp, p.maxHp);
420:     setBar('bar-mp', 'txt-mp', p.mp, p.maxMp);
421:     setBar('bar-st', 'txt-st', p.stamina, p.maxStamina);
422:     const name = $('hud-name');
423:     if (name) name.textContent = p.name;
424:     const origin = $('hud-origin');
425:     if (origin) origin.textContent = ORIGINS[p.origin]?.name || 'Peregrino';
426:     const level = $('hud-level');
427:     if (level) level.textContent = p.level;
428:     const gold = $('hud-gold');
429:     if (gold) gold.textContent = `◈ ${p.gold}`;
430:     const ult = $('hud-ult');
431:     if (ult) ult.textContent = `ULT ${Math.round(p.ult)}%`;
432:     const region = REGIONS[game.regionId] || REGIONS.valdoria;
433:     const regionName = $('region-name');
434:     if (regionName) regionName.textContent = region.name;
435:     const regionLevel = $('region-level');
436:     if (regionLevel) regionLevel.textContent = `Nv. ${region.level}`;
437: 
438:     const boss = game.bosses.find((b) => !b.dead) || game.activeBoss;
439:     const bossBar = $('boss-bar');
440:     if (bossBar) bossBar.classList.toggle('hidden', !boss);
441:     if (boss) {
442:       const bn = $('boss-name');
443:       if (bn) bn.textContent = boss.name;
444:       const bp = $('boss-phase');
445:       if (bp) bp.textContent = `FASE ${boss.phase + 1} / ${boss.phaseCount}`;
446:       const bb = $('bar-boss');
447:       if (bb) bb.style.width = `${boss.hpRatio * 100}%`;
448:     }
449: 
450:     const tracked = game.quests?.trackedObjective();
451:     const qTitle = $('quest-title');
452:     const qObj = $('quest-objective');
453:     const qProg = $('quest-progress');
454:     if (tracked) {
455:       if (qTitle) qTitle.textContent = tracked.def.title;
456:       if (qObj) qObj.textContent = tracked.objective.label || tracked.stage.text;
457:       if (qProg) {
458:         const need = tracked.need || 1;
459:         qProg.textContent = need > 1 ? `${tracked.progress} / ${need}` : '';
460:       }
461:     } else {
462:       if (qTitle) qTitle.textContent = 'Sin misión activa';
463:       if (qObj) qObj.textContent = 'Explora, habla y escucha los ecos.';
464:       if (qProg) qProg.textContent = '';
465:     }
466: 
467:     const comp = game.companions.find((c) => !c.temp && !c.dead);
468:     const chip = $('companion-chip');
469:     if (chip) chip.classList.toggle('hidden', !comp);
470:     if (comp) {
471:       const cn = $('companion-name');
472:       if (cn) cn.textContent = creatureName(comp.id, comp.entry.bond);
473:       const cd = $('companion-cd');
474:       if (cd) cd.textContent = comp.abilityCd <= 0 ? 'Eco listo' : `Recarga ${comp.abilityCd.toFixed(1)} s`;
475:     }
