549:   updateDialogue(dt) {
550:     const d = this.dialog;
551:     if (!d) return;
552:     const beat = d.script.beats[d.index];
553:     if (!beat || d.complete) return;
554:     const speed = 46 * (this.game.settings.textSpeed || 1);
555:     d.shown += dt * speed;
556:     const text = beat.text || '';
557:     const count = Math.min(text.length, Math.floor(d.shown));
558:     if (this.el.dialogueText.textContent.length !== count) {
559:       this.el.dialogueText.textContent = text.slice(0, count);
560:     }
561:     if (count >= text.length) this.completeDialogueText();
562:   }
