564:   completeDialogueText() {
565:     const d = this.dialog;
566:     if (!d) return;
567:     const beat = d.script.beats[d.index];
568:     if (!beat) return;
569:     this.el.dialogueText.textContent = beat.text || '';
570:     d.complete = true;
571:     if (beat.choices?.length) {
572:       this.el.dialogueNext.classList.add('hidden');
573:       this.el.dialogueChoices.classList.remove('hidden');
574:       this.el.dialogueChoices.innerHTML = beat.choices.map((c, i) =>
575:         `<button class="choice-btn" data-choice="${i}" type="button">${esc(c.text)}</button>`).join('');
576:     } else {
577:       this.el.dialogueNext.classList.remove('hidden');
578:     }
579:   }
