581:   advanceDialogue() {
582:     const d = this.dialog;
583:     if (!d) return;
584:     const beat = d.script.beats[d.index];
585:     if (!beat) { this.finishDialogue(); return; }
586:     if (!d.complete) { this.completeDialogueText(); return; }
587:     if (beat.choices?.length) return;
588:     d.index++;
589:     if (d.index >= d.script.beats.length) this.finishDialogue();
590:     else this.renderDialogueBeat();
591:   }
