593:   choose(index) {
594:     const d = this.dialog;
595:     if (!d) return;
596:     const beat = d.script.beats[d.index];
597:     const choice = beat?.choices?.[index];
598:     if (!choice) return;
599:     this.game.audio.sfx('ui');
600:     let result = null;
601:     for (const action of choice.actions || []) {
602:       const r = d.onAction?.(action);
603:       if (r) result = r;
604:     }
605:     if (result === 'ending') {
606:       const endingId = this.game.pendingEnding;
607:       this.finishDialogue();
608:       if (endingId) this.game.showEnding(endingId);
609:       return;
610:     }
611:     if (choice.next && choice.next !== 'end') {
612:       const next = choice.next;
613:       this.runScriptEnd();
614:       this.openDialogue(next, {
615:         context: d.context,
616:         onAction: d.onAction,
617:         onScriptEnd: d.onScriptEnd,
618:         onClosed: d.onClosed,
619:       });
620:     } else {
621:       this.finishDialogue();
622:     }
623:   }
624: 
625:   runScriptEnd() {
626:     const d = this.dialog;
627:     if (!d || d.ended) return;
628:     d.ended = true;
629:     d.onScriptEnd?.(d.scriptId, d.context);
630:   }
