834:     const slotLabels = { weapon: 'Arma', armor: 'Armadura', helmet: 'Yelmo', accessory: 'Accesorio' };
835:     const equipHtml = Object.entries(slotLabels).map(([slot, label]) => {
836:       const id = inv.equipment[slot];
837:       const item = id ? ITEMS[id] : null;
838:       const lvl = id ? inv.upgradeLevel(id) : 0;
839:       return `<div class="equip-slot">
840:         <span class="item-icon">${item ? itemIcon(item) : '·'}</span>
841:         <div style="flex:1;min-width:0">
842:           <span class="slot-label">${label}</span>
843:           <strong>${item ? esc(item.name) + (lvl ? ` +${lvl}` : '') : 'Vacío'}</strong>
844:         </div>
845:         ${id && (slot === 'helmet' || slot === 'accessory') ? `<button class="mini-btn" data-action="unequip" data-slot="${slot}" type="button">QUITAR</button>` : ''}
846:       </div>`;
847:     }).join('');
848: 
849:     const stats = inv.equipmentStats();
850:     const statHtml = `<div class="stat-summary">
851:       <div class="stat-pill"><span>VIDA</span><strong>${p.maxHp}</strong></div>
852:       <div class="stat-pill"><span>MANÁ</span><strong>${p.maxMp}</strong></div>
853:       <div class="stat-pill"><span>ATAQUE</span><strong>${Math.round(p.attack)}</strong></div>
854:       <div class="stat-pill"><span>DEFENSA</span><strong>${Math.round(p.defense)}</strong></div>
855:       <div class="stat-pill"><span>CRÍTICO</span><strong>${pct(p.crit)}</strong></div>
856:       <div class="stat-pill"><span>VELOCIDAD</span><strong>${Math.round(p.speed)}</strong></div>
857:       <div class="stat-pill"><span>SUERTE</span><strong>${Math.round(p.luck)}</strong></div>
858:       <div class="stat-pill"><span>PUNTOS</span><strong>${p.points}</strong></div>
859:     </div>`;
860: 
861:     const entries = Object.entries(inv.items).filter(([, qty]) => qty > 0)
