27:     default: return palette.ground;
28:   }
29: }
30: 
31: export class Renderer {
32:   constructor(canvas, game) {
33:     this.canvas = canvas;
34:     this.ctx = canvas.getContext('2d', { alpha: false });
35:     this.game = game;
36:     this.width = 1280;
37:     this.height = 720;
38:     this.dpr = 1;
39:     this.terrain = null;
40:     this.terrainId = null;
41:     this.minimap = null;
42:     this.minimapId = null;
43:     this.titleStars = null;
44:   }
45: 
46:   resize(w, h, dpr = 1) {
47:     this.width = Math.max(320, w);
48:     this.height = Math.max(240, h);
49:     this.dpr = clamp(dpr, 1, 2);
50:     this.canvas.width = Math.round(this.width * this.dpr);
51:     this.canvas.height = Math.round(this.height * this.dpr);
52:     this.canvas.style.width = this.width + 'px';
53:     this.canvas.style.height = this.height + 'px';
54:     this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
55:     this.ctx.imageSmoothingEnabled = true;
56:     this.titleStars = null;
57:   }
58: 
59:   setWorld(world) {
60:     this.terrain = null;
61:     this.terrainId = null;
62:     this.minimap = null;
63:     this.minimapId = null;
64:     if (!world) return;
65:     this.buildTerrain(world);
66:     this.buildMinimap(world);
67:   }
68: 
69:   buildTerrain(world) {
70:     const c = makeCanvas(world.pixelWidth, world.pixelHeight);
71:     const ctx = c.getContext('2d');
72:     ctx.fillStyle = REGIONS[world.id]?.palette?.ground || '#4a3a35';
73:     ctx.fillRect(0, 0, c.width, c.height);
74:     for (let y = 0; y < world.height; y++) {
75:       for (let x = 0; x < world.width; x++) {
76:         drawTerrainTile(ctx, x * TILE, y * TILE, world.tileAtTile(x, y), world.id, world.seed, x, y);
77:       }
78:     }
79:     // Vetas de camino: pequeños bordes claros para dar profundidad.
80:     this.terrain = c;
81:     this.terrainId = world.id;
82:   }
83: 
84:   buildMinimap(world) {
85:     const c = makeCanvas(world.width * 2, world.height * 2);
86:     const ctx = c.getContext('2d');
87:     const palette = REGIONS[world.id]?.palette || REGIONS.valdoria.palette;
88:     for (let y = 0; y < world.height; y++) {
89:       for (let x = 0; x < world.width; x++) {
90:         ctx.fillStyle = minimapColor(world.tileAtTile(x, y), palette);
91:         ctx.fillRect(x * 2, y * 2, 2, 2);
92:       }
93:     }
94:     this.minimap = c;
95:     this.minimapId = world.id;
96:   }
97: 
98:   render(time) {
99:     const { ctx } = this;
100:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
101:     if (this.game.state === 'title' || this.game.state === 'creator') {
102:       this.drawTitle(time);
103:       return;
104:     }
105:     this.drawWorld(time);
106:   }
107: 
108:   drawWorld(time) {
109:     const { ctx, game } = this;
110:     const world = game.world;
111:     if (!world) { this.drawTitle(time); return; }
112:     if (this.terrainId !== world.id || !this.terrain) this.setWorld(world);
113:     const region = REGIONS[game.regionId] || REGIONS.valdoria;
114:     const cam = game.camera;
115: 
116:     ctx.fillStyle = region.palette.fog || '#16101f';
117:     ctx.fillRect(0, 0, this.width, this.height);
118:     ctx.save();
119:     cam.apply(ctx);
120: 
121:     if (this.terrain) {
122:       ctx.drawImage(this.terrain, 0, 0);
123:     }
124: 
125:     // Zonas de peligro bajo todo lo demás.
126:     for (const z of game.zones) z.draw(ctx);
127: 
128:     // Marcadores de punto de guardado.
129:     for (const wp of world.waypoints) {
130:       const active = game.flags['waypoint:' + wp.id];
131:       const bob = Math.sin(time * 1.8 + wp.x) * 3;
132:       glowCircle(ctx, wp.x * TILE, wp.y * TILE - 18, active ? 46 : 26, active ? '#9fe8ff' : '#ffe7a8', active ? 0.22 : 0.12);
133:       ctx.strokeStyle = active ? 'rgba(159,232,255,0.75)' : 'rgba(255,231,168,0.55)';
134:       ctx.lineWidth = 2;
135:       ctx.beginPath();
136:       ctx.arc(wp.x * TILE, wp.y * TILE - 6, 16, Math.PI, TAU);
137:       ctx.stroke();
138:       star(ctx, wp.x * TILE, wp.y * TILE - 28 + bob, 5, active ? '#9fe8ff' : '#ffe7a8', 4, time * 0.6);
139:     }
140: 
141:     // Recolectar todo lo dibujable y ordenarlo por profundidad.
142:     const drawables = [];
143:     for (const p of world.props) {
144:       if (!cam.isVisible(p.x, p.y, 180)) continue;
145:       drawables.push({ y: p.y + (p.canopy ? 8 : 0), kind: 'prop', ref: p });
146:     }
147:     for (const it of world.interactables) {
148:       if (!cam.isVisible(it.x, it.y, 120)) continue;
149:       if (it.type === 'survivor') continue;
150:       drawables.push({ y: it.y, kind: 'interactable', ref: it });
151:     }
152:     for (const npc of game.npcs) {
153:       if (!cam.isVisible(npc.x, npc.y, 100)) continue;
154:       drawables.push({ y: npc.y, kind: 'npc', ref: npc });
155:     }
156:     for (const e of game.enemies) {
157:       if (!cam.isVisible(e.x, e.y, 100)) continue;
158:       drawables.push({ y: e.y, kind: 'enemy', ref: e });
159:     }
160:     for (const b of game.bosses) {
161:       if (!cam.isVisible(b.x, b.y, 160)) continue;
162:       drawables.push({ y: b.y, kind: 'boss', ref: b });
163:     }
164:     for (const c of game.companions) {
165:       if (!cam.isVisible(c.x, c.y, 80)) continue;
166:       drawables.push({ y: c.y, kind: 'companion', ref: c });
167:     }
168:     if (!game.player.dead || game.player.deadTime < 6) {
169:       drawables.push({ y: game.player.y, kind: 'player', ref: game.player });
170:     }
171:     drawables.sort((a, b) => a.y - b.y);
172: 
173:     for (const d of drawables) {
174:       switch (d.kind) {
175:         case 'prop':
176:           drawProp(ctx, d.ref, world.id, time);
177:           break;
178:         case 'interactable': {
179:           const it = d.ref;
180:           const state = game.interactableState(it);
181:           if (it.type === 'gate') {
182:             drawInteractable(ctx, it, state, time);
183:           } else if (it.type === 'bossdoor') {
184:             drawInteractable(ctx, it, { active: state.active }, time);
185:           } else {
186:             drawInteractable(ctx, it, state, time);
187:           }
188:           if (state.highlight) {
189:             glowCircle(ctx, it.x, it.y - 18, 36, '#ffe7a8', 0.2);
190:             star(ctx, it.x, it.y - 58 + Math.sin(time * 2) * 3, 5, '#fff3c4', 4, time);
191:           }
192:           break;
193:         }
194:         case 'npc': {
195:           drawNpc(ctx, d.ref, time);
196:           const isNear = game.nearNpc === d.ref;
197:           if (isNear) {
198:             star(ctx, d.ref.x, d.ref.y - 72 + Math.sin(time * 2.4) * 3, 4, '#ffe7a8', 4, time * 0.4);
199:           }
200:           break;
201:         }
202:         case 'enemy': {
203:           drawEnemy(ctx, d.ref, time);
204:           if (!d.ref.dead) {
205:             d.ref.drawHealthBar(ctx);
206:             if (game.canCapture(d.ref)) {
207:               const pulse = 0.55 + Math.sin(time * 4) * 0.2;
208:               ctx.save();
209:               ctx.strokeStyle = `rgba(199,164,255,${pulse})`;
210:               ctx.lineWidth = 1.5;
211:               ctx.setLineDash([4, 4]);
212:               ctx.beginPath();
213:               ctx.arc(d.ref.x, d.ref.y - 8, d.ref.radius + 10, 0, TAU);
214:               ctx.stroke();
215:               ctx.restore();
216:             }
217:           }
218:           break;
219:         }
220:         case 'boss':
221:           drawBoss(ctx, d.ref, time);
222:           break;
223:         case 'companion':
224:           drawCompanion(ctx, d.ref, time);
225:           d.ref.drawHealthRing(ctx);
226:           break;
227:         case 'player':
228:           drawPlayer(ctx, d.ref, time);
229:           break;
230:       }
231:     }
232: 
233:     for (const p of game.projectiles) p.draw(ctx);
234:     game.particles.draw(ctx);
235: 
236:     // Partículas ambientales en coordenadas de mundo.
237:     this.drawWeatherWorld(time);
238: 
239:     ctx.restore();
240: 
241:     this.drawLighting(time);
242:     this.drawScreenWeather(time);
243:     if (game.settings.showFps) this.drawFps(time);
244:   }
245: 
246:   drawWeatherWorld(time) {
247:     const { ctx, game } = this;
248:     const weather = REGIONS[game.regionId]?.weather || 'motes';
249:     const cfg = WEATHER[weather] || WEATHER.motes;
250:     const cam = game.camera;
251:     const halfW = this.width / (2 * cam.zoom), halfH = this.height / (2 * cam.zoom);
252:     const left = cam.x - halfW, top = cam.y - halfH;
253:     ctx.save();
254:     for (const a of game.world.ambient) {
255:       const wx = left + ((a.x * this.width + time * a.speed * 38) % (this.width + 120));
256:       const wy = top + ((a.y * this.height + Math.sin(time * a.speed * 6 + a.phase) * 26 + time * (weather === 'embers' ? -12 : 8)) % (this.height + 80));
257:       ctx.globalAlpha = 0.25 + Math.sin(time + a.phase) * 0.12;
258:       ctx.fillStyle = cfg.color;
259:       if (weather === 'leaves') {
260:         ctx.save();
261:         ctx.translate(wx, wy);
262:         ctx.rotate(time * 0.7 + a.phase);
263:         ctx.beginPath(); ctx.ellipse(0, 0, a.size * 2.2, a.size, 0, 0, TAU); ctx.fill();
264:         ctx.restore();
265:       } else {
266:         ctx.beginPath(); ctx.arc(wx, wy, a.size, 0, TAU); ctx.fill();
267:         if (weather === 'embers') {
268:           ctx.globalAlpha *= 0.3;
269:           ctx.beginPath(); ctx.arc(wx, wy, a.size * 3.4, 0, TAU); ctx.fill();
270:         }
271:       }
272:     }
273:     ctx.restore();
274:   }
275: 
276:   drawLighting(time) {
277:     const { ctx, game } = this;
278:     const p = game.player;
279:     const screen = game.camera.worldToScreen(p.x, p.y - 18);
280:     const region = REGIONS[game.regionId] || REGIONS.valdoria;
281:     const darkness = game.regionId === 'drakmor' ? 0.56 : game.regionId === 'kansordore' ? 0.42 : 0.3;
282:     const radius = Math.max(this.width, this.height) * (game.regionId === 'drakmor' ? 0.58 : 0.66);
283:     const g = ctx.createRadialGradient(screen.x, screen.y, 30, screen.x, screen.y, radius);
284:     g.addColorStop(0, 'rgba(4,3,10,0)');
285:     g.addColorStop(0.42, `rgba(4,3,10,${darkness * 0.22})`);
286:     g.addColorStop(0.78, `rgba(4,3,10,${darkness * 0.62})`);
287:     g.addColorStop(1, `rgba(4,3,10,${darkness})`);
288:     ctx.save();
289:     ctx.fillStyle = g;
290:     ctx.fillRect(0, 0, this.width, this.height);
291: 
292:     // Vignette cinematográfico.
293:     const v = ctx.createRadialGradient(this.width / 2, this.height / 2, Math.min(this.width, this.height) * 0.32, this.width / 2, this.height / 2, Math.max(this.width, this.height) * 0.78);
294:     v.addColorStop(0, 'rgba(0,0,0,0)');
295:     v.addColorStop(1, 'rgba(0,0,0,0.42)');
296:     ctx.fillStyle = v;
297:     ctx.fillRect(0, 0, this.width, this.height);
298: 
299:     // Tinte de la región en los bordes.
300:     const tint = region.palette.ambient || 'rgba(18,32,26,0.3)';
301:     ctx.globalAlpha = 0.35;
302:     ctx.fillStyle = tint;
303:     ctx.fillRect(0, 0, this.width, this.height);
304:     ctx.restore();
305:   }
306: 
307:   drawScreenWeather(time) {
308:     const { ctx, game } = this;
309:     if (game.regionId !== 'kansordore') return;
310:     ctx.save();
311:     ctx.globalCompositeOperation = 'lighter';
312:     for (let i = 0; i < 14; i++) {
313:       const x = ((i * 173 + time * 7) % (this.width + 80)) - 40;
314:       const y = ((i * 91 + Math.sin(time * 0.3 + i) * 30) % (this.height + 60)) - 30;
315:       ctx.globalAlpha = 0.08 + (i % 3) * 0.03;
316:       ctx.fillStyle = '#ffe7a8';
317:       ctx.beginPath(); ctx.arc(x, y, 2 + (i % 2), 0, TAU); ctx.fill();
318:     }
319:     ctx.restore();
320:   }
321: 
322:   drawFps(time) {
323:     const { ctx } = this;
324:     ctx.save();
325:     ctx.font = '12px monospace';
326:     ctx.fillStyle = 'rgba(255,255,255,0.65)';
327:     ctx.fillText(`FPS ${Math.round(this.game.fps || 0)}`, 12, this.height - 14);
328:     ctx.restore();
329:   }
330: 
331:   drawTitle(time) {
332:     const { ctx, w, h } = { ctx: this.ctx, w: this.width, h: this.height };
333:     const t = time;
334:     const sky = ctx.createLinearGradient(0, 0, 0, h);
335:     sky.addColorStop(0, '#0a0814');
336:     sky.addColorStop(0.35, '#1a1430');
337:     sky.addColorStop(0.66, '#4a2a3a');
338:     sky.addColorStop(1, '#0c0812');
339:     ctx.fillStyle = sky;
340:     ctx.fillRect(0, 0, w, h);
341: 
342:     if (!this.titleStars || this.titleStars.w !== w || this.titleStars.h !== h) {
343:       const rng = mulberry32(7719);
344:       this.titleStars = {
345:         w, h,
346:         stars: Array.from({ length: 150 }, () => ({ x: rng() * w, y: rng() * h * 0.7, r: rng() * 1.7 + 0.3, p: rng() * TAU, s: rng() * 0.8 + 0.2 })),
347:       };
348:     }
349:     ctx.save();
350:     for (const s of this.titleStars.stars) {
351:       const a = 0.18 + (Math.sin(t * s.s + s.p) * 0.5 + 0.5) * 0.55;
352:       ctx.globalAlpha = a;
353:       ctx.fillStyle = s.r > 1.3 ? '#fff3c4' : '#dfe8ff';
354:       ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, TAU); ctx.fill();
355:     }
356:     ctx.restore();
357: 
358:     // Luna / Gema Celestial.
359:     const mx = w * 0.76, my = h * 0.23;
360:     const halo = ctx.createRadialGradient(mx, my, 8, mx, my, Math.min(w, h) * 0.34);
361:     halo.addColorStop(0, 'rgba(255,231,168,0.34)');
362:     halo.addColorStop(0.35, 'rgba(255,207,106,0.12)');
363:     halo.addColorStop(1, 'rgba(255,207,106,0)');
364:     ctx.fillStyle = halo;
365:     ctx.fillRect(0, 0, w, h);
366:     ctx.save();
367:     ctx.translate(mx, my);
368:     ctx.rotate(t * 0.03);
369:     ctx.strokeStyle = 'rgba(255,231,168,0.5)';
370:     ctx.lineWidth = 1.2;
371:     for (let i = 0; i < 3; i++) {
372:       ctx.beginPath();
373:       ctx.ellipse(0, 0, 64 + i * 22, 24 + i * 10, i * 0.6 + t * 0.05, 0, TAU);
374:       ctx.stroke();
375:     }
376:     ctx.restore();
377:     const gem = ctx.createLinearGradient(mx - 22, my - 34, mx + 22, my + 34);
378:     gem.addColorStop(0, '#fffbe8');
379:     gem.addColorStop(0.5, '#ffe7a8');
380:     gem.addColorStop(1, '#b8924a');
381:     ctx.fillStyle = gem;
382:     ctx.beginPath();
383:     ctx.moveTo(mx, my - 38);
384:     ctx.lineTo(mx + 22, my - 6);
385:     ctx.lineTo(mx, my + 38);
386:     ctx.lineTo(mx - 22, my - 6);
387:     ctx.closePath();
388:     ctx.fill();
389:     ctx.strokeStyle = 'rgba(255,255,255,0.65)';
390:     ctx.lineWidth = 1;
391:     ctx.stroke();
392:     ctx.save();
393:     ctx.globalCompositeOperation = 'lighter';
394:     for (let i = 0; i < 9; i++) {
395:       const a = (i / 9) * TAU + t * 0.14;
396:       const rr = 86 + (i % 3) * 26 + Math.sin(t * 0.7 + i) * 7;
397:       star(ctx, mx + Math.cos(a) * rr, my + Math.sin(a) * rr * 0.62, 2 + (i % 2) * 1.5, '#ffe7a8', 4, t * 0.4 + i);
398:     }
399:     ctx.restore();
400: 
401:     // Montañas por capas.
402:     this.mountainLayer(0.52, '#181228', 0.18, 1.1, t);
403:     this.mountainLayer(0.62, '#241a32', 0.24, 1.5, t);
404:     this.mountainLayer(0.72, '#0f0b18', 0.3, 2.1, t);
405: 
406:     // Silueta de ciudadela.
407:     this.drawCastle(w * 0.27, h * 0.73, Math.min(w, h) * 0.0016, t);
408: 
409:     // Espada en primer plano.
410:     this.drawHeroSword(w * 0.5, h * 0.86, Math.min(w, h) * 0.0015, t);
411: 
412:     // Niebla.
413:     for (let i = 0; i < 5; i++) {
414:       const y = h * (0.55 + i * 0.09);
415:       const fg = ctx.createLinearGradient(0, y - 30, 0, y + 40);
416:       fg.addColorStop(0, 'rgba(199,164,255,0)');
417:       fg.addColorStop(0.5, `rgba(199,164,255,${0.035 + i * 0.012})`);
418:       fg.addColorStop(1, 'rgba(199,164,255,0)');
419:       ctx.fillStyle = fg;
420:       ctx.fillRect(0, y - 30 + Math.sin(t * 0.25 + i) * 10, w, 70);
421:     }
422: 
423:     // Motes flotantes.
424:     ctx.save();
425:     ctx.globalCompositeOperation = 'lighter';
426:     for (let i = 0; i < 40; i++) {
427:       const x = ((i * 137 + t * (6 + i % 5)) % (w + 60)) - 30;
428:       const y = h - ((i * 83 + t * (12 + i % 7)) % (h * 0.8));
429:       ctx.globalAlpha = 0.12 + (i % 4) * 0.05;
430:       ctx.fillStyle = i % 3 ? '#ffe7a8' : '#c7a4ff';
431:       ctx.beginPath(); ctx.arc(x, y, 1 + (i % 2), 0, TAU); ctx.fill();
432:     }
433:     ctx.restore();
434: 
435:     // Vignette final.
436:     const v = ctx.createRadialGradient(w / 2, h * 0.48, Math.min(w, h) * 0.2, w / 2, h * 0.5, Math.max(w, h) * 0.8);
437:     v.addColorStop(0, 'rgba(0,0,0,0)');
438:     v.addColorStop(1, 'rgba(0,0,0,0.72)');
439:     ctx.fillStyle = v;
440:     ctx.fillRect(0, 0, w, h);
441:   }
442: 
443:   mountainLayer(base, color, rough, speed, time) {
444:     const { ctx, w, h } = this;
445:     const y0 = h * base;
446:     ctx.save();
447:     ctx.fillStyle = color;
448:     ctx.beginPath();
449:     ctx.moveTo(0, h);
450:     ctx.lineTo(0, y0);
451:     const steps = 16;
452:     for (let i = 0; i <= steps; i++) {
453:       const x = (i / steps) * w;
454:       const n = hash2(i, Math.round(base * 100), 91);
455:       const n2 = Math.sin(i * 1.7 + speed + time * 0.01) * 0.5 + 0.5;
456:       const y = y0 - (n * 0.7 + n2 * 0.3) * h * rough;
457:       ctx.lineTo(x, y);
458:     }
459:     ctx.lineTo(w, h);
460:     ctx.closePath();
461:     ctx.fill();
462:     ctx.restore();
463:   }
464: 
465:   drawCastle(cx, baseY, scale, time) {
466:     const { ctx } = this;
467:     const s = Math.max(0.55, scale);
468:     ctx.save();
469:     ctx.translate(cx, baseY);
470:     ctx.scale(s, s);
471:     ctx.fillStyle = 'rgba(8,6,14,0.92)';
472:     // Muralla.
473:     ctx.fillRect(-120, -46, 240, 46);
474:     for (let i = 0; i < 12; i++) ctx.fillRect(-120 + i * 21, -54, 11, 9);
475:     // Torres.
476:     for (const tx of [-92, 0, 92]) {
477:       ctx.fillRect(tx - 16, -108, 32, 108);
478:       ctx.beginPath(); ctx.moveTo(tx - 22, -108); ctx.lineTo(tx, -146); ctx.lineTo(tx + 22, -108); ctx.closePath(); ctx.fill();
479:       // Ventanas encendidas.
480:       for (let i = 0; i < 3; i++) {
481:         ctx.fillStyle = `rgba(255,207,106,${0.25 + Math.sin(time * 1.2 + i + tx) * 0.12})`;
482:         ctx.fillRect(tx - 4, -92 + i * 24, 8, 11);
483:         ctx.fillStyle = 'rgba(8,6,14,0.92)';
484:       }
485:     }
486:     // Puente.
487:     ctx.fillRect(-160, -20, 320, 8);
488:     ctx.restore();
489:   }
490: 
491:   drawHeroSword(cx, baseY, scale, time) {
492:     const { ctx, w, h } = this;
493:     const s = Math.max(0.7, scale) * Math.min(w, h) / 720;
494:     ctx.save();
495:     ctx.translate(cx, baseY);
496:     ctx.scale(s, s);
497:     const glow = ctx.createRadialGradient(0, -170, 4, 0, -150, 210);
498:     glow.addColorStop(0, 'rgba(255,231,168,0.4)');
499:     glow.addColorStop(0.5, 'rgba(255,207,106,0.12)');
500:     glow.addColorStop(1, 'rgba(255,207,106,0)');
501:     ctx.fillStyle = glow;
502:     ctx.fillRect(-230, -380, 460, 440);
503:     // Hoja.
