  border: 1px solid rgba(255, 231, 168, 0.12);
  pointer-events: none; z-index: 2;
}
#creator-preview { display: block; width: 100%; height: auto; aspect-ratio: 280 / 340; }
.preview-corners::before, .preview-corners::after {
  content: '';
