  font-family: var(--font-display);
  font-size: 15px;
  letter-spacing: 0.08em;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.text-input:focus { border-color: var(--line-strong); box-shadow: 0 0 22px rgba(217, 180, 106, 0.12); }
.origin-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.origin-card {
  text-align: left;
  padding: 12px 12px 10px;
  border: 1px solid rgba(217, 180, 106, 0.18);
  background: rgba(10, 8, 18, 0.6);
  color: var(--text);
  transition: 0.2s ease;
  position: relative;
}
.origin-card:hover { border-color: var(--line-strong); background: rgba(30, 22, 42, 0.7); }
.origin-card.selected { border-color: var(--gold); background: linear-gradient(160deg, rgba(60, 44, 72, 0.8), rgba(20, 14, 30, 0.9)); box-shadow: inset 0 0 26px rgba(217, 180, 106, 0.08), 0 0 18px rgba(217, 180, 106, 0.1); }
.origin-card .oc-icon { font-size: 20px; display: block; margin-bottom: 5px; }
.origin-card strong { display: block; font-size: 11px; color: var(--gold-bright); line-height: 1.2; }
.origin-card small { display: block; margin-top: 4px; font-size: 10px; color: var(--muted); line-height: 1.25; }
.appearance-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 18px; }
.appearance-item { display: flex; flex-direction: column; gap: 5px; }
.appearance-item > span { font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }
.chip-row, .swatch-row { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  border: 1px solid rgba(217, 180, 106, 0.2);
  background: rgba(12, 9, 20, 0.7);
  color: var(--muted);
  font-size: 10px;
  padding: 4px 8px;
  letter-spacing: 0.04em;
}
.chip.selected { border-color: var(--gold); color: var(--gold-bright); background: rgba(217, 180, 106, 0.14); }
.swatch {
  width: 24px; height: 24px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.6);
  transition: transform 0.15s ease, border-color 0.15s ease;
}
.swatch:hover { transform: scale(1.12); }
.swatch.selected { border-color: var(--gold-bright); box-shadow: 0 0 12px rgba(255, 231, 168, 0.5); transform: scale(1.12); }
.toggle-item { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--muted); }
