@font-face {
  font-family: 'Cinzel';
  src: url('assets/fonts/cinzel.woff2') format('woff2');
  font-weight: 400 900;
  font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: url('assets/fonts/cormorant.woff2') format('woff2');
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Cormorant Garamond';
  src: url('assets/fonts/cormorant-italic.woff2') format('woff2');
  font-weight: 300 700;
  font-style: italic;
  font-display: swap;
}

:root {
  --ink: #08060e;
  --ink-2: #0f0b18;
  --ink-3: #171122;
  --panel: rgba(16, 12, 26, 0.86);
  --panel-solid: #120e1d;
  --line: rgba(217, 180, 106, 0.28);
  --line-strong: rgba(217, 180, 106, 0.58);
  --gold: #d9b46a;
  --gold-bright: #ffe7a8;
  --gold-deep: #8a6a2a;
  --parchment: #efe3c8;
  --text: #e8dfd0;
  --muted: #a89c8e;
  --dim: #766d63;
  --red: #ff7b7b;
  --blue: #7fb7ff;
  --green: #8fd18a;
  --violet: #c7a4ff;
  --cyan: #9fe8ff;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.62);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --font-display: 'Cinzel', 'Times New Roman', serif;
  --font-body: 'Cormorant Garamond', Georgia, serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--text);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
body {
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}
button, input { font: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }

#app {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100dvh;
  overflow: hidden;
  background: radial-gradient(circle at 50% 30%, #1a1228 0%, #08060e 70%);
}
#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  background: #08060e;
}

/* ── Tipografía ─────────────────────────────────────────────────────── */
h1, h2, h3, strong, .btn, .field-label, .eyebrow, kbd, .quest-kicker {
  font-family: var(--font-display);
  letter-spacing: 0.06em;
}
.eyebrow {
  margin: 0 0 10px;
  color: var(--gold);
  font-size: clamp(10px, 1.1vw, 13px);
  text-transform: uppercase;
  letter-spacing: 0.32em;
  opacity: 0.92;
}
h2 {
  margin: 0;
  font-size: clamp(24px, 3.2vw, 42px);
  color: var(--parchment);
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.6);
}

/* ── Botones ────────────────────────────────────────────────────────── */
.btn {
  position: relative;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(42, 31, 54, 0.9), rgba(16, 12, 26, 0.94));
